struct DuplicateRejectingJsonValue(Value);

struct DuplicateRejectingJsonValueVisitor;

impl<'de> Deserialize<'de> for DuplicateRejectingJsonValue {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        deserializer.deserialize_any(DuplicateRejectingJsonValueVisitor)
    }
}

impl<'de> Visitor<'de> for DuplicateRejectingJsonValueVisitor {
    type Value = DuplicateRejectingJsonValue;

    fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("a JSON value without duplicate object keys")
    }

    fn visit_bool<E>(self, value: bool) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::Bool(value)))
    }

    fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::Number(value.into())))
    }

    fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::Number(value.into())))
    }

    fn visit_f64<E>(self, value: f64) -> Result<Self::Value, E>
    where
        E: de::Error,
    {
        let number = serde_json::Number::from_f64(value)
            .ok_or_else(|| E::custom("JSON number must be finite"))?;
        Ok(DuplicateRejectingJsonValue(Value::Number(number)))
    }

    fn visit_str<E>(self, value: &str) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::String(
            value.to_string(),
        )))
    }

    fn visit_string<E>(self, value: String) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::String(value)))
    }

    fn visit_none<E>(self) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::Null))
    }

    fn visit_unit<E>(self) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJsonValue(Value::Null))
    }

    fn visit_some<D>(self, deserializer: D) -> Result<Self::Value, D::Error>
    where
        D: Deserializer<'de>,
    {
        DuplicateRejectingJsonValue::deserialize(deserializer)
    }

    fn visit_seq<A>(self, mut sequence: A) -> Result<Self::Value, A::Error>
    where
        A: SeqAccess<'de>,
    {
        let mut values = SensitiveJsonArray::with_capacity(
            sequence.size_hint().unwrap_or(16).min(1024),
        );
        while let Some(value) = sequence.next_element::<DuplicateRejectingJsonValue>()? {
            values.push(value.0);
        }
        Ok(DuplicateRejectingJsonValue(Value::Array(values.into_vec())))
    }

    fn visit_map<A>(self, mut object: A) -> Result<Self::Value, A::Error>
    where
        A: MapAccess<'de>,
    {
        let mut values = SensitiveJsonObject::new();
        while let Some(key) = object.next_key::<String>()? {
            let mut key = Zeroizing::new(key);
            if values.contains_key(key.as_str()) {
                return Err(de::Error::custom("duplicate_json_object_key"));
            }
            let value = object.next_value::<DuplicateRejectingJsonValue>()?;
            values.insert(std::mem::take(&mut *key), value.0);
        }
        Ok(DuplicateRejectingJsonValue(Value::Object(values.into_map())))
    }
}

fn strict_json_value_from_slice(input: &[u8]) -> Result<Value, serde_json::Error> {
    if contains_integer_negative_zero(input) {
        return Err(<serde_json::Error as de::Error>::custom(
            "integer -0 is not permitted in strict JSON",
        ));
    }
    let mut deserializer = serde_json::Deserializer::from_slice(input);
    let value = SensitiveJsonValue::new(
        DuplicateRejectingJsonValue::deserialize(&mut deserializer)?.0,
    );
    deserializer.end()?;
    Ok(value.into_value())
}

#[derive(Clone, Copy, Default, PartialEq, Eq)]
enum IntegerNegativeZeroState {
    #[default]
    None,
    Minus,
    NegativeZero,
}

#[derive(Default)]
struct IntegerNegativeZeroDetector {
    in_string: bool,
    escaped: bool,
    state: IntegerNegativeZeroState,
}

impl IntegerNegativeZeroDetector {
    fn scan(&mut self, input: &[u8]) -> bool {
        input.iter().copied().any(|byte| self.scan_byte(byte))
    }

    fn finish(&self) -> bool {
        !self.in_string && self.state == IntegerNegativeZeroState::NegativeZero
    }

    fn scan_byte(&mut self, byte: u8) -> bool {
        if self.in_string {
            if self.escaped {
                self.escaped = false;
            } else if byte == b'\\' {
                self.escaped = true;
            } else if byte == b'"' {
                self.in_string = false;
            }
            return false;
        }

        match self.state {
            IntegerNegativeZeroState::None => self.scan_value_start(byte),
            IntegerNegativeZeroState::Minus => {
                self.state = IntegerNegativeZeroState::None;
                if byte == b'0' {
                    self.state = IntegerNegativeZeroState::NegativeZero;
                    false
                } else {
                    self.scan_value_start(byte)
                }
            }
            IntegerNegativeZeroState::NegativeZero => {
                self.state = IntegerNegativeZeroState::None;
                if json_ws(byte) || matches!(byte, b',' | b']' | b'}') {
                    true
                } else if matches!(byte, b'.' | b'e' | b'E') {
                    false
                } else {
                    self.scan_value_start(byte)
                }
            }
        }
    }

    fn scan_value_start(&mut self, byte: u8) -> bool {
        if byte == b'"' {
            self.in_string = true;
            self.escaped = false;
        } else if byte == b'-' {
            self.state = IntegerNegativeZeroState::Minus;
        }
        false
    }
}

fn contains_integer_negative_zero(input: &[u8]) -> bool {
    let mut detector = IntegerNegativeZeroDetector::default();
    detector.scan(input) || detector.finish()
}

struct StrictJsonRead<R> {
    inner: R,
    negative_zero: IntegerNegativeZeroDetector,
    rejected: bool,
}

impl<R> StrictJsonRead<R> {
    fn new(inner: R) -> Self {
        Self {
            inner,
            negative_zero: IntegerNegativeZeroDetector::default(),
            rejected: false,
        }
    }

    fn negative_zero_error() -> io::Error {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "integer -0 is not permitted in strict JSON",
        )
    }
}

impl<R: Read> Read for StrictJsonRead<R> {
    fn read(&mut self, out: &mut [u8]) -> io::Result<usize> {
        if out.is_empty() {
            return Ok(0);
        }
        if self.rejected {
            return Err(Self::negative_zero_error());
        }
        let read = self.inner.read(out)?;
        let rejected = if read == 0 {
            self.negative_zero.finish()
        } else {
            self.negative_zero.scan(&out[..read])
        };
        if rejected {
            self.rejected = true;
            return Err(Self::negative_zero_error());
        }
        Ok(read)
    }
}

fn strict_json_value_from_str(input: &str) -> Result<Value, serde_json::Error> {
    strict_json_value_from_slice(input.as_bytes())
}

fn strict_json_from_slice<T>(input: &[u8]) -> Result<T, serde_json::Error>
where
    T: DeserializeOwned,
{
    serde_json::from_value(strict_json_value_from_slice(input)?)
}

