#[derive(Clone, Deserialize)]
struct DecisionRequest {
    #[serde(rename = "clientIp")]
    client_ip: Option<String>,
    method: String,
    url: String,
    #[serde(default)]
    headers: BTreeMap<String, String>,
    #[serde(default)]
    body: String,
    #[serde(default, rename = "bodySha256")]
    body_sha256: Option<String>,
    #[serde(skip)]
    forwarded_body_length: Option<u64>,
    #[serde(skip)]
    forwarded_body_utf8_valid: Option<bool>,
    #[serde(default, rename = "credentialMetadata")]
    credential_metadata: BTreeMap<String, BTreeMap<String, Value>>,
    #[serde(skip)]
    gmail_proofs: Vec<SensitiveString>,
    #[serde(skip)]
    client_request_digest: Option<String>,
}

impl Drop for DecisionRequest {
    fn drop(&mut self) {
        if let Some(client_ip) = self.client_ip.as_mut() {
            client_ip.zeroize();
        }
        self.method.zeroize();
        self.url.zeroize();
        self.body.zeroize();
        if let Some(body_sha256) = self.body_sha256.as_mut() {
            body_sha256.zeroize();
        }
        zeroize_string_map(&mut self.headers);
        let metadata = std::mem::take(&mut self.credential_metadata);
        for (mut credential_id, fields) in metadata {
            credential_id.zeroize();
            for (mut key, mut value) in fields {
                key.zeroize();
                zeroize_json_value(&mut value);
            }
        }
        if let Some(client_request_digest) = self.client_request_digest.as_mut() {
            client_request_digest.zeroize();
        }
    }
}

