type SensitiveReleasedHeaders = Vec<(String, SensitiveString)>;
type SensitiveRawPolicyHeaders = BTreeMap<String, Vec<SensitiveString>>;

fn zeroize_json_value(value: &mut Value) {
    match value {
        Value::String(text) => text.zeroize(),
        Value::Array(items) => {
            for item in items.iter_mut() {
                zeroize_json_value(item);
            }
            items.clear();
        }
        Value::Object(object) => {
            let entries = std::mem::take(object);
            for (mut key, mut item) in entries {
                key.zeroize();
                zeroize_json_value(&mut item);
            }
        }
        Value::Bool(boolean) => *boolean = false,
        Value::Number(_) => {
            *value = Value::Null;
        }
        Value::Null => {}
    }
}

fn zeroize_string_map(values: &mut BTreeMap<String, String>) {
    let values = std::mem::take(values);
    for (mut key, mut value) in values {
        key.zeroize();
        value.zeroize();
    }
}

fn replace_string_map(
    target: &mut BTreeMap<String, String>,
    replacement: BTreeMap<String, String>,
) {
    let mut original = std::mem::replace(target, replacement);
    zeroize_string_map(&mut original);
}

fn take_sensitive_prefix(buffer: &mut Vec<u8>, length: usize) -> Zeroizing<Vec<u8>> {
    let length = length.min(buffer.len());
    let mut prefix = Zeroizing::new(Vec::with_capacity(length));
    prefix.extend_from_slice(&buffer[..length]);
    let remaining = buffer.len() - length;
    buffer.copy_within(length.., 0);
    buffer[remaining..].zeroize();
    buffer.truncate(remaining);
    prefix
}

fn discard_sensitive_prefix(buffer: &mut Vec<u8>, length: usize) {
    let mut discarded = take_sensitive_prefix(buffer, length);
    discarded.zeroize();
}

struct SensitiveJsonValue {
    value: Value,
}

impl SensitiveJsonValue {
    fn new(value: Value) -> Self {
        Self { value }
    }

    fn into_value(mut self) -> Value {
        std::mem::replace(&mut self.value, Value::Null)
    }
}

impl Deref for SensitiveJsonValue {
    type Target = Value;

    fn deref(&self) -> &Self::Target {
        &self.value
    }
}

impl DerefMut for SensitiveJsonValue {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.value
    }
}

impl Drop for SensitiveJsonValue {
    fn drop(&mut self) {
        zeroize_json_value(&mut self.value);
        #[cfg(test)]
        SENSITIVE_JSON_DROP_ZEROIZE_COUNT.fetch_add(1, Ordering::Relaxed);
    }
}

fn sensitive_json_value_from_slice(input: &[u8]) -> Result<SensitiveJsonValue, serde_json::Error> {
    strict_json_value_from_slice(input).map(SensitiveJsonValue::new)
}

fn sensitive_json_value_from_str(input: &str) -> Result<SensitiveJsonValue, serde_json::Error> {
    sensitive_json_value_from_slice(input.as_bytes())
}

fn replace_sensitive_json_value(target: &mut Value, replacement: Value) {
    let mut original = std::mem::replace(target, replacement);
    zeroize_json_value(&mut original);
}

struct SensitiveJsonQueue {
    values: VecDeque<Value>,
}

impl SensitiveJsonQueue {
    fn from_vec(values: Vec<Value>) -> Self {
        Self {
            values: values.into(),
        }
    }

    fn len(&self) -> usize {
        self.values.len()
    }

    fn pop_front(&mut self) -> Option<Value> {
        self.values.pop_front()
    }
}

impl Drop for SensitiveJsonQueue {
    fn drop(&mut self) {
        for value in &mut self.values {
            zeroize_json_value(value);
        }
        self.values.clear();
    }
}

struct SensitiveJsonArray {
    values: Vec<Value>,
}

impl SensitiveJsonArray {
    fn with_capacity(capacity: usize) -> Self {
        Self {
            values: Vec::with_capacity(capacity),
        }
    }

    fn push(&mut self, value: Value) {
        self.values.push(value);
    }

    fn into_vec(mut self) -> Vec<Value> {
        std::mem::take(&mut self.values)
    }
}

impl Drop for SensitiveJsonArray {
    fn drop(&mut self) {
        for value in &mut self.values {
            zeroize_json_value(value);
        }
        self.values.clear();
    }
}

struct SensitiveJsonObject {
    values: Map<String, Value>,
}

impl SensitiveJsonObject {
    fn new() -> Self {
        Self { values: Map::new() }
    }

    fn contains_key(&self, key: &str) -> bool {
        self.values.contains_key(key)
    }

    fn insert(&mut self, key: String, value: Value) {
        self.values.insert(key, value);
    }

    fn as_map_mut(&mut self) -> &mut Map<String, Value> {
        &mut self.values
    }

    fn into_map(mut self) -> Map<String, Value> {
        std::mem::take(&mut self.values)
    }
}

impl Drop for SensitiveJsonObject {
    fn drop(&mut self) {
        let values = std::mem::take(&mut self.values);
        for (mut key, mut value) in values {
            key.zeroize();
            zeroize_json_value(&mut value);
        }
    }
}

struct SensitiveFormPairs {
    values: Vec<(String, String)>,
}

impl SensitiveFormPairs {
    fn new() -> Self {
        Self {
            values: Vec::with_capacity(8),
        }
    }

    fn push(&mut self, pair: (String, String)) {
        self.values.push(pair);
    }

    fn as_slice(&self) -> &[(String, String)] {
        &self.values
    }

    fn into_vec(mut self) -> Vec<(String, String)> {
        std::mem::take(&mut self.values)
    }
}

impl Drop for SensitiveFormPairs {
    fn drop(&mut self) {
        for (key, value) in &mut self.values {
            key.zeroize();
            value.zeroize();
        }
        self.values.clear();
    }
}

