fn exact_completion_recovery_required() -> Value {
    json!({
        "error":"release_authorization_exact_completion_recovery_required",
        "providerOperationMayHaveCommitted":true,
        "retryProviderRequest":false,
    })
}

fn provider_operation_outcome_unknown() -> Value {
    json!({
        "error":"provider_operation_outcome_unknown",
        "providerOperationMayHaveCommitted":true,
        "retryProviderRequest":false,
    })
}

fn gate_durable_buffered_release(
    result: ForwardResult,
    completion: Result<bool, String>,
) -> Result<ForwardResult, Value> {
    let ForwardResult::Buffered(mut candidate) = result else {
        return Err(json!({"error":"durable_policy_streaming_release_forbidden"}));
    };
    match completion {
        Ok(true) => Ok(ForwardResult::buffered(candidate)),
        Ok(false) => {
            candidate.zeroize();
            Err(json!({"error":"durable_policy_response_denied"}))
        }
        Err(_) => {
            candidate.zeroize();
            Err(exact_completion_recovery_required())
        }
    }
}

