fn streaming_request_authorization_disabled() -> bool {
    #[cfg(test)]
    if FORWARDER_POST_DECISION_FAILURE.with(|failure| {
        matches!(
            failure.borrow().as_deref(),
            Some("streaming") | Some("intercepted-connect")
        )
    }) {
        return false;
    }
    !REQUEST_BODY_STREAMING_AVAILABLE
}

struct UpstreamDispatchAuthority {
    state: Mutex<UpstreamDispatchAuthorityState>,
    changed: Condvar,
}

struct UpstreamDispatchAuthorityState {
    active_sends: u64,
    waiting_sends: u64,
    waiting_mutations: u64,
    mutation_active: bool,
    next_send_ticket: u64,
    send_admit_through: u64,
    send_cohort_remaining: u64,
    next_mutation_ticket: u64,
    serving_mutation_ticket: u64,
    cancelled_mutation_tickets: HashSet<u64>,
}

struct UpstreamDispatchPermit<'a> {
    authority: &'a UpstreamDispatchAuthority,
}

impl Drop for UpstreamDispatchPermit<'_> {
    fn drop(&mut self) {
        let mut state = self
            .authority
            .state
            .lock()
            .expect("upstream dispatch authority lock poisoned");
        state.active_sends = state
            .active_sends
            .checked_sub(1)
            .expect("upstream active send count underflow");
        let notify = state.active_sends == 0;
        drop(state);
        if notify {
            self.authority.changed.notify_all();
        }
    }
}

struct UpstreamDispatchMutation<'a> {
    authority: &'a UpstreamDispatchAuthority,
}

impl Drop for UpstreamDispatchMutation<'_> {
    fn drop(&mut self) {
        let mut state = self
            .authority
            .state
            .lock()
            .expect("upstream dispatch authority lock poisoned");
        state.mutation_active = false;
        state.serving_mutation_ticket = state
            .serving_mutation_ticket
            .checked_add(1)
            .expect("upstream mutation ticket exhausted");
        loop {
            let ticket = state.serving_mutation_ticket;
            if !state.cancelled_mutation_tickets.remove(&ticket) { break; }
            state.serving_mutation_ticket = ticket.checked_add(1).expect("upstream mutation ticket exhausted");
        }
        if state.waiting_sends != 0 {
            state.send_admit_through = state
                .next_send_ticket
                .checked_sub(1)
                .expect("upstream send ticket underflow");
            state.send_cohort_remaining = state.waiting_sends;
        } else {
            state.send_cohort_remaining = 0;
        }
        drop(state);
        self.authority.changed.notify_all();
    }
}

impl UpstreamDispatchAuthority {
    fn new() -> Self {
        Self {
            state: Mutex::new(UpstreamDispatchAuthorityState {
                active_sends: 0,
                waiting_sends: 0,
                waiting_mutations: 0,
                mutation_active: false,
                next_send_ticket: 1,
                send_admit_through: 0,
                send_cohort_remaining: 0,
                next_mutation_ticket: 1,
                serving_mutation_ticket: 1,
                cancelled_mutation_tickets: HashSet::new(),
            }),
            changed: Condvar::new(),
        }
    }

    fn acquire_send(&self) -> UpstreamDispatchPermit<'_> {
        let mut state = self
            .state
            .lock()
            .expect("upstream dispatch authority lock poisoned");
        let ticket = state.next_send_ticket;
        state.next_send_ticket = state
            .next_send_ticket
            .checked_add(1)
            .expect("upstream send ticket exhausted");
        state.waiting_sends = state
            .waiting_sends
            .checked_add(1)
            .expect("upstream waiting send count exhausted");
        while state.mutation_active
            || (state.waiting_mutations != 0
                && !(state.send_cohort_remaining != 0 && ticket <= state.send_admit_through))
        {
            state = self
                .changed
                .wait(state)
                .expect("upstream dispatch authority lock poisoned");
        }
        state.waiting_sends = state
            .waiting_sends
            .checked_sub(1)
            .expect("upstream waiting send count underflow");
        if state.send_cohort_remaining != 0 && ticket <= state.send_admit_through {
            state.send_cohort_remaining = state
                .send_cohort_remaining
                .checked_sub(1)
                .expect("upstream send cohort count underflow");
        }
        state.active_sends = state
            .active_sends
            .checked_add(1)
            .expect("upstream active send count exhausted");
        drop(state);
        UpstreamDispatchPermit { authority: self }
    }

    fn begin_mutation(&self) -> UpstreamDispatchMutation<'_> {
        self.begin_mutation_until(None).expect("unbounded upstream mutation cannot expire")
    }

    fn begin_mutation_on_deadline(&self, deadline: Instant) -> Result<UpstreamDispatchMutation<'_>, String> {
        self.begin_mutation_until(Some(deadline))
    }

    fn begin_mutation_until(&self, deadline: Option<Instant>) -> Result<UpstreamDispatchMutation<'_>, String> {
        let mut state = self
            .state
            .lock()
            .expect("upstream dispatch authority lock poisoned");
        let ticket = state.next_mutation_ticket;
        state.next_mutation_ticket = state
            .next_mutation_ticket
            .checked_add(1)
            .expect("upstream mutation ticket exhausted");
        state.waiting_mutations = state
            .waiting_mutations
            .checked_add(1)
            .expect("upstream waiting mutation count exhausted");
        while state.active_sends != 0
            || state.mutation_active
            || state.send_cohort_remaining != 0
            || ticket != state.serving_mutation_ticket
        {
            if let Some(deadline) = deadline {
                let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
                    state.waiting_mutations -= 1;
                    state.cancelled_mutation_tickets.insert(ticket);
                    loop {
                        let next = state.serving_mutation_ticket;
                        if !state.cancelled_mutation_tickets.remove(&next) { break; }
                        state.serving_mutation_ticket = next.checked_add(1).expect("upstream mutation ticket exhausted");
                    }
                    drop(state);
                    self.changed.notify_all();
                    return Err("currentness drain exceeded its original deadline; no acknowledgement".to_owned());
                };
                state = self.changed.wait_timeout(state, remaining)
                    .expect("upstream dispatch authority lock poisoned").0;
            } else {
                state = self.changed.wait(state).expect("upstream dispatch authority lock poisoned");
            }
        }
        state.waiting_mutations = state
            .waiting_mutations
            .checked_sub(1)
            .expect("upstream waiting mutation count underflow");
        state.mutation_active = true;
        drop(state);
        Ok(UpstreamDispatchMutation { authority: self })
    }
}

// Native custody retains its live NSM-backed owner. A public certificate or a
// previously generated TLS configuration cannot replace that owner.
enum MitmAuthority {
    Pem(TlsAuthorityV1),
    Native(EnclaveRuntimeIdentityV1),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MitmAuthorityIdentity {
    Pem([u8; 32]),
    Native([u8; 32]),
}

struct LeafConfigEntry {
    authority: MitmAuthorityIdentity,
    validity: LeafConfigValidity,
    config: Arc<ServerConfig>,
}

enum LeafConfigValidity {
    Development {
        not_before: OffsetDateTime,
        not_after: OffsetDateTime,
    },
    NativeOriginalScope,
}

impl LeafConfigValidity {
    fn permits_cache_hit(&self, identity: MitmAuthorityIdentity, now: OffsetDateTime) -> bool {
        match (self, identity) {
            (Self::Development { not_before, not_after }, MitmAuthorityIdentity::Pem(_)) => {
                // Renew development leaves before expiry, leaving time for the
                // pending TLS handshake. Also reject reuse after clock rollback
                // outside this certificate's actual not-before interval.
                *not_before <= now && now < *not_after - TimeDuration::minutes(5)
            }
            // Native leaves retain their original issuer interval. This only
            // permits lookup: the actual owner must still verify its live scope
            // on every cache hit. Never apply development renewal to that owner.
            (Self::NativeOriginalScope, MitmAuthorityIdentity::Native(_)) => true,
            _ => false,
        }
    }
}

impl MitmAuthority {
    fn cache_identity(&self) -> MitmAuthorityIdentity {
        match self {
            Self::Pem(authority) => MitmAuthorityIdentity::Pem(
                Sha256::digest(authority.certificate_der()).into()),
            Self::Native(authority) => MitmAuthorityIdentity::Native(
                Sha256::digest(authority.ca_certificate_der()).into()),
        }
    }

    fn verify_current_tls_scope(&mut self) -> Result<(), String> {
        if let Self::Native(authority) = self {
            let deadline = authority.deadline();
            authority.verify_tls_scope(OffsetDateTime::now_utc(), deadline)?;
        }
        Ok(())
    }
}

