struct CredentialLeaseFlight {
    result: Mutex<Option<Result<(), String>>>,
    completed: Condvar,
    #[cfg(test)]
    follower_wait_hook: Mutex<Option<mpsc::SyncSender<()>>>,
}

#[cfg(test)]
impl CredentialLeaseFlight {
    fn observe_follower_wait(&self) {
        if let Some(sender) = self
            .follower_wait_hook
            .lock()
            .expect("credential lease follower wait hook mutex poisoned")
            .take()
        {
            sender
                .send(())
                .expect("credential lease follower wait observer closed");
        }
    }
}

struct CredentialLeaseFlightLeaderGuard<'a> {
    state: &'a GateState,
    key: CredentialLeaseGenerationKey,
    flight: Arc<CredentialLeaseFlight>,
    published: bool,
}

impl<'a> CredentialLeaseFlightLeaderGuard<'a> {
    fn new(
        state: &'a GateState,
        key: CredentialLeaseGenerationKey,
        flight: Arc<CredentialLeaseFlight>,
    ) -> Self {
        Self {
            state,
            key,
            flight,
            published: false,
        }
    }

    fn publish(&mut self, result: Result<(), String>) {
        let mut published = self
            .flight
            .result
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        *published = Some(result);
        drop(published);
        self.flight.completed.notify_all();
        let mut flights = self
            .state
            .credential_lease_flights
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if flights
            .get(&self.key)
            .is_some_and(|active| Arc::ptr_eq(active, &self.flight))
        {
            flights.remove(&self.key);
        }
        self.published = true;
    }
}

impl Drop for CredentialLeaseFlightLeaderGuard<'_> {
    fn drop(&mut self) {
        if !self.published {
            self.publish(Err(
                "credential lease singleflight leader terminated before publication".to_string(),
            ));
        }
    }
}

