impl CredentialLeaseGenerationKey {
    fn new(
        snapshot: &Snapshot,
        scope: &CredentialLeaseScope,
        purpose: CredentialLeasePurpose,
        release_authorization: Option<&CredentialLeaseReleaseAuthorization>,
    ) -> Self {
        Self::new_bound(snapshot, scope, purpose, None, release_authorization)
    }

    fn new_bound(
        snapshot: &Snapshot,
        scope: &CredentialLeaseScope,
        purpose: CredentialLeasePurpose,
        request_authority: Option<&CredentialLeaseRequestAuthority>,
        release_authorization: Option<&CredentialLeaseReleaseAuthorization>,
    ) -> Self {
        Self {
            scope: scope.clone(),
            snapshot_epoch: snapshot.epoch,
            policy_hash: snapshot.hash.clone(),
            trust_generation: snapshot.trust_generation,
            purpose,
            request_authority_sha256: request_authority
                .map(credential_lease_request_authority_sha256),
            release_authorization: release_authorization.cloned(),
        }
    }
}

struct CredentialLeaseRenewalTask {
    snapshot: Arc<Snapshot>,
    key: CredentialLeaseGenerationKey,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct CredentialLeaseBackgroundCandidate {
    scope: CredentialLeaseScope,
    purpose: CredentialLeasePurpose,
}

struct CredentialLeaseRenewalPendingGuard {
    pending: Arc<Mutex<HashSet<CredentialLeaseGenerationKey>>>,
    state: Arc<GateState>,
    key: CredentialLeaseGenerationKey,
}

impl Drop for CredentialLeaseRenewalPendingGuard {
    fn drop(&mut self) {
        self.pending
            .lock()
            // Cleanup must not panic a second time during worker/queue unwind.
            // Recover only to remove this owned registration; the mutex stays
            // poisoned so ordinary work continues to fail closed.
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .remove(&self.key);
        self.state
            .credential_lease_renewal_queued
            .fetch_sub(1, Ordering::Relaxed);
    }
}

