struct DeadlineIo<T> {
    inner: T,
    read_budget: Duration,
    read_started: Option<Instant>,
    write_budget: Duration,
    write_started: Option<Instant>,
    terminal_write_deadline: Option<Instant>,
    operation_deadline: Option<Instant>,
}

trait TerminalDeadlineWrite: Write {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>);
}

trait ConfigureIoTimeout {
    fn configure_read_timeout(&self, timeout: Duration) -> io::Result<()>;
    fn configure_write_timeout(&self, timeout: Duration) -> io::Result<()>;
}

enum GateSocket {
    Tcp(TcpStream),
    Vsock(VsockStreamV1),
}

impl GateSocket {
    fn client_ip(&self) -> Option<String> {
        match self {
            Self::Tcp(stream) => stream.peer_addr().ok().map(|address| address.ip().to_string()),
            // A transport CID is not an IP or an authenticated principal. CIDR
            // policy must see absence, never a manufactured parent/loopback IP.
            Self::Vsock(_) => None,
        }
    }

    fn clone_development_tcp_reader(&self) -> io::Result<TcpStream> {
        match self {
            Self::Tcp(stream) => stream.try_clone(),
            Self::Vsock(_) => Err(io::Error::new(io::ErrorKind::Unsupported,
                "vsock has no development raw-reader clone")),
        }
    }
}

impl ConfigureIoTimeout for GateSocket {
    fn configure_read_timeout(&self, timeout: Duration) -> io::Result<()> {
        match self {
            Self::Tcp(stream) => stream.set_read_timeout(Some(timeout)),
            Self::Vsock(stream) => stream.set_read_timeout(Some(timeout)),
        }
    }

    fn configure_write_timeout(&self, timeout: Duration) -> io::Result<()> {
        match self {
            Self::Tcp(stream) => stream.set_write_timeout(Some(timeout)),
            Self::Vsock(stream) => stream.set_write_timeout(Some(timeout)),
        }
    }
}

impl Read for GateSocket {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        match self { Self::Tcp(stream) => stream.read(buffer), Self::Vsock(stream) => stream.read(buffer) }
    }
}

impl Write for GateSocket {
    fn write(&mut self, buffer: &[u8]) -> io::Result<usize> {
        match self { Self::Tcp(stream) => stream.write(buffer), Self::Vsock(stream) => stream.write(buffer) }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self { Self::Tcp(stream) => stream.flush(), Self::Vsock(stream) => stream.flush() }
    }
}

impl ConfigureIoTimeout for TcpStream {
    fn configure_read_timeout(&self, timeout: Duration) -> io::Result<()> {
        self.set_read_timeout(Some(timeout))
    }

    fn configure_write_timeout(&self, timeout: Duration) -> io::Result<()> {
        self.set_write_timeout(Some(timeout))
    }
}

impl<T> ConfigureIoTimeout for Cursor<T> {
    fn configure_read_timeout(&self, _timeout: Duration) -> io::Result<()> {
        Ok(())
    }

    fn configure_write_timeout(&self, _timeout: Duration) -> io::Result<()> {
        Ok(())
    }
}

impl<T> DeadlineIo<T> {
    fn new(inner: T, read_budget: Duration, write_budget: Duration) -> Self {
        Self {
            inner,
            read_budget,
            read_started: None,
            write_budget,
            write_started: None,
            terminal_write_deadline: None,
            operation_deadline: None,
        }
    }

    fn reset_read_deadline(&mut self, budget: Duration) {
        self.read_budget = budget;
        self.read_started = None;
    }

    fn reset_write_deadline(&mut self, budget: Duration) {
        self.write_budget = budget;
        self.write_started = None;
    }

    fn phase_remaining(started: &mut Option<Instant>, budget: Duration) -> Option<Duration> {
        let started = started.get_or_insert_with(Instant::now);
        budget.checked_sub(started.elapsed())
    }

    fn restrict_operation_deadline(&mut self, deadline: Instant) {
        self.operation_deadline = Some(self.operation_deadline.map_or(deadline,
            |original| original.min(deadline)));
    }

    fn check_operation_deadline(&self) -> io::Result<()> {
        if self.operation_deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            return Err(io::Error::new(io::ErrorKind::TimedOut,
                "absolute connection operation deadline exceeded"));
        }
        Ok(())
    }

    fn read_remaining(&mut self) -> Option<Duration> {
        let remaining = Self::phase_remaining(&mut self.read_started, self.read_budget)?;
        match self.operation_deadline {
            Some(deadline) => Some(remaining.min(deadline.checked_duration_since(Instant::now())?)),
            None => Some(remaining),
        }
    }

    fn write_remaining(&mut self) -> Option<Duration> {
        let mut phase_remaining = Self::phase_remaining(&mut self.write_started, self.write_budget)?;
        if let Some(deadline) = self.operation_deadline {
            phase_remaining = phase_remaining.min(deadline.checked_duration_since(Instant::now())?);
        }
        match self.terminal_write_deadline {
            Some(deadline) => {
                Some(phase_remaining.min(deadline.checked_duration_since(Instant::now())?))
            }
            None => Some(phase_remaining),
        }
    }
}

impl<T: ConfigureIoTimeout + Write> TerminalDeadlineWrite for DeadlineIo<T> {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        self.terminal_write_deadline = deadline;
    }
}

impl<T: ConfigureIoTimeout + Read + Write> TerminalDeadlineWrite
    for StreamOwned<ServerConnection, DeadlineIo<T>> {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        self.sock.set_terminal_write_deadline(deadline);
    }
}

#[cfg(test)]
impl TerminalDeadlineWrite for Vec<u8> {
    fn set_terminal_write_deadline(&mut self, _deadline: Option<Instant>) {}
}

impl<T: ConfigureIoTimeout + Read> Read for DeadlineIo<T> {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        loop {
            let Some(remaining) = self.read_remaining()
            else {
                return Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    "absolute request read deadline exceeded",
                ));
            };
            self.inner
                .configure_read_timeout(remaining.min(SOCKET_IO_SLICE))?;
            match self.inner.read(buffer) {
                Err(err)
                    if matches!(
                        err.kind(),
                        io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
                    ) =>
                {
                    continue;
                }
                Ok(read) => {
                    if self.read_remaining().is_none() {
                        return Err(io::Error::new(
                            io::ErrorKind::TimedOut,
                            "absolute request read deadline exceeded",
                        ));
                    }
                    return Ok(read);
                }
                Err(err) => return Err(err),
            }
        }
    }
}

impl<T: ConfigureIoTimeout + Write> Write for DeadlineIo<T> {
    fn write(&mut self, buffer: &[u8]) -> io::Result<usize> {
        let Some(remaining) = self.write_remaining() else {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "absolute response write deadline exceeded",
            ));
        };
        self.inner
            .configure_write_timeout(remaining.min(SOCKET_IO_SLICE))?;
        match self.inner.write(buffer) {
            Err(err)
                if matches!(
                    err.kind(),
                    io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
                ) =>
            {
                if self.write_remaining().is_none() {
                    return Err(io::Error::new(
                        io::ErrorKind::TimedOut,
                        "absolute response write deadline exceeded",
                    ));
                }
                Err(io::Error::new(
                    io::ErrorKind::Interrupted,
                    "response write slice elapsed",
                ))
            }
            Ok(written) => {
                if self.write_remaining().is_none() {
                    return Err(io::Error::new(
                        io::ErrorKind::TimedOut,
                        "absolute response write deadline exceeded",
                    ));
                }
                Ok(written)
            }
            Err(err) => Err(err),
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        let Some(remaining) = self.write_remaining() else {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "absolute response write deadline exceeded",
            ));
        };
        self.inner
            .configure_write_timeout(remaining.min(SOCKET_IO_SLICE))?;
        match self.inner.flush() {
            Err(err)
                if matches!(
                    err.kind(),
                    io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
                ) =>
            {
                if self.write_remaining().is_none() {
                    return Err(io::Error::new(
                        io::ErrorKind::TimedOut,
                        "absolute response write deadline exceeded",
                    ));
                }
                Err(io::Error::new(
                    io::ErrorKind::Interrupted,
                    "response flush slice elapsed",
                ))
            }
            Ok(()) => {
                if self.write_remaining().is_none() {
                    return Err(io::Error::new(
                        io::ErrorKind::TimedOut,
                        "absolute response write deadline exceeded",
                    ));
                }
                Ok(())
            }
            Err(err) => Err(err),
        }
    }
}

/// Constructed only with the configuration actually used for this handshake.
/// Keeping it beside the connection avoids treating a later configuration
/// argument as evidence of which trust store created that connection.
struct RetainedProxyIngressTls {
    stream: StreamOwned<ServerConnection, DeadlineIo<GateSocket>>,
    configuration: Arc<ProxyIngressTlsConfig>,
}

impl std::ops::Deref for RetainedProxyIngressTls {
    type Target = StreamOwned<ServerConnection, DeadlineIo<GateSocket>>;
    fn deref(&self) -> &Self::Target { &self.stream }
}

impl std::ops::DerefMut for RetainedProxyIngressTls {
    fn deref_mut(&mut self) -> &mut Self::Target { &mut self.stream }
}

impl Read for RetainedProxyIngressTls {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> { self.stream.read(buffer) }
}

impl Write for RetainedProxyIngressTls {
    fn write(&mut self, buffer: &[u8]) -> io::Result<usize> { self.stream.write(buffer) }
    fn flush(&mut self) -> io::Result<()> { self.stream.flush() }
}

impl TerminalDeadlineWrite for RetainedProxyIngressTls {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        self.stream.set_terminal_write_deadline(deadline);
    }
}

enum DirectProxyStream {
    DevelopmentRaw(DeadlineIo<GateSocket>),
    MutualTls(RetainedProxyIngressTls),
}

impl DirectProxyStream {
    fn native_enrollment_tls_config(&self) -> Option<&Arc<ProxyIngressTlsConfig>> {
        match self {
            Self::MutualTls(tls) => Some(&tls.configuration),
            Self::DevelopmentRaw(_) => None,
        }
    }

    // Only the explicit attestation-to-CONNECT path installs this cap. Phase
    // resets and terminal-write changes cannot widen or remove it afterward.
    fn restrict_operation_deadline(&mut self, deadline: Instant) {
        match self {
            Self::DevelopmentRaw(stream) => stream.restrict_operation_deadline(deadline),
            Self::MutualTls(stream) => stream.sock.restrict_operation_deadline(deadline),
        }
    }

    fn check_operation_deadline(&self) -> io::Result<()> {
        match self {
            Self::DevelopmentRaw(stream) => stream.check_operation_deadline(),
            Self::MutualTls(stream) => stream.sock.check_operation_deadline(),
        }
    }

    fn reset_read_deadline(&mut self, budget: Duration) {
        match self {
            Self::DevelopmentRaw(stream) => stream.reset_read_deadline(budget),
            Self::MutualTls(stream) => stream.sock.reset_read_deadline(budget),
        }
    }

    fn reset_write_deadline(&mut self, budget: Duration) {
        match self {
            Self::DevelopmentRaw(stream) => stream.reset_write_deadline(budget),
            Self::MutualTls(stream) => stream.sock.reset_write_deadline(budget),
        }
    }

    fn clone_raw_reader(&self) -> io::Result<TcpStream> {
        match self {
            Self::DevelopmentRaw(stream) => stream.inner.clone_development_tcp_reader(),
            Self::MutualTls(_) => Err(io::Error::new(
                io::ErrorKind::Unsupported,
                "outer TLS transport cannot be cloned for absolute-form streaming",
            )),
        }
    }

    fn is_mutual_tls(&self) -> bool {
        matches!(self, Self::MutualTls(_))
    }
}

impl Read for DirectProxyStream {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        self.check_operation_deadline()?;
        let result = match self {
            Self::DevelopmentRaw(stream) => stream.read(buffer),
            Self::MutualTls(stream) => stream.read(buffer),
        };
        // rustls may satisfy this read from decrypted buffered plaintext
        // without reaching DeadlineIo, so the outer owner also checks it.
        self.check_operation_deadline()?;
        result
    }
}

impl Write for DirectProxyStream {
    fn write(&mut self, buffer: &[u8]) -> io::Result<usize> {
        self.check_operation_deadline()?;
        let result = match self {
            Self::DevelopmentRaw(stream) => stream.write(buffer),
            Self::MutualTls(stream) => stream.write(buffer),
        };
        self.check_operation_deadline()?;
        result
    }

    fn flush(&mut self) -> io::Result<()> {
        self.check_operation_deadline()?;
        let result = match self {
            Self::DevelopmentRaw(stream) => stream.flush(),
            Self::MutualTls(stream) => stream.flush(),
        };
        self.check_operation_deadline()?;
        result
    }
}

impl TerminalDeadlineWrite for DirectProxyStream {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        match self {
            Self::DevelopmentRaw(stream) => stream.set_terminal_write_deadline(deadline),
            Self::MutualTls(stream) => stream.sock.set_terminal_write_deadline(deadline),
        }
    }
}

impl TerminalDeadlineWrite for StreamOwned<ServerConnection, DirectProxyStream> {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        self.sock.set_terminal_write_deadline(deadline);
    }
}

// The inner rustls connection can retain plaintext after the outer transport
// was read. Preserve an opted-in continuation's cap at that second buffering
// layer too. With no installed cap these are the existing IO operations.
struct ConnectOperationIo<'a>(&'a mut StreamOwned<ServerConnection, DirectProxyStream>);

impl Read for ConnectOperationIo<'_> {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        self.0.sock.check_operation_deadline()?;
        let result = self.0.read(buffer);
        self.0.sock.check_operation_deadline()?;
        result
    }
}

impl Write for ConnectOperationIo<'_> {
    fn write(&mut self, buffer: &[u8]) -> io::Result<usize> {
        self.0.sock.check_operation_deadline()?;
        let result = self.0.write(buffer);
        self.0.sock.check_operation_deadline()?;
        result
    }

    fn flush(&mut self) -> io::Result<()> {
        self.0.sock.check_operation_deadline()?;
        let result = self.0.flush();
        self.0.sock.check_operation_deadline()?;
        result
    }
}

impl TerminalDeadlineWrite for ConnectOperationIo<'_> {
    fn set_terminal_write_deadline(&mut self, deadline: Option<Instant>) {
        self.0.set_terminal_write_deadline(deadline);
    }
}

