struct AuditReservation<'a> {
    state: &'a GateState,
    active: bool,
}

impl AuditReservation<'_> {
    fn reject(&mut self) -> bool {
        let _queue = self
            .state
            .audit_queue
            .lock()
            .expect("audit queue mutex poisoned");
        self.state.audit_reserved.fetch_sub(1, Ordering::Relaxed);
        self.state
            .audit_required_failed
            .fetch_add(1, Ordering::Relaxed);
        self.active = false;
        false
    }

    fn commit(&mut self, event_type: &str, event: Value) -> bool {
        if !self.active {
            return false;
        }
        let queued_event = match AuditEvent::new(event_type, event, true) {
            Ok(event) => event,
            Err(_) => {
                eprintln!("required audit event ID generation failed");
                return self.reject();
            }
        };
        if !audit_event_fits_batch(&queued_event) {
            return self.reject();
        }
        let mut queue = self
            .state
            .audit_queue
            .lock()
            .expect("audit queue mutex poisoned");
        self.state.audit_reserved.fetch_sub(1, Ordering::Relaxed);
        self.active = false;
        if queue.len() >= self.state.audit_queue_max {
            self.state
                .audit_required_failed
                .fetch_add(1, Ordering::Relaxed);
            return false;
        }
        queue.push_back(queued_event);
        self.state.audit_enqueued.fetch_add(1, Ordering::Relaxed);
        true
    }
}

impl Drop for AuditReservation<'_> {
    fn drop(&mut self) {
        if self.active {
            let _queue = self
                .state
                .audit_queue
                .lock()
                .expect("audit queue mutex poisoned");
            self.state.audit_reserved.fetch_sub(1, Ordering::Relaxed);
            self.active = false;
        }
    }
}

