#[derive(Clone)]
struct AttestedResponseAuthenticationContext {
    verifying_key: VerifyingKey,
    key_id: String,
    response_context: AttestedResponseContext,
    policy_digest: String,
}

impl AttestedResponseAuthenticationContext {
    fn from_snapshot(snapshot: &Snapshot, label: &str) -> Result<Self, String> {
        let verifying_key = snapshot
            .response_verifying_key
            .clone()
            .ok_or_else(|| format!("{label} requires an attested response signing key"))?;
        let key_id = snapshot
            .response_signing_key_id
            .clone()
            .ok_or_else(|| format!("{label} requires an attested response signing key id"))?;
        let response_context = snapshot
            .attested_response_context
            .clone()
            .ok_or_else(|| format!("{label} requires attested response context"))?;
        if response_context.policy_bundle_digest != snapshot.hash {
            return Err(format!("{label} attested response context is inconsistent"));
        }
        Ok(Self {
            verifying_key,
            key_id,
            response_context,
            policy_digest: snapshot.hash.clone(),
        })
    }

    fn matches_snapshot(&self, snapshot: &Snapshot) -> bool {
        snapshot
            .response_verifying_key
            .as_ref()
            .is_some_and(|key| key.to_bytes() == self.verifying_key.to_bytes())
            && snapshot.response_signing_key_id.as_deref() == Some(self.key_id.as_str())
            && snapshot.attested_response_context.as_ref() == Some(&self.response_context)
            && snapshot.hash == self.policy_digest
    }
}

