fn parse_release_authorization_response(
    body: &[u8],
    expected_version: &str,
) -> Result<ReleaseAuthorizationResponse, String> {
    parse_release_authorization_response_contract(body, expected_version, false)
}

fn parse_dispatch_release_authorization_response(
    body: &[u8],
    expected_version: &str,
) -> Result<ReleaseAuthorizationResponse, String> {
    parse_release_authorization_response_contract(body, expected_version, true)
}

fn parse_release_authorization_response_contract(
    body: &[u8],
    expected_version: &str,
    exact_dispatch_shape: bool,
) -> Result<ReleaseAuthorizationResponse, String> {
    const DISPATCH_V1_FIELDS: [&str; 17] = [
        "apiVersion",
        "ok",
        "authorized",
        "state",
        "reason",
        "attemptId",
        "bindingDigest",
        "idempotentReplay",
        "grantId",
        "approvalRequestId",
        "reservationExpiresAtEpochMs",
        "dispatchStartedAtEpochMs",
        "dispatchExpiresAtEpochMs",
        "completionOutcome",
        "retryAfterSeconds",
        "quotas",
        "store",
    ];
    const DISPATCH_V2_FIELDS: [&str; 18] = [
        "apiVersion",
        "ok",
        "authorized",
        "state",
        "reason",
        "attemptId",
        "bindingDigest",
        "idempotentReplay",
        "grantId",
        "approvalRequestId",
        "reservationExpiresAtEpochMs",
        "dispatchStartedAtEpochMs",
        "dispatchExpiresAtEpochMs",
        "completionOutcome",
        "retryAfterSeconds",
        "quotas",
        "store",
        "durablePolicy",
    ];
    const DURABLE_DISPATCH_FIELDS: [&str; 11] = [
        "state",
        "attemptId",
        "claimDigest",
        "reservationId",
        "actorId",
        "reservationDeadlineAtEpochMs",
        "dispatchDeadlineAtEpochMs",
        "responseEvidenceDigest",
        "failureReason",
        "responseBodySha256",
        "uncertainty",
    ];
    const LEGACY_FIXED_QUOTA_FIELDS: [&str; 9] = [
        "counterKey",
        "constraintId",
        "operation",
        "windowStartEpochMs",
        "windowSeconds",
        "max",
        "count",
        "remaining",
        "reservationState",
    ];
    const CURRENT_FIXED_QUOTA_FIELDS: [&str; 11] = [
        "counterKey",
        "constraintId",
        "operation",
        "windowKind",
        "windowStartEpochMs",
        "windowEndEpochMs",
        "windowSeconds",
        "max",
        "count",
        "remaining",
        "reservationState",
    ];
    const CURRENT_CALENDAR_QUOTA_FIELDS: [&str; 11] = [
        "counterKey",
        "constraintId",
        "operation",
        "windowKind",
        "windowStartEpochMs",
        "windowEndEpochMs",
        "calendarWindow",
        "max",
        "count",
        "remaining",
        "reservationState",
    ];
    const STORE_FIELDS: [&str; 2] = ["backend", "ha"];

    let value = SensitiveJsonValue::new(
        strict_json_value_from_slice(body)
            .map_err(|_| "parse_release_authorization_response_json".to_string())?,
    );
    let object = value
        .as_object()
        .ok_or("release authorization response must be an object")?;
    if object.get("apiVersion").and_then(Value::as_str) != Some(expected_version) {
        return Err("release authorization response version mismatch".to_string());
    }
    let durable = object.get("durablePolicy");
    match expected_version {
        RELEASE_AUTHORIZATION_RESPONSE_V1 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V1
            | "serverware.policyAwareReleaseAuthorizationResponse/v1" if durable.is_some() => {
            return Err(
                "release authorization v1 response must omit durablePolicy".to_string(),
            )
        }
        RELEASE_AUTHORIZATION_RESPONSE_V2 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V2
            | "serverware.policyAwareReleaseAuthorizationResponse/v2"
            if durable.is_none_or(|value| !value.is_object()) =>
        {
            return Err(
                "release authorization v2 response requires durablePolicy".to_string(),
            )
        }
        RELEASE_AUTHORIZATION_RESPONSE_V1 | RELEASE_AUTHORIZATION_RESPONSE_V2
            | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V1 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V2
            | "serverware.policyAwareReleaseAuthorizationResponse/v1"
            | "serverware.policyAwareReleaseAuthorizationResponse/v2" => {}
        _ => {
            return Err(
                "release authorization response version is unsupported".to_string(),
            )
        }
    }
    if exact_dispatch_shape {
        let expected_fields = match expected_version {
            RELEASE_AUTHORIZATION_RESPONSE_V1 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V1
                | "serverware.policyAwareReleaseAuthorizationResponse/v1" => &DISPATCH_V1_FIELDS[..],
            RELEASE_AUTHORIZATION_RESPONSE_V2 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V2
                | "serverware.policyAwareReleaseAuthorizationResponse/v2" => &DISPATCH_V2_FIELDS[..],
            _ => unreachable!("supported release response version checked above"),
        };
        if !object_has_exact_fields(object, expected_fields) {
            return Err(
                "release authorization dispatch response fields are not exact".to_string(),
            );
        }
        if matches!(expected_version, RELEASE_AUTHORIZATION_RESPONSE_V2 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V2
            | "serverware.policyAwareReleaseAuthorizationResponse/v2")
            && !durable
                .and_then(Value::as_object)
                .is_some_and(|durable| {
                    object_has_exact_fields(durable, &DURABLE_DISPATCH_FIELDS)
                })
        {
            return Err(
                "release authorization dispatch durable response fields are not exact".to_string(),
            );
        }
        if !object
            .get("store")
            .and_then(Value::as_object)
            .is_some_and(|store| object_has_exact_fields(store, &STORE_FIELDS))
        {
            return Err(
                "release authorization dispatch store fields are not exact".to_string(),
            );
        }
        let quotas = object
            .get("quotas")
            .and_then(Value::as_array)
            .ok_or("release authorization dispatch quotas are invalid")?;
        for quota in quotas {
            let quota = quota
                .as_object()
                .ok_or("release authorization dispatch quota is not an object")?;
            let expected_quota_fields = match quota.get("windowKind") {
                None if matches!(expected_version, RELEASE_AUTHORIZATION_RESPONSE_V1 | NATIVE_RELEASE_AUTHORIZATION_RESPONSE_V1
                    | "serverware.policyAwareReleaseAuthorizationResponse/v1") => {
                    &LEGACY_FIXED_QUOTA_FIELDS[..]
                }
                Some(Value::String(kind)) if kind == "fixed" => {
                    &CURRENT_FIXED_QUOTA_FIELDS[..]
                }
                Some(Value::String(kind))
                    if matches!(kind.as_str(), "utcDay" | "utcIsoWeek" | "utcMonth") =>
                {
                    &CURRENT_CALENDAR_QUOTA_FIELDS[..]
                }
                _ => {
                    return Err(
                        "release authorization dispatch quota window shape is invalid".to_string(),
                    )
                }
            };
            if !object_has_exact_fields(quota, expected_quota_fields) {
                return Err(
                    "release authorization dispatch quota fields are not exact".to_string(),
                );
            }
        }
    }
    let response: ReleaseAuthorizationResponse = serde_json::from_value(value.into_value())
        .map_err(|_| "parse_release_authorization_response_contract".to_string())?;
    let _authenticated_store_assertion_only = response
        .store
        .asserted_backend
        .as_deref()
        .filter(|backend| valid_release_authorization_identity(Some(*backend)))
        .ok_or("release authorization authenticated store backend assertion is invalid")?;
    if !response.store.asserts_ha {
        return Err(
            "release authorization authenticated HA store assertion is false; the current contract carries no independent durable store proof"
                .to_string(),
        );
    }
    Ok(response)
}

