    struct ReleaseCleanupTestFixture {
        snapshot: Arc<Snapshot>,
        state: GateState,
        scope: CredentialLeaseScope,
        shared_scope: CredentialLeaseScope,
        reservation: ReleaseAuthorizationReservation,
        request_authority: CredentialLeaseRequestAuthority,
        authorization: CredentialLeaseReleaseAuthorization,
        concurrent_request_authority: CredentialLeaseRequestAuthority,
        concurrent_authorization: CredentialLeaseReleaseAuthorization,
    }

    fn test_release_cleanup_fixture(marker: u64) -> ReleaseCleanupTestFixture {
        let mut snapshot_value = (*test_snapshot(1)).clone();
        snapshot_value.hash =
            sha256_prefixed(format!("release-cleanup-fixture-{marker}").as_bytes());
        snapshot_value.credentials.insert(
            "credential:one-use".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        snapshot_value.credentials.insert(
            "credential:shared".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        snapshot_value.routes[0].credential_ref = Some("credential:one-use".to_string());
        snapshot_value.routes[0].jit = json!({
            "required":true,
            "ttlSeconds":30,
            "maxUses":1,
        });
        let mut shared_route = snapshot_value.routes[0].clone();
        shared_route.id = "route:shared".to_string();
        shared_route.credential_ref = Some("credential:shared".to_string());
        shared_route.jit = json!({"required":false});
        snapshot_value.routes.push(shared_route);
        let snapshot = Arc::new(snapshot_value);
        let scope =
            CredentialLeaseScope::new("agent:test", "route:test", "credential:one-use");
        let shared_scope =
            CredentialLeaseScope::new("agent:test", "route:shared", "credential:shared");
        let reservation = test_jit_release_reservation(&snapshot, &scope, 7, marker);
        let concurrent_reservation =
            test_jit_release_reservation(&snapshot, &scope, 7, marker + 1_000);
        let request_authority = reservation
            .credential_lease_request_authority()
            .expect("target request authority");
        let concurrent_request_authority = concurrent_reservation
            .credential_lease_request_authority()
            .expect("concurrent request authority");
        let authorization = reservation
            .credential_lease_authorization()
            .expect("target release authorization")
            .expect("target JIT release authority");
        let concurrent_authorization = concurrent_reservation
            .credential_lease_authorization()
            .expect("concurrent release authorization")
            .expect("concurrent JIT release authority");
        let state = test_gate_state(Arc::clone(&snapshot));
        {
            let mut generations = state
                .credential_generations
                .lock()
                .expect("credential generations");
            generations.insert(
                scope.clone(),
                test_credential_generation(&snapshot, 7, BTreeMap::new()),
            );
            generations.insert(
                shared_scope.clone(),
                test_credential_generation(&snapshot, 11, BTreeMap::new()),
            );
        }
        for (request_authority, release_authorization, secret) in [
            (
                request_authority.clone(),
                authorization.clone(),
                "target-one-use-secret",
            ),
            (
                concurrent_request_authority.clone(),
                concurrent_authorization.clone(),
                "concurrent-one-use-secret",
            ),
        ] {
            let mut lease =
                test_secret_lease(&snapshot, scope.clone(), 7, secret, BTreeMap::new());
            lease.request_authority = Some(request_authority);
            lease.release_authorization = Some(release_authorization);
            cache_scoped_credential_lease(&state, &snapshot, &scope, lease)
                .expect("cache exact release-controlled fixture secret");
        }
        cache_scoped_credential_lease(
            &state,
            &snapshot,
            &shared_scope,
            test_secret_lease(
                &snapshot,
                shared_scope.clone(),
                11,
                "shared-hot-secret",
                BTreeMap::new(),
            ),
        )
        .expect("cache shared non-release-controlled fixture secret");
        ReleaseCleanupTestFixture {
            snapshot,
            state,
            scope,
            shared_scope,
            reservation,
            request_authority,
            authorization,
            concurrent_request_authority,
            concurrent_authorization,
        }
    }

    fn assert_only_exact_release_secret_removed(fixture: &ReleaseCleanupTestFixture) {
        let leases = fixture
            .state
            .credential_leases
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(!leases.contains_key(&CredentialLeaseCacheKey::new_bound(
            &fixture.scope,
            Some(&fixture.request_authority),
            Some(&fixture.authorization),
        )));
        assert!(leases.contains_key(&CredentialLeaseCacheKey::new_bound(
            &fixture.scope,
            Some(&fixture.concurrent_request_authority),
            Some(&fixture.concurrent_authorization),
        )));
        assert!(leases.contains_key(&CredentialLeaseCacheKey::new(
            &fixture.shared_scope,
            None,
        )));
        assert_eq!(leases.len(), 2);
    }

    #[test]
    fn custody_configuration_is_complete_absolute_and_production_closed() {
        for dangling in [
            response_proof_custody_config_from_values(
                None,
                Some(OsString::from("123")),
                None,
                false,
                1000,
            ),
            response_proof_custody_config_from_values(
                None,
                None,
                Some(OsString::from("1000")),
                false,
                1000,
            ),
        ] {
            assert!(dangling
                .expect_err("custody option without socket must fail")
                .contains(RESPONSE_PROOF_CUSTODY_SOCKET_ENV));
        }
        assert!(response_proof_custody_config_from_values(
            Some(OsString::from("relative/custody.sock")),
            None,
            None,
            false,
            1000,
        )
        .expect_err("relative custody socket must fail")
        .contains("absolute"));
        assert!(response_proof_custody_config_from_values(
            Some(OsString::from("/run/serverware/custody.sock")),
            None,
            None,
            false,
            1000,
        )
        .expect_err("custody peer UID must never be implicit")
        .contains("explicitly configured"));
        assert!(response_proof_custody_config_from_values(
            Some(OsString::from("/run/serverware/custody.sock")),
            Some(OsString::from("1000")),
            None,
            true,
            1000,
        )
        .expect_err("production custody peer must use a distinct UID")
        .contains("must differ"));
        let configured = response_proof_custody_config_from_values(
            Some(OsString::from("/run/serverware/custody.sock")),
            Some(OsString::from("123")),
            Some(OsString::from("2500")),
            true,
            1000,
        )
        .expect("complete custody configuration")
        .expect("custody enabled");
        assert_eq!(
            configured.socket_path,
            PathBuf::from("/run/serverware/custody.sock")
        );
        assert_eq!(configured.expected_uid, 123);
        assert_eq!(configured.startup_timeout, Duration::from_millis(2500));
        validate_local_response_proof_mode(false, true)
            .expect("local response proof remains explicit development behavior");
        assert!(validate_local_response_proof_mode(true, true)
            .expect_err("production response proof must require custody")
            .contains("development-only"));
    }

