    #[test]
    fn grant_tombstones_survive_same_signed_policy_identity_reload_only() {
        let (snapshot, state) = local_grant_admission_fixture();
        assert_eq!(
            create_grant(&state, local_grant_create(&snapshot))["ok"],
            true
        );
        consume_local_grant(
            &state,
            "agent:test",
            "route:test",
            "credential:test",
            7,
            &snapshot.hash,
            local_grant_create(&snapshot).request_digest.as_str(),
            local_grant_create(&snapshot).operation_digest.as_str(),
        )
        .expect("consume grant into a replay tombstone");

        let mut same_policy = (*snapshot).clone();
        same_policy.epoch = snapshot.epoch + 1;
        same_policy.trust_generation = snapshot.trust_generation + 1;
        same_policy.response_signing_key_id = Some("sha256:rotated-response-key".to_string());
        assert!(!clear_local_grants_if_signed_policy_changed(
            &state,
            &snapshot,
            &same_policy,
        ));
        assert_eq!(state.grants.lock().expect("grant cache").len(), 1);

        let mut changed_policy = same_policy.clone();
        changed_policy.hash = "sha256:changed-signed-policy".to_string();
        changed_policy.policy_sequence += 1;
        assert!(clear_local_grants_if_signed_policy_changed(
            &state,
            &same_policy,
            &changed_policy,
        ));
        assert!(state.grants.lock().expect("grant cache").is_empty());
    }

    #[test]
    fn grant_admission_linearizes_with_policy_reload() {
        let snapshot = test_snapshot(1);
        let state = Arc::new(test_gate_state(Arc::clone(&snapshot)));
        let (admission_entered_tx, admission_entered_rx) = mpsc::sync_channel(0);
        let (admission_release_tx, admission_release_rx) = mpsc::sync_channel(0);
        let admission_state = Arc::clone(&state);
        let admission_snapshot = Arc::clone(&snapshot);
        let admission = thread::spawn(move || {
            insert_grant_for_snapshot(
                &admission_state,
                &admission_snapshot,
                "grant-key".to_string(),
                Grant {
                    id: "grant:before-reload".to_string(),
                    approval_id: Some("approval:before-reload".to_string()),
                    max_uses: 1,
                    ttl_seconds: 30,
                    uses_remaining: 1,
                    expires_at_ms: now_epoch_ms() + 30_000,
                },
                || {
                    admission_entered_tx
                        .send(())
                        .expect("announce grant admission");
                    admission_release_rx
                        .recv()
                        .expect("release grant admission");
                },
            )
        });
        admission_entered_rx
            .recv()
            .expect("grant admission reached linearization point");

        let (reload_started_tx, reload_started_rx) = mpsc::sync_channel(0);
        let (reload_done_tx, reload_done_rx) = mpsc::sync_channel(0);
        let reload_state = Arc::clone(&state);
        let reloader = thread::spawn(move || {
            reload_started_tx.send(()).expect("announce policy reload");
            *reload_state.snapshot.write().expect("snapshot lock") = test_snapshot(2);
            reload_state.grants.lock().expect("grant cache").clear();
            reload_done_tx.send(()).expect("announce reload completion");
        });
        reload_started_rx.recv().expect("policy reload started");
        assert!(
            reload_done_rx
                .recv_timeout(Duration::from_millis(100))
                .is_err(),
            "policy replacement must not split grant admission"
        );

        admission_release_tx
            .send(())
            .expect("release grant admission");
        admission
            .join()
            .expect("grant admission thread")
            .expect("grant admitted before reload");
        reload_done_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("policy reload completed after grant admission");
        reloader.join().expect("policy reloader");
        assert_eq!(current_snapshot(&state).policy_sequence, 2);
        assert!(state.grants.lock().expect("grant cache").is_empty());

        let stale = insert_grant_for_snapshot(
            &state,
            &snapshot,
            "stale-grant-key".to_string(),
            Grant {
                id: "grant:after-reload".to_string(),
                approval_id: Some("approval:after-reload".to_string()),
                max_uses: 1,
                ttl_seconds: 30,
                uses_remaining: 1,
                expires_at_ms: now_epoch_ms() + 30_000,
            },
            || panic!("stale admission must not reach its linearization callback"),
        )
        .expect_err("stale policy grant must be rejected");
        assert_eq!(
            stale,
            GrantAdmissionError::InactivePolicy(sha256_prefixed(b"serverware:test-policy:epoch:2"))
        );
        assert!(state.grants.lock().expect("grant cache").is_empty());
    }

    #[test]
    fn atomic_jit_denial_uses_canonical_request_and_surfaces_pending_approval() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let credential_listener =
            TcpListener::bind("127.0.0.1:0").expect("credential lease listener");
        credential_listener
            .set_nonblocking(true)
            .expect("credential lease nonblocking mode");
        let credential_address = credential_listener
            .local_addr()
            .expect("credential lease listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let approval_expires_at = (OffsetDateTime::now_utc() + TimeDuration::minutes(5))
            .format(&Rfc3339)
            .expect("approval expiry");
        let server_approval_expires_at = approval_expires_at.clone();
        let response_signing_key = SigningKey::from_bytes(&[112u8; 32]);
        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.routes[0].jit = json!({"required":true});
        snapshot_value.routes[0].credential_ref = Some("credential:test".to_string());
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        let snapshot = Arc::new(snapshot_value);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("release request");
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .expect("release read timeout");
            let head = read_request_head_from(&mut stream, None).expect("release request head");
            let request =
                read_request_body_from_head(&mut stream, head, MAX_MANAGEMENT_REQUEST_BODY_BYTES)
                    .expect("release request body");
            let payload = strict_json_value_from_slice(&request.body).expect("release JSON");
            let attempt_id = payload["attemptId"]
                .as_str()
                .expect("release attempt ID")
                .to_string();
            let binding_digest = test_release_binding_digest(&payload, true, json!([]));
            payload_sender
                .send(payload)
                .expect("capture release payload");
            let response = signed_release_test_response(
                &response_signing_key,
                &server_snapshot,
                &request,
                StatusCode::OK,
                json!({
                    "apiVersion":"serverware.releaseAuthorization/v1",
                    "ok":true,
                    "authorized":false,
                    "state":"denied",
                    "reason":"jit_grant_unavailable",
                    "attemptId":attempt_id,
                    "bindingDigest":binding_digest,
                    "idempotentReplay":false,
                    "grantId":null,
                    "approvalRequestId":"approval:test",
                    "approvalStatus":"pending",
                    "approvalExpiresAt":server_approval_expires_at,
                    "approvalCreated":true,
                    "reservationExpiresAtEpochMs":null,
                    "dispatchStartedAtEpochMs":null,
                    "dispatchExpiresAtEpochMs":null,
                    "completionOutcome":null,
                    "retryAfterSeconds":3,
                    "quotas":[],
                    "store":{"backend":"postgres","ha":true},
                }),
            );
            stream.write_all(&response).expect("release response");
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.credential_lease_url = Some(format!(
            "http://{credential_address}/api/data-plane/credential-leases"
        ));
        state.credential_lease_token = Some("credential-token".to_string());
        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        state
            .credential_generations
            .lock()
            .expect("credential generations")
            .insert(
                scope,
                test_credential_generation(&snapshot, 1, BTreeMap::new()),
            );

        let decision = decide_internal(
            &state,
            &snapshot,
            correlated_test_decision_request("A_-0123456789abcdefghijk"),
            Some("agent:test"),
        );
        server.join().expect("release server");

        assert_eq!(decision["status_code"], 428);
        assert_eq!(decision["action"], "jit_required");
        assert_eq!(decision["allowed"], false);
        assert_eq!(decision["approval_id"], "approval:test");
        assert_eq!(decision["approval_url"], "/approvals/approval:test");
        assert_eq!(decision["approval_status"], "pending");
        assert_eq!(decision["expires_at"], approval_expires_at);
        assert_eq!(decision["approval_created"], true);
        assert_eq!(decision["retry_after_seconds"], 3);
        assert_eq!(decision["payload"]["approval_id"], "approval:test");
        assert_eq!(
            decision["payload"]["approval_url"],
            "/approvals/approval:test"
        );
        assert_eq!(decision["payload"]["approval_status"], "pending");
        assert_eq!(decision["payload"]["expires_at"], approval_expires_at);
        assert_eq!(decision["payload"]["approval_created"], true);
        assert_eq!(decision["payload"]["retry_after_seconds"], 3);
        assert_eq!(
            decision["jit"]["grant_store"],
            "atomic_release_authorization"
        );
        assert_eq!(decision["jit"]["approval_id"], "approval:test");

        let payload = payload_receiver.recv().expect("reserve payload");
        let canonical = payload["canonicalRequest"].clone();
        assert_eq!(
            payload["requestDigest"],
            digest_json_ensure_ascii(&canonical)
        );
        assert_eq!(payload["operationDigest"], operation_digest(&canonical));
        assert_eq!(payload["operationContext"], canonical["operation"]);
        assert_eq!(
            canonical["request"]["headers"],
            json!({"host":"example.test"})
        );
        assert!(payload.get("redactedDisplay").is_none());
        assert!(matches!(
            credential_listener.accept(),
            Err(error) if error.kind() == io::ErrorKind::WouldBlock
        ));
        assert!(state
            .credential_leases
            .lock()
            .expect("credential lease cache")
            .is_empty());
    }

    #[test]
    fn approved_identical_jit_retry_fetches_dispatch_secret_only_after_reservation() {
        let release_listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let release_address = release_listener
            .local_addr()
            .expect("release listener address");
        let credential_listener = TcpListener::bind("127.0.0.1:0").expect("credential listener");
        let credential_address = credential_listener
            .local_addr()
            .expect("credential listener address");
        let order = Arc::new(Mutex::new(Vec::new()));
        let release_payloads = Arc::new(Mutex::new(Vec::new()));
        let credential_payload = Arc::new(Mutex::new(None));
        let approval_expires_at = (OffsetDateTime::now_utc() + TimeDuration::minutes(5))
            .format(&Rfc3339)
            .expect("approval expiry");
        let reservation_expires_at = u64::try_from(now_epoch_ms()).expect("current epoch") + 5_000;
        let response_signing_key = SigningKey::from_bytes(&[53u8; 32]);
        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.routes[0].jit = json!({"required":true});
        snapshot_value.routes[0].credential_ref = Some("credential:test".to_string());
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        let snapshot = Arc::new(snapshot_value);

        let release_order = Arc::clone(&order);
        let captured_release_payloads = Arc::clone(&release_payloads);
        let release_snapshot = Arc::clone(&snapshot);
        let release_response_signing_key = response_signing_key.clone();
        let release_server = thread::spawn(move || {
            let mut reserved_binding_digest = None;
            for index in 0..3 {
                let (mut stream, _) = release_listener.accept().expect("release request");
                let head = read_request_head_from(&mut stream, None).expect("release request head");
                let request = read_request_body_from_head(
                    &mut stream,
                    head,
                    MAX_MANAGEMENT_REQUEST_BODY_BYTES,
                )
                .expect("release request body");
                let payload =
                    strict_json_value_from_slice(&request.body).expect("release request JSON");
                let attempt_id = payload["attemptId"]
                    .as_str()
                    .expect("release attempt ID")
                    .to_string();
                let binding_digest = if index < 2 {
                    let binding = test_release_binding_digest(&payload, true, json!([]));
                    if index == 1 {
                        reserved_binding_digest = Some(binding.clone());
                    }
                    binding
                } else {
                    reserved_binding_digest
                        .clone()
                        .expect("reserved binding precedes cancellation")
                };
                captured_release_payloads
                    .lock()
                    .expect("release payloads")
                    .push(payload.clone());
                release_order
                    .lock()
                    .expect("request order")
                    .push(match index {
                        0 => "release-denied",
                        1 => "release-reserved",
                        _ => "release-cancelled",
                    });
                let body = if index == 0 {
                    json!({
                        "apiVersion":"serverware.releaseAuthorization/v1",
                        "ok":true,
                        "authorized":false,
                        "state":"denied",
                        "reason":"jit_grant_unavailable",
                        "attemptId":attempt_id,
                        "bindingDigest":binding_digest,
                        "idempotentReplay":false,
                        "grantId":null,
                        "approvalRequestId":"approval:test",
                        "approvalStatus":"pending",
                        "approvalExpiresAt":approval_expires_at,
                        "approvalCreated":true,
                        "reservationExpiresAtEpochMs":null,
                        "dispatchStartedAtEpochMs":null,
                        "dispatchExpiresAtEpochMs":null,
                        "completionOutcome":null,
                        "retryAfterSeconds":1,
                        "quotas":[],
                        "store":{"backend":"postgres","ha":true},
                    })
                } else if index == 1 {
                    json!({
                        "apiVersion":"serverware.releaseAuthorization/v1",
                        "ok":true,
                        "authorized":true,
                        "state":"reserved",
                        "reason":"reserved",
                        "attemptId":attempt_id,
                        "bindingDigest":binding_digest,
                        "idempotentReplay":false,
                        "grantId":"grant:test",
                        "approvalRequestId":"approval:test",
                        "approvalStatus":null,
                        "approvalExpiresAt":null,
                        "approvalCreated":null,
                        "reservationExpiresAtEpochMs":reservation_expires_at,
                        "dispatchStartedAtEpochMs":null,
                        "dispatchExpiresAtEpochMs":null,
                        "completionOutcome":null,
                        "retryAfterSeconds":0,
                        "quotas":[],
                        "store":{"backend":"postgres","ha":true},
                    })
                } else {
                    assert_eq!(
                        payload["bindingDigest"],
                        binding_digest
                    );
                    assert_eq!(payload["outcome"], "not_forwarded");
                    json!({
                        "apiVersion":"serverware.releaseAuthorization/v1",
                        "ok":true,
                        "authorized":false,
                        "state":"cancelled",
                        "reason":"cancelled",
                        "attemptId":attempt_id,
                        "bindingDigest":binding_digest,
                        "idempotentReplay":false,
                        "grantId":"grant:test",
                        "approvalRequestId":"approval:test",
                        "approvalStatus":null,
                        "approvalExpiresAt":null,
                        "approvalCreated":null,
                        "reservationExpiresAtEpochMs":reservation_expires_at,
                        "dispatchStartedAtEpochMs":null,
                        "dispatchExpiresAtEpochMs":null,
                        "completionOutcome":"not_forwarded",
                        "retryAfterSeconds":0,
                        "quotas":[],
                        "store":{"backend":"postgres","ha":true},
                    })
                };
                stream
                    .write_all(&signed_release_test_response(
                        &release_response_signing_key,
                        &release_snapshot,
                        &request,
                        StatusCode::OK,
                        body,
                    ))
                    .expect("release response");
            }
        });

        let credential_order = Arc::clone(&order);
        let captured_credential_payload = Arc::clone(&credential_payload);
        let credential_snapshot = Arc::clone(&snapshot);
        let credential_server = thread::spawn(move || {
            let (mut stream, _) = credential_listener
                .accept()
                .expect("dispatch credential request");
            let head = read_request_head_from(&mut stream, None).expect("credential request head");
            let request =
                read_request_body_from_head(&mut stream, head, MAX_CREDENTIAL_LEASE_RESPONSE_BYTES)
                    .expect("credential request body");
            let payload =
                strict_json_value_from_slice(&request.body).expect("credential request JSON");
            *captured_credential_payload
                .lock()
                .expect("credential payload") = Some(payload);
            credential_order
                .lock()
                .expect("request order")
                .push("credential-dispatch");
            let response_nonce = request
                .headers
                .get("x-serverware-response-nonce")
                .expect("credential response nonce");
            let response = signed_control_plane_test_response(
                &response_signing_key,
                &credential_snapshot,
                &request,
                response_nonce,
                u64::try_from(now_epoch_ms()).expect("response epoch"),
                StatusCode::SERVICE_UNAVAILABLE,
                json!({"detail":"intentional dispatch fixture stop"}),
            );
            stream
                .write_all(&response)
                .expect("signed credential response");
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{release_address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.credential_lease_url = Some(format!(
            "http://{credential_address}/api/data-plane/credential-leases"
        ));
        state.credential_lease_token = Some("credential-token".to_string());
        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        let generation = test_credential_generation(&snapshot, 7, BTreeMap::new());
        let generation_digest = generation.metadata_sha256.clone();
        state
            .credential_generations
            .lock()
            .expect("credential generations")
            .insert(scope, generation);
        let request = || correlated_test_decision_request("A_-0123456789abcdefghijk");

        let denied = decide_internal(&state, &snapshot, request(), Some("agent:test"));
        assert_eq!(denied["status_code"], 428);
        assert_eq!(
            *order.lock().expect("request order"),
            vec!["release-denied"]
        );
        assert!(state
            .credential_leases
            .lock()
            .expect("credential leases")
            .is_empty());

        let retry = decide_internal(&state, &snapshot, request(), Some("agent:test"));
        assert_eq!(retry["status_code"], 503);
        release_server.join().expect("release server");
        credential_server.join().expect("credential server");
        assert_eq!(
            *order.lock().expect("request order"),
            vec![
                "release-denied",
                "release-reserved",
                "credential-dispatch",
                "release-cancelled",
            ]
        );
        let releases = release_payloads.lock().expect("release payloads");
        assert_eq!(releases[0]["requestDigest"], releases[1]["requestDigest"]);
        assert_eq!(
            releases[0]["operationDigest"],
            releases[1]["operationDigest"]
        );
        let credential = credential_payload
            .lock()
            .expect("credential payload")
            .clone()
            .expect("captured credential payload");
        assert_eq!(
            credential["apiVersion"],
            "serverware.credentialLeaseRequest/v4"
        );
        assert_eq!(credential["purpose"], "dispatchSecret");
        assert_eq!(
            credential["requestAuthority"]["apiVersion"],
            "serverware.credentialLeaseRequestAuthority/v1"
        );
        assert_eq!(
            credential["requestAuthority"]["attemptId"],
            releases[1]["attemptId"]
        );
        assert_eq!(credential["expectedCredentialVersion"], 7);
        assert_eq!(credential["expectedMetadataSha256"], generation_digest);
        assert_eq!(
            credential["releaseAuthorization"]["attemptId"],
            releases[1]["attemptId"]
        );
        assert_eq!(
            credential["releaseAuthorization"]["bindingDigest"],
            test_release_binding_digest(&releases[1], true, json!([]))
        );
        assert!(state
            .credential_leases
            .lock()
            .expect("credential leases")
            .is_empty());
    }

    #[test]
    fn shared_jit_428_includes_approval_url_without_changing_approval_id() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("atomic release listener");
        let address = listener.local_addr().expect("atomic release address");
        let effects_listener = TcpListener::bind("127.0.0.1:0")
            .expect("unexpected legacy or credential effect listener");
        effects_listener
            .set_nonblocking(true)
            .expect("unexpected effect listener nonblocking mode");
        let effects_address = effects_listener.local_addr().expect("effect listener address");
        let approval_expires_at = (OffsetDateTime::now_utc() + TimeDuration::minutes(5))
            .format(&Rfc3339)
            .expect("pending approval expiry");
        let server_approval_expires_at = approval_expires_at.clone();
        let response_signing_key = SigningKey::from_bytes(&[113u8; 32]);
        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.routes[0].jit = valid_jit_policy();
        // This fixture proves authenticated approval presentation only. The route
        // remains credentialless and no forwarding/shadow authority is fabricated.
        let snapshot = Arc::new(snapshot_value);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let mut stream = accept_bounded_test_stream(&listener, Duration::from_secs(5))
                .expect("atomic reserve request must arrive before the fixture deadline");
            let head = read_request_head_from(&mut stream, None).expect("atomic reserve head");
            let request = read_request_body_from_head(
                &mut stream,
                head,
                MAX_MANAGEMENT_REQUEST_BODY_BYTES,
            )
            .expect("complete atomic reserve request");
            assert_eq!(request.method, "POST");
            assert_eq!(request.target, "/api/data-plane/release-authorizations/reserve");
            let payload = strict_json_value_from_slice(&request.body).expect("atomic reserve JSON");
            let response = signed_release_test_response(
                &response_signing_key,
                &server_snapshot,
                &request,
                StatusCode::OK,
                json!({
                    "apiVersion":"serverware.releaseAuthorization/v1",
                    "ok":true,
                    "authorized":false,
                    "state":"denied",
                    "reason":"jit_grant_unavailable",
                    "attemptId":payload["attemptId"],
                    "bindingDigest":test_release_binding_digest(&payload, true, json!([])),
                    "idempotentReplay":false,
                    "grantId":null,
                    "approvalRequestId":"approval:shared",
                    "approvalStatus":"pending",
                    "approvalExpiresAt":server_approval_expires_at,
                    "approvalCreated":true,
                    "reservationExpiresAtEpochMs":null,
                    "dispatchStartedAtEpochMs":null,
                    "dispatchExpiresAtEpochMs":null,
                    "completionOutcome":null,
                    "retryAfterSeconds":3,
                    "quotas":[],
                    "store":{"backend":"postgres","ha":true},
                }),
            );
            stream
                .write_all(&response)
                .expect("signed atomic pending approval response");
            (listener, payload)
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.audit_client = Client::builder()
            .no_proxy()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(Duration::from_secs(2))
            .build()
            .expect("bounded fixture control-plane client");
        state.credential_lease_client = state.audit_client.clone();
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.audit_url = Some(format!("http://{effects_address}/audit"));
        state.audit_token = Some("audit-token".to_string());
        state.grant_consume_url = Some(format!("http://{effects_address}/consume"));
        state.grant_consume_token = Some("grant-token".to_string());
        state.rate_limit_consume_url = Some(format!("http://{effects_address}/quota"));
        state.rate_limit_consume_token = Some("rate-token".to_string());
        state.credential_lease_url = Some(format!("http://{effects_address}/credential-leases"));
        state.credential_lease_token = Some("credential-token".to_string());
        let decision = decide_internal(
            &state,
            &snapshot,
            correlated_test_decision_request("A_-0123456789abcdefghijk"),
            Some("agent:test"),
        );
        assert_eq!(decision["status_code"], 428, "shared grant decision: {decision}");
        assert_eq!(decision["action"], "jit_required");
        assert_eq!(decision["allowed"], false);
        assert_eq!(
            decision["approval_id"], "approval:shared",
            "shared grant decision: {decision}"
        );
        assert_eq!(
            decision["approval_url"], "/approvals/approval:shared",
            "shared grant decision: {decision}"
        );
        assert_eq!(decision["payload"]["approval_id"], "approval:shared");
        assert_eq!(decision["payload"]["approval_url"], "/approvals/approval:shared");
        assert_eq!(decision["approval_status"], "pending");
        assert_eq!(decision["expires_at"], approval_expires_at);
        assert_eq!(decision["approval_created"], true);
        assert_eq!(decision["retry_after_seconds"], 3);
        assert_eq!(decision["jit"]["grant_store"], "atomic_release_authorization");
        assert_eq!(decision["jit"]["grant_reserved"], false);
        assert_eq!(decision["jit"]["grant_consumed"], false);
        let (listener, payload) = server
            .join()
            .expect("atomic reserve server must receive and answer the request");
        let canonical = &payload["canonicalRequest"];
        assert_eq!(payload["requestDigest"], digest_json_ensure_ascii(canonical));
        assert_eq!(payload["operationDigest"], operation_digest(canonical));
        assert_eq!(payload["operationContext"], canonical["operation"]);
        assert_eq!(payload["flowId"], payload["attemptId"]);
        assert_eq!(decision["attempt_id"], payload["attemptId"]);
        assert_eq!(decision["request_digest"], payload["requestDigest"]);
        assert_eq!(decision["operation_digest"], payload["operationDigest"]);
        assert_eq!(canonical["request"]["headers"], json!({"host":"example.test"}));
        assert!(payload["credentialRef"].is_null());
        assert!(matches!(listener.accept(), Err(error) if error.kind() == io::ErrorKind::WouldBlock));
        assert!(matches!(effects_listener.accept(), Err(error) if error.kind() == io::ErrorKind::WouldBlock));
        assert!(state.grants.lock().expect("grant cache").is_empty());
        assert!(state.credential_generations.lock().expect("credential generations").is_empty());
        assert!(state.credential_leases.lock().expect("credential lease cache").is_empty());
        assert!(state.constraint_rate_counters.lock().expect("rate counters").is_empty());
        assert!(!state.audit_queue.lock().expect("audit queue").iter().any(|event| {
            event.event_type == "data_plane.jit.grant_consumed"
        }));
    }

    #[test]
    fn shared_jit_requires_atomic_authorization_before_legacy_endpoint_contact() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("legacy grant listener");
        listener.set_nonblocking(true).expect("legacy listener nonblocking mode");
        let address = listener.local_addr().expect("legacy grant address");
        let mut snapshot_value = (*test_snapshot(1)).clone();
        snapshot_value.routes[0].jit = valid_jit_policy();
        let snapshot = Arc::new(snapshot_value);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        assert!(!state.atomic_release_authorization_enabled);
        state.audit_client = Client::builder()
            .no_proxy()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(Duration::from_secs(2))
            .build()
            .expect("bounded legacy negative control-plane client");
        state.credential_lease_client = state.audit_client.clone();
        state.grant_consume_url = Some(format!("http://{address}/consume"));
        state.grant_consume_token = Some("grant-token".to_string());
        let decision = decide_internal(
            &state,
            &snapshot,
            correlated_test_decision_request("A_-0123456789abcdefghijk"),
            Some("agent:test"),
        );
        assert_eq!(decision["status_code"], 503);
        assert_eq!(decision["allowed"], false);
        assert_eq!(decision["payload"]["error"], "legacy_jit_requires_atomic_release_authorization");
        assert!(matches!(listener.accept(), Err(error) if error.kind() == io::ErrorKind::WouldBlock));
        assert!(state.grants.lock().expect("grant cache").is_empty());
        assert!(state.constraint_rate_counters.lock().expect("rate counters").is_empty());
        assert!(state.audit_queue.lock().expect("audit queue").is_empty());
    }

    fn test_release_authorization_response(
        state: &str,
        completion_outcome: Option<&str>,
        authorized: bool,
        idempotent_replay: bool,
    ) -> ReleaseAuthorizationResponse {
        let now_ms = u64::try_from(now_epoch_ms()).expect("current epoch fits u64");
        ReleaseAuthorizationResponse {
            api_version: "serverware.releaseAuthorization/v1".to_string(),
            ok: true,
            authorized,
            state: state.to_string(),
            reason: state.to_string(),
            attempt_id: "attempt-test".to_string(),
            binding_digest: format!("sha256:{}", "a".repeat(64)),
            idempotent_replay,
            grant_id: None,
            approval_request_id: None,
            approval_status: None,
            approval_expires_at: None,
            approval_created: None,
            reservation_expires_at_epoch_ms: (state == "reserved").then_some(now_ms + 30_000),
            dispatch_started_at_epoch_ms: (state == "dispatching").then_some(now_ms),
            dispatch_expires_at_epoch_ms: (state == "dispatching").then_some(now_ms + 10_000),
            completion_outcome: completion_outcome.map(str::to_string),
            retry_after_seconds: 0,
            quotas: Vec::new(),
            store: AuthenticatedReleaseAuthorizationStoreAssertion {
                asserted_backend: Some("sqlite".to_string()),
                asserts_ha: false,
            },
            durable_policy: None,
            validated_quotas: Vec::new(),
            validated_durable_policy: None,
        }
    }

