    fn signed_control_plane_test_response(
        signing_key: &SigningKey,
        snapshot: &Snapshot,
        request: &IncomingRequest,
        response_nonce: &str,
        issued_at_ms: u64,
        status: StatusCode,
        body: Value,
    ) -> Vec<u8> {
        validate_canonical_response_nonce(response_nonce, "test control-plane response")
            .expect("canonical test control-plane response nonce");
        let body = serde_json::to_vec(&body).expect("signed response body");
        let body_sha256 = sha256_prefixed(&body);
        let key_id = snapshot
            .response_signing_key_id
            .as_deref()
            .expect("test response signing key id");
        let context = snapshot
            .attested_response_context
            .as_ref()
            .expect("test attested response context");
        let (path, query) = request
            .target
            .split_once('?')
            .unwrap_or((&request.target, ""));
        let mut response_headers = HeaderMap::new();
        response_headers.insert(
            "content-length",
            HeaderValue::from_str(&body.len().to_string()).expect("response content length"),
        );
        response_headers.insert(
            "content-type",
            HeaderValue::from_static("application/json"),
        );
        let (response_headers_sha256, response_header_count) =
            control_plane_response_headers_binding(&response_headers)
                .expect("canonical signed response headers");
        let statement = json!({
            "version":"serverware.responseSignature/v3",
            "issued_at_ms":issued_at_ms,
            "request":{
                "method":request.method,
                "path":path,
                "query_sha256":sha256_prefixed(query.as_bytes()),
            },
            "status_code":status.as_u16(),
            "body_sha256":body_sha256,
            "response_headers_sha256":response_headers_sha256,
            "response_header_count":response_header_count,
            "nonce":response_nonce,
            "response_signing_key_id":key_id,
            "context":{
                "runtime_manifest_digest":context.runtime_manifest_digest,
                "policy_bundle_digest":context.policy_bundle_digest,
                "provenance_digest":context.provenance_digest,
                "image_signatures_digest":context.image_signatures_digest,
                "source_tree_digest":context.source_tree_digest,
            },
        });
        let statement = canonical_json_ensure_ascii(&statement).into_bytes();
        let statement_sha256 = sha256_prefixed(&statement);
        let statement_b64 = general_purpose::URL_SAFE_NO_PAD.encode(&statement);
        let signature = signing_key.sign(&statement);
        http_binary_response_with_headers(
            status,
            Some("application/json"),
            body,
            &[
                (
                    "X-Serverware-Response-Key-Id".to_string(),
                    key_id.to_string(),
                ),
                ("X-Serverware-Response-Body-SHA256".to_string(), body_sha256),
                (
                    "X-Serverware-Response-Statement-B64".to_string(),
                    statement_b64,
                ),
                (
                    "X-Serverware-Response-Statement-SHA256".to_string(),
                    statement_sha256,
                ),
                (
                    "X-Serverware-Response-Signature".to_string(),
                    format!(
                        "ed25519:{}",
                        general_purpose::URL_SAFE_NO_PAD.encode(signature.to_bytes())
                    ),
                ),
            ],
        )
    }

    #[test]
    fn response_signature_nonce_requires_exact_canonical_32_bytes() {
        let canonical = general_purpose::URL_SAFE_NO_PAD.encode([7u8; 32]);
        validate_canonical_response_nonce(&canonical, "test response")
            .expect("canonical 32-byte response nonce");

        let short = general_purpose::URL_SAFE_NO_PAD.encode([7u8; 31]);
        let overlong = general_purpose::URL_SAFE_NO_PAD.encode([7u8; 33]);
        let padded = format!("{canonical}=");
        let alphabet =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        let final_index = alphabet
            .find(canonical.chars().last().expect("nonce final character"))
            .expect("nonce uses base64url alphabet");
        let alias_index = if final_index % 4 == 3 {
            final_index - 1
        } else {
            final_index + 1
        };
        let mut noncanonical = canonical.clone();
        noncanonical.pop();
        noncanonical.push(
            alphabet
                .chars()
                .nth(alias_index)
                .expect("noncanonical nonce alias"),
        );
        for nonce in [&short, &padded, &noncanonical, &overlong] {
            assert!(validate_canonical_response_nonce(nonce, "test response").is_err());
        }
    }

