    fn signed_encrypted_dispatch_credential_response(
        signing_key: &SigningKey,
        snapshot: &Snapshot,
        request: &IncomingRequest,
        response_nonce: &str,
        secret: &str,
        credential_version: u64,
        metadata: BTreeMap<String, Value>,
    ) -> Vec<u8> {
        let lease_request: CredentialLeaseRequest =
            strict_json_from_slice(&request.body).expect("credential lease request");
        assert_eq!(
            lease_request.purpose,
            CredentialLeasePurpose::DispatchSecret
        );
        let recipient_public_key = general_purpose::URL_SAFE_NO_PAD
            .decode(lease_request.recipient_public_key.as_bytes())
            .expect("recipient public key");
        let recipient_public_key: [u8; 32] = recipient_public_key
            .try_into()
            .expect("32-byte recipient public key");
        let recipient_nonce_bytes = general_purpose::URL_SAFE_NO_PAD
            .decode(lease_request.recipient_nonce.as_bytes())
            .expect("recipient nonce");
        let recipient_nonce_bytes: [u8; 32] = recipient_nonce_bytes
            .try_into()
            .expect("32-byte recipient nonce");
        let issued_at_epoch_ms =
            u64::try_from(now_epoch_ms()).expect("credential issued epoch");
        let request_bound = lease_request.request_authority.is_some();
        let request_binding_sha256 = credential_lease_request_binding_sha256(&lease_request);
        let request_authority_sha256 = lease_request
            .request_authority
            .as_ref()
            .map(credential_lease_request_authority_sha256);
        let release_expiry = lease_request
            .request_authority
            .as_ref()
            .map(|authority| authority.reservation_expires_at_epoch_ms)
            .or_else(|| {
                lease_request
                    .release_authorization
                    .as_ref()
                    .map(|authorization| authorization.reservation_expires_at_epoch_ms)
            })
            .unwrap_or(issued_at_epoch_ms + 4_000);
        let expires_at_epoch_ms = (issued_at_epoch_ms + 4_000).min(release_expiry);
        assert!(expires_at_epoch_ms > issued_at_epoch_ms);
        let aad = if request_bound {
            json!({
                "apiVersion":"serverware.credentialLeaseEnvelope/v3",
                "algorithm":"X25519-HKDF-SHA256-AES-256-GCM",
                "purpose":"dispatchSecret",
                "requestBindingSha256":request_binding_sha256,
                "requestAuthoritySha256":request_authority_sha256,
                "recipientKeyId":lease_request.recipient_key_id,
                "recipientNonce":lease_request.recipient_nonce,
                "policyHash":lease_request.policy_hash,
                "dataPlaneBinaryDigest":lease_request.data_plane_binary_digest,
                "principalId":lease_request.principal_id,
                "routeId":lease_request.route_id,
                "credentialId":lease_request.credential_id,
                "issuedAtEpochMs":issued_at_epoch_ms,
                "expiresAtEpochMs":expires_at_epoch_ms,
            })
        } else {
            json!({
                "apiVersion":"serverware.credentialLeaseEnvelope/v2",
                "algorithm":"X25519-HKDF-SHA256-AES-256-GCM",
                "recipientKeyId":lease_request.recipient_key_id,
                "recipientNonce":lease_request.recipient_nonce,
                "policyHash":lease_request.policy_hash,
                "dataPlaneBinaryDigest":lease_request.data_plane_binary_digest,
                "principalId":lease_request.principal_id,
                "routeId":lease_request.route_id,
                "credentialId":lease_request.credential_id,
                "issuedAtEpochMs":issued_at_epoch_ms,
                "expiresAtEpochMs":expires_at_epoch_ms,
            })
        };
        let mut plaintext = json!({
            "apiVersion":if request_bound {
                "serverware.credentialLeaseSet/v4"
            } else {
                "serverware.credentialLeaseSet/v3"
            },
            "purpose":"dispatchSecret",
            "requestBindingSha256":request_binding_sha256,
            "releaseAuthorization":lease_request.release_authorization,
            "recipientKeyId":lease_request.recipient_key_id,
            "recipientNonce":lease_request.recipient_nonce,
            "policyHash":lease_request.policy_hash,
            "dataPlaneBinaryDigest":lease_request.data_plane_binary_digest,
            "principalId":lease_request.principal_id,
            "routeId":lease_request.route_id,
            "credentialId":lease_request.credential_id,
            "issuedAtEpochMs":issued_at_epoch_ms,
            "expiresAtEpochMs":expires_at_epoch_ms,
            "credentials":[{
                "credentialId":lease_request.credential_id,
                "credentialVersion":credential_version,
                "secret":secret,
                "metadataSha256":credential_lease_metadata_sha256(&metadata),
                "metadata":metadata,
            }],
        });
        if request_bound {
            let plaintext = plaintext
                .as_object_mut()
                .expect("credential lease plaintext is an object");
            plaintext.insert(
                "requestAuthoritySha256".to_string(),
                request_authority_sha256.clone().map_or(Value::Null, Value::String),
            );
            plaintext.insert(
                "requestAuthority".to_string(),
                serde_json::to_value(&lease_request.request_authority)
                    .expect("serialize request authority"),
            );
        }
        let aad_bytes = canonical_json(&aad).into_bytes();
        let server_private_key = X25519StaticSecret::from([109u8; 32]);
        let server_public_key = X25519PublicKey::from(&server_private_key);
        let recipient_public_key = X25519PublicKey::from(recipient_public_key);
        let shared_secret = server_private_key.diffie_hellman(&recipient_public_key);
        assert!(shared_secret.was_contributory());
        let aad_digest = Sha256::digest(&aad_bytes);
        let mut hkdf_info = b"serverware:credential-lease-envelope:v2\0".to_vec();
        hkdf_info.extend_from_slice(&aad_digest);
        let salt = hkdf::Salt::new(hkdf::HKDF_SHA256, &recipient_nonce_bytes);
        let prk = salt.extract(shared_secret.as_bytes());
        let info = [hkdf_info.as_slice()];
        let mut key_bytes = [0u8; 32];
        prk.expand(&info, Aes256KeyLength)
            .expect("credential lease HKDF expand")
            .fill(&mut key_bytes)
            .expect("credential lease HKDF fill");
        let unbound = aead::UnboundKey::new(&aead::AES_256_GCM, &key_bytes)
            .expect("credential lease AEAD key");
        let key = aead::LessSafeKey::new(unbound);
        let aead_nonce = [110u8; 12];
        let mut ciphertext = canonical_json(&plaintext).into_bytes();
        key.seal_in_place_append_tag(
            aead::Nonce::assume_unique_for_key(aead_nonce),
            aead::Aad::from(aad_bytes.as_slice()),
            &mut ciphertext,
        )
        .expect("credential lease encryption");
        let mut envelope = json!({
            "apiVersion":if request_bound {
                "serverware.credentialLeaseEnvelope/v3"
            } else {
                "serverware.credentialLeaseEnvelope/v2"
            },
            "algorithm":"X25519-HKDF-SHA256-AES-256-GCM",
            "recipientKeyId":aad["recipientKeyId"],
            "recipientNonce":aad["recipientNonce"],
            "policyHash":aad["policyHash"],
            "dataPlaneBinaryDigest":aad["dataPlaneBinaryDigest"],
            "principalId":aad["principalId"],
            "routeId":aad["routeId"],
            "credentialId":aad["credentialId"],
            "issuedAtEpochMs":issued_at_epoch_ms,
            "expiresAtEpochMs":expires_at_epoch_ms,
            "serverEphemeralPublicKey":general_purpose::URL_SAFE_NO_PAD
                .encode(server_public_key.as_bytes()),
            "aeadNonce":general_purpose::URL_SAFE_NO_PAD.encode(aead_nonce),
            "ciphertext":general_purpose::URL_SAFE_NO_PAD.encode(&ciphertext),
            "ciphertextSha256":sha256_prefixed(&ciphertext),
        });
        if request_bound {
            let envelope = envelope
                .as_object_mut()
                .expect("credential lease envelope is an object");
            envelope.insert("purpose".to_string(), json!("dispatchSecret"));
            envelope.insert(
                "requestBindingSha256".to_string(),
                Value::String(request_binding_sha256),
            );
            envelope.insert(
                "requestAuthoritySha256".to_string(),
                request_authority_sha256.map_or(Value::Null, Value::String),
            );
        }
        signed_control_plane_test_response(
            signing_key,
            snapshot,
            request,
            response_nonce,
            issued_at_epoch_ms,
            StatusCode::OK,
            envelope,
        )
    }

    fn snapshot_with_control_plane_response_key(
        snapshot: &Snapshot,
        signing_key: &SigningKey,
    ) -> Arc<Snapshot> {
        let mut snapshot = snapshot.clone();
        snapshot.response_signing_key_id =
            Some(test_ed25519_spki_key_id(&signing_key.verifying_key()));
        snapshot.response_verifying_key = Some(signing_key.verifying_key());
        snapshot.attested_response_context = Some(AttestedResponseContext {
            runtime_manifest_digest: sha256_prefixed(b"test-runtime-manifest"),
            policy_bundle_digest: snapshot.hash.clone(),
            provenance_digest: None,
            image_signatures_digest: None,
            source_tree_digest: None,
        });
        Arc::new(snapshot)
    }

    fn test_snapshot_with_control_plane_response_key(
        epoch: u64,
        signing_key: &SigningKey,
    ) -> Arc<Snapshot> {
        snapshot_with_control_plane_response_key(&test_snapshot(epoch), signing_key)
    }

    fn read_audit_test_request(listener: &TcpListener) -> (TcpStream, IncomingRequest) {
        let (mut stream, _) = listener.accept().expect("audit request");
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .expect("audit read timeout");
        let head = read_request_head_from(&mut stream, None).expect("audit request head");
        let request =
            read_request_body_from_head(&mut stream, head, MAX_CONTROL_PLANE_AUDIT_ACK_BODY_BYTES)
                .expect("audit request body");
        (stream, request)
    }

    fn signed_audit_test_acknowledgement(
        signing_key: &SigningKey,
        snapshot: &Snapshot,
        request: &IncomingRequest,
        accepted: u64,
        batch_digest: &str,
    ) -> Vec<u8> {
        signed_audit_test_response(
            signing_key,
            snapshot,
            request,
            StatusCode::OK,
            accepted,
            batch_digest,
            "test-instance",
        )
    }

    fn signed_audit_test_response(
        signing_key: &SigningKey,
        snapshot: &Snapshot,
        request: &IncomingRequest,
        status: StatusCode,
        accepted: u64,
        batch_digest: &str,
        instance_id: &str,
    ) -> Vec<u8> {
        let response_nonce = request
            .headers
            .get("x-serverware-response-nonce")
            .expect("audit response nonce");
        validate_canonical_response_nonce(response_nonce, "test audit acknowledgement")
            .expect("canonical audit response nonce");
        signed_control_plane_test_response(
            signing_key,
            snapshot,
            request,
            response_nonce,
            u64::try_from(now_epoch_ms()).expect("current epoch fits u64"),
            status,
            json!({
                "apiVersion":"serverware.dataPlaneAuditAck/v1",
                "ok":true,
                "accepted":accepted,
                "batchDigest":batch_digest,
                "instanceId":instance_id,
            }),
        )
    }

    #[test]
    fn reserve_response_validation_binds_jit_grant_identity_and_denial_reason() {
        let reserved = test_release_authorization_response("reserved", None, true, false);
        validate_reserve_release_authorization_response(&reserved, "attempt-test", false)
            .expect("non-JIT reserve without grant identity is valid");
        assert!(
            validate_reserve_release_authorization_response(&reserved, "attempt-test", true,)
                .expect_err("JIT reserve must carry grant identity")
                .contains("invalid lifecycle state")
        );

        let mut jit_reserved = test_release_authorization_response("reserved", None, true, false);
        jit_reserved.grant_id = Some("grant:test".to_string());
        jit_reserved.approval_request_id = Some("approval:test".to_string());
        validate_reserve_release_authorization_response(&jit_reserved, "attempt-test", true)
            .expect("JIT reserve with both grant identities is valid");
        assert!(validate_reserve_release_authorization_response(
            &jit_reserved,
            "attempt-test",
            false,
        )
        .expect_err("non-JIT reserve must reject grant identity")
        .contains("invalid lifecycle state"));

        let mut partial_jit = test_release_authorization_response("reserved", None, true, false);
        partial_jit.grant_id = Some("grant:test".to_string());
        assert!(validate_reserve_release_authorization_response(
            &partial_jit,
            "attempt-test",
            true,
        )
        .is_err());
        partial_jit.approval_request_id = Some(" approval:test".to_string());
        assert!(validate_reserve_release_authorization_response(
            &partial_jit,
            "attempt-test",
            true,
        )
        .is_err());
        partial_jit.approval_request_id = Some("approval:\ninvalid".to_string());
        assert!(validate_reserve_release_authorization_response(
            &partial_jit,
            "attempt-test",
            true,
        )
        .is_err());

        let mut replayed_jit = test_release_authorization_response("reserved", None, true, true);
        replayed_jit.grant_id = Some("grant:test".to_string());
        replayed_jit.approval_request_id = Some("approval:test".to_string());
        validate_reserve_release_authorization_response(&replayed_jit, "attempt-test", true)
            .expect("idempotent replay of the same live JIT reservation is valid");

        let mut wrong_success_reason =
            test_release_authorization_response("reserved", None, true, false);
        wrong_success_reason.reason = "authorized".to_string();
        assert!(validate_reserve_release_authorization_response(
            &wrong_success_reason,
            "attempt-test",
            false,
        )
        .is_err());

        let mut unknown_denial = test_release_authorization_response("denied", None, false, false);
        unknown_denial.reason = "policy_denied".to_string();
        assert!(validate_reserve_release_authorization_response(
            &unknown_denial,
            "attempt-test",
            false,
        )
        .is_err());

        let mut non_jit_jit_denial =
            test_release_authorization_response("denied", None, false, false);
        non_jit_jit_denial.reason = "jit_grant_unavailable".to_string();
        non_jit_jit_denial.approval_request_id = Some("approval:test".to_string());
        assert!(validate_reserve_release_authorization_response(
            &non_jit_jit_denial,
            "attempt-test",
            false,
        )
        .is_err());

        let mut quota_denial = test_release_authorization_response("denied", None, false, false);
        quota_denial.reason = "shared_quota_denied".to_string();
        quota_denial.retry_after_seconds = 86_400;
        validate_reserve_release_authorization_response(&quota_denial, "attempt-test", false)
            .expect("bounded daily quota denial is valid");
        quota_denial.retry_after_seconds = MAX_RATE_LIMIT_WINDOW_SECONDS + 1;
        assert!(validate_reserve_release_authorization_response(
            &quota_denial,
            "attempt-test",
            false,
        )
        .expect_err("quota retry interval above the policy maximum must fail closed")
        .contains("retry interval"));
    }

    #[test]
    fn release_lifecycle_response_validation_rejects_cross_state_pairs() {
        let now_ms = u64::try_from(now_epoch_ms()).expect("current epoch fits u64");
        let reservation = ReleaseAuthorizationReservation {
            profile: ReleaseProfile::Legacy,
            preparation: None,
            attempt_id: "attempt-test".to_string(),
            binding_digest: format!("sha256:{}", "a".repeat(64)),
            principal_id: "agent:test".to_string(),
            route_id: "route:test".to_string(),
            credential_id: "credential:test".to_string(),
            credential_version: 1,
            policy_hash: format!("sha256:{}", "b".repeat(64)),
            request_digest: format!("sha256:{}", "c".repeat(64)),
            operation_digest: Some(format!("sha256:{}", "d".repeat(64))),
            operation_context: Some(json!({"operation":"test.operation"})),
            grant_id: None,
            approval_request_id: None,
            reservation_expires_at_epoch_ms: Some(now_ms + 30_000),
            shared_quotas: Vec::new(),
            durable_policy: None,
            dispatch_started_at_epoch_ms: None,
            dispatch_expires_at_epoch_ms: None,
        };

        let committed =
            test_release_authorization_response("committed", Some("forwarded"), true, false);
        assert!(
            validate_reserve_release_authorization_response(&committed, "attempt-test", false)
                .expect_err("reserve must reject terminal state")
                .contains("invalid lifecycle state")
        );
        assert!(validate_complete_release_authorization_response(
            &committed,
            &reservation,
            "unknown"
        )
        .expect_err("unknown completion must reject a non-replay forwarded result")
        .contains("invalid state"));

        let mut replayed_forwarded =
            test_release_authorization_response("committed", Some("forwarded"), true, true);
        replayed_forwarded.reservation_expires_at_epoch_ms =
            reservation.reservation_expires_at_epoch_ms;
        validate_complete_release_authorization_response(
            &replayed_forwarded,
            &reservation,
            "unknown",
        )
        .expect("lost forwarded completion response may replay during unknown cleanup");

        let mut indeterminate_not_forwarded = test_release_authorization_response(
            "committed_indeterminate",
            Some("not_forwarded"),
            true,
            false,
        );
        indeterminate_not_forwarded.reservation_expires_at_epoch_ms =
            reservation.reservation_expires_at_epoch_ms;
        assert!(validate_complete_release_authorization_response(
            &indeterminate_not_forwarded,
            &reservation,
            "not_forwarded",
        )
        .is_err());

        let mut dispatching =
            test_release_authorization_response("dispatching", Some("forwarded"), true, true);
        dispatching.reservation_expires_at_epoch_ms = reservation.reservation_expires_at_epoch_ms;
        dispatching.dispatch_started_at_epoch_ms = Some(now_ms);
        dispatching.dispatch_expires_at_epoch_ms = Some(now_ms + 10_000);
        assert!(
            validate_dispatch_release_authorization_response(&dispatching, &reservation)
                .expect_err("dispatch must reject completion outcome")
                .contains("exact dispatching state")
        );

        let mut live_dispatch =
            test_release_authorization_response("dispatching", None, true, false);
        live_dispatch.reservation_expires_at_epoch_ms = reservation.reservation_expires_at_epoch_ms;
        live_dispatch.dispatch_started_at_epoch_ms = Some(now_ms);
        live_dispatch.dispatch_expires_at_epoch_ms = Some(now_ms + 10_000);
        validate_dispatch_release_authorization_response(&live_dispatch, &reservation)
            .expect("dispatch must accept an exact live response");

        live_dispatch.dispatch_expires_at_epoch_ms = Some(now_ms.saturating_sub(1));
        assert!(
            validate_dispatch_release_authorization_response(&live_dispatch, &reservation)
                .expect_err("dispatch must reject an expired authorization")
                .contains("exact dispatching state")
        );

        live_dispatch.dispatch_started_at_epoch_ms = Some(now_ms);
        live_dispatch.dispatch_expires_at_epoch_ms = Some(now_ms + 10_000);
        live_dispatch.reason = "reserved".to_string();
        assert!(
            validate_dispatch_release_authorization_response(&live_dispatch, &reservation)
                .expect_err("dispatch must reject the wrong reason")
                .contains("exact dispatching state")
        );
    }

    #[test]
    fn completion_validation_binds_authority_ids_for_every_terminal_result() {
        let reservation = ReleaseAuthorizationReservation {
            profile: ReleaseProfile::Legacy,
            preparation: None,
            attempt_id: "attempt-test".to_string(),
            binding_digest: format!("sha256:{}", "a".repeat(64)),
            principal_id: "agent:test".to_string(),
            route_id: "route:test".to_string(),
            credential_id: "credential:test".to_string(),
            credential_version: 1,
            policy_hash: format!("sha256:{}", "b".repeat(64)),
            request_digest: format!("sha256:{}", "c".repeat(64)),
            operation_digest: Some(format!("sha256:{}", "d".repeat(64))),
            operation_context: Some(json!({"operation":"test.operation"})),
            grant_id: Some("grant:test".to_string()),
            approval_request_id: Some("approval:test".to_string()),
            reservation_expires_at_epoch_ms: Some(1234),
            shared_quotas: Vec::new(),
            durable_policy: None,
            dispatch_started_at_epoch_ms: None,
            dispatch_expires_at_epoch_ms: None,
        };
        for (state, completion_outcome, authorized, replay, requested_outcome) in [
            ("committed", "forwarded", true, false, "forwarded"),
            ("cancelled", "not_forwarded", false, false, "not_forwarded"),
            ("committed_indeterminate", "unknown", true, false, "unknown"),
            ("committed", "forwarded", true, true, "unknown"),
            ("cancelled", "not_forwarded", false, true, "unknown"),
        ] {
            let mut exact = test_release_authorization_response(
                state,
                Some(completion_outcome),
                authorized,
                replay,
            );
            exact.grant_id = reservation.grant_id.clone();
            exact.approval_request_id = reservation.approval_request_id.clone();
            exact.reservation_expires_at_epoch_ms = reservation.reservation_expires_at_epoch_ms;
            validate_complete_release_authorization_response(
                &exact,
                &reservation,
                requested_outcome,
            )
            .expect("terminal completion must preserve exact authority IDs");

            let mut wrong_grant = test_release_authorization_response(
                state,
                Some(completion_outcome),
                authorized,
                replay,
            );
            wrong_grant.grant_id = Some("grant:other".to_string());
            wrong_grant.approval_request_id = reservation.approval_request_id.clone();
            wrong_grant.reservation_expires_at_epoch_ms =
                reservation.reservation_expires_at_epoch_ms;
            assert!(validate_complete_release_authorization_response(
                &wrong_grant,
                &reservation,
                requested_outcome,
            )
            .is_err());

            let mut wrong_approval = test_release_authorization_response(
                state,
                Some(completion_outcome),
                authorized,
                replay,
            );
            wrong_approval.grant_id = reservation.grant_id.clone();
            wrong_approval.approval_request_id = Some("approval:other".to_string());
            wrong_approval.reservation_expires_at_epoch_ms =
                reservation.reservation_expires_at_epoch_ms;
            assert!(validate_complete_release_authorization_response(
                &wrong_approval,
                &reservation,
                requested_outcome,
            )
            .is_err());
        }
    }

    fn exercise_real_forwarder_reservation_cleanup(branch: &'static str) {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let response_signing_key = SigningKey::from_bytes(&[107u8; 32]);
        let snapshot =
            test_snapshot_with_control_plane_response_key(1, &response_signing_key);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let (mut reserve_stream, reserve_request, reserve_payload) =
                read_release_test_http_request(&listener);
            let attempt_id = reserve_payload["attemptId"]
                .as_str()
                .expect("reserve attempt")
                .to_string();
            let binding_digest =
                test_release_binding_digest(&reserve_payload, false, json!([]));
            let reservation_expires_at_epoch_ms =
                u64::try_from(now_epoch_ms()).expect("current epoch fits u64") + 30_000;
            payload_sender
                .send(reserve_payload)
                .expect("capture reserve");
            let reserve_body = json!({
                "apiVersion":"serverware.releaseAuthorization/v1",
                "ok":true,
                "authorized":true,
                "state":"reserved",
                "reason":"reserved",
                "attemptId":attempt_id.clone(),
                "bindingDigest":binding_digest.clone(),
                "idempotentReplay":false,
                "grantId":null,
                "approvalRequestId":null,
                "approvalStatus":null,
                "approvalExpiresAt":null,
                "approvalCreated":null,
                "reservationExpiresAtEpochMs":reservation_expires_at_epoch_ms,
                "dispatchStartedAtEpochMs":null,
                "dispatchExpiresAtEpochMs":null,
                "completionOutcome":null,
                "retryAfterSeconds":0,
                "quotas":[],
                "store":{"backend":"sqlite","ha":true},
            });
            reserve_stream
                .write_all(&signed_release_test_response(
                    &response_signing_key,
                    &server_snapshot,
                    &reserve_request,
                    StatusCode::OK,
                    reserve_body,
                ))
                .expect("reserve response");

            let (mut completion_stream, completion_request, completion_payload) =
                read_release_test_http_request(&listener);
            payload_sender
                .send(completion_payload)
                .expect("capture completion");
            let completion_body = json!({
                "apiVersion":"serverware.releaseAuthorization/v1",
                "ok":true,
                "authorized":false,
                "state":"cancelled",
                "reason":"cancelled",
                "attemptId":attempt_id,
                "bindingDigest":binding_digest,
                "idempotentReplay":false,
                "grantId":null,
                "approvalRequestId":null,
                "approvalStatus":null,
                "approvalExpiresAt":null,
                "approvalCreated":null,
                "reservationExpiresAtEpochMs":reservation_expires_at_epoch_ms,
                "dispatchStartedAtEpochMs":null,
                "dispatchExpiresAtEpochMs":null,
                "completionOutcome":"not_forwarded",
                "retryAfterSeconds":0,
                "quotas":[],
                "store":{"backend":"sqlite","ha":true},
            });
            completion_stream
                .write_all(&signed_release_test_response(
                    &response_signing_key,
                    &server_snapshot,
                    &completion_request,
                    StatusCode::OK,
                    completion_body,
                ))
                .expect("completion response");
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.upstream_resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![
            "127.0.0.1:443".parse().expect("test upstream address"),
        ])]));
        force_forwarder_post_decision_failure(branch);
        match branch {
            "buffered" => {
                let result = forward_absolute_request_inner(
                    &state,
                    &snapshot,
                    IncomingRequest {
                        method: "GET".to_string(),
                        target: "https://example.test/resource".to_string(),
                        headers: BTreeMap::new(),
                        body: Vec::new(),
                        client_ip: None,
                    },
                    Some("agent:test"),
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                    false,
                );
                let ForwardResult::Buffered(response) = result else {
                    panic!("buffered cleanup fixture unexpectedly streamed");
                };
                assert!(String::from_utf8_lossy(&response)
                    .starts_with("HTTP/1.1 503 Service Unavailable"));
            }
            "streaming" => {
                let stats = Arc::new(Mutex::new(RequestBodyStreamStats::new()));
                let body = RequestBodyStream::new(
                    Box::new(Cursor::new(Vec::<u8>::new())),
                    Vec::new(),
                    0,
                    Arc::clone(&stats),
                );
                let mut output = Vec::new();
                assert!(forward_absolute_streaming_request_to(
                    &state,
                    &snapshot,
                    RequestHead {
                        method: "GET".to_string(),
                        target: "https://example.test/resource".to_string(),
                        http_version: "HTTP/1.1".to_string(),
                        headers: BTreeMap::new(),
                        raw_headers_digest: None,
                        raw_header_count: 0,
                        content_length: 0,
                        has_content_length: true,
                        prefetched_body: Vec::new(),
                        client_ip: None,
                    },
                    body,
                    stats,
                    streaming_rebind_policy(),
                    Some("agent:test"),
                    false,
                    &mut output,
                ));
                assert!(String::from_utf8_lossy(&output)
                    .starts_with("HTTP/1.1 503 Service Unavailable"));
            }
            "intercepted-connect" => {
                let state = Arc::new(state);
                let mut io = DeadlineIo::new(
                    Cursor::new(Vec::<u8>::new()),
                    Duration::from_secs(2),
                    Duration::from_secs(2),
                );
                assert!(forward_intercepted_streaming_request_to(
                    &state,
                    &snapshot,
                    RequestHead {
                        method: "GET".to_string(),
                        target: "https://example.test/resource".to_string(),
                        http_version: "HTTP/1.1".to_string(),
                        headers: BTreeMap::new(),
                        raw_headers_digest: None,
                        raw_header_count: 0,
                        content_length: 0,
                        has_content_length: true,
                        prefetched_body: Vec::new(),
                        client_ip: None,
                    },
                    &mut io,
                    streaming_rebind_policy(),
                    Some("agent:test"),
                    false,
                ));
            }
            _ => panic!("unknown forwarder cleanup branch"),
        }
        server.join().expect("release server");
        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 2, "{branch}");
        assert_eq!(payloads[1]["attemptId"], payloads[0]["attemptId"], "{branch}");
        assert_eq!(
            payloads[1]["bindingDigest"],
            test_release_binding_digest(&payloads[0], false, json!([])),
            "{branch}"
        );
        assert_eq!(payloads[1]["outcome"], "not_forwarded", "{branch}");
    }

