    #[test]
    fn durable_guard_recovery_rejects_outcome_evidence_and_digest_substitution() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let response_signing_key = SigningKey::from_bytes(&[109u8; 32]);
        let snapshot =
            test_snapshot_with_control_plane_response_key(1, &response_signing_key);
        let server_snapshot = Arc::clone(&snapshot);
        let now_ms = u64::try_from(now_epoch_ms()).expect("current epoch fits u64");
        let dispatch_started_at_epoch_ms = now_ms.saturating_sub(1_000);
        let dispatch_expires_at_epoch_ms = now_ms + 20_000;
        let reservation_expires_at_epoch_ms = now_ms + 30_000;
        let durable_reservation = ValidatedDurablePolicyReservation {
            actor_id: "agent:test".to_string(),
            claim_digest: format!("sha256:{}", "e".repeat(64)),
            claims: Vec::new(),
            reservation_id: "reservation:durable-recovery".to_string(),
            reservation_deadline_at_epoch_ms: reservation_expires_at_epoch_ms,
            dispatch_deadline_at_epoch_ms: Some(dispatch_expires_at_epoch_ms),
        };
        let evidence = durable_policy_response_evidence(&durable_reservation, b"{}")
            .expect("validated durable completion evidence");
        let response_evidence_digest = evidence.response_evidence_digest.clone();
        let response_body_sha256 = evidence.response_body_sha256.clone();
        let response_durable_reservation = durable_reservation.clone();
        let server = thread::spawn(move || {
            for _ in 0..4 {
                let (_stream, payload) = read_release_test_request(&listener);
                payload_sender
                    .send(payload)
                    .expect("capture lost completion attempt");
            }
            let (mut stream, request, payload) =
                read_release_test_http_request(&listener);
            payload_sender
                .send(payload)
                .expect("capture exact completion recovery");
            stream
                .write_all(&signed_release_test_response(
                    &response_signing_key,
                    &server_snapshot,
                    &request,
                    StatusCode::OK,
                    json!({
                        "apiVersion":"serverware.releaseAuthorization/v2",
                        "ok":true,
                        "authorized":true,
                        "state":"committed",
                        "reason":"committed",
                        "attemptId":"attempt-test",
                        "bindingDigest":format!("sha256:{}", "a".repeat(64)),
                        "idempotentReplay":true,
                        "grantId":null,
                        "approvalRequestId":null,
                        "reservationExpiresAtEpochMs":reservation_expires_at_epoch_ms,
                        "dispatchStartedAtEpochMs":dispatch_started_at_epoch_ms,
                        "dispatchExpiresAtEpochMs":dispatch_expires_at_epoch_ms,
                        "completionOutcome":"forwarded",
                        "retryAfterSeconds":0,
                        "quotas":[],
                        "store":{"backend":"postgres","ha":true},
                        "durablePolicy":{
                            "state":"committed",
                            "attemptId":"attempt-test",
                            "claimDigest":response_durable_reservation.claim_digest,
                            "reservationId":response_durable_reservation.reservation_id,
                            "actorId":response_durable_reservation.actor_id,
                            "reservationDeadlineAtEpochMs":response_durable_reservation.reservation_deadline_at_epoch_ms,
                            "dispatchDeadlineAtEpochMs":response_durable_reservation.dispatch_deadline_at_epoch_ms,
                            "responseEvidenceDigest":response_evidence_digest,
                            "failureReason":null,
                            "responseBodySha256":response_body_sha256,
                            "uncertainty":null,
                        },
                    }),
                ))
                .expect("completion replay response");
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        let response_authentication =
            AttestedResponseAuthenticationContext::from_snapshot(
                &snapshot,
                "test durable completion recovery",
            )
            .expect("test durable completion response authentication");
        let mut guard = ReleaseAuthorizationGuard {
            state: &state,
            shadow_finalization: None,
            shadow_snapshot: None,
            response_authentication: Some(response_authentication),
            reservation: ReleaseAuthorizationReservation {
                profile: ReleaseProfile::Legacy,
                preparation: None,
                attempt_id: "attempt-test".to_string(),
                binding_digest: format!("sha256:{}", "a".repeat(64)),
                principal_id: "agent:test".to_string(),
                route_id: "route:test".to_string(),
                credential_id: "credential:test".to_string(),
                credential_version: 1,
                policy_hash: format!("sha256:{}", "b".repeat(64)),
                request_digest: format!("sha256:{}", "c".repeat(64)),
                operation_digest: Some(format!("sha256:{}", "d".repeat(64))),
                operation_context: Some(json!({"operation":"test.operation"})),
                grant_id: None,
                approval_request_id: None,
                reservation_expires_at_epoch_ms: Some(reservation_expires_at_epoch_ms),
                shared_quotas: Vec::new(),
                durable_policy: Some(durable_reservation),
                dispatch_started_at_epoch_ms: Some(dispatch_started_at_epoch_ms),
                dispatch_expires_at_epoch_ms: Some(dispatch_expires_at_epoch_ms),
            },
            stage: ReleaseAuthorizationStage::Dispatching,
            terminal_releasable: None,
            retained_completion: None,
            credential_lease_cleanup: CredentialLeaseRequestCleanup::new(&state),
        };
        guard
            .complete_forwarded_with_evidence(&evidence)
            .expect_err("all initial completion replies are lost");
        assert_eq!(guard.stage, ReleaseAuthorizationStage::Dispatching);
        assert!(guard.retained_completion.is_some());

        let uncertainty =
            guard.uncertainty_evidence("provider_outcome_or_response_validation_uncertain");
        assert!(guard
            .complete("unknown", Some(&uncertainty))
            .expect_err("recovery must not substitute unknown for forwarded")
            .contains("substitution"));

        let mut digest_mismatch = evidence.clone();
        digest_mismatch.response_evidence_digest = sha256_prefixed(b"substituted digest");
        assert!(guard
            .complete_forwarded_with_evidence(&digest_mismatch)
            .expect_err("recovery must independently recompute the evidence digest")
            .contains("digest mismatch"));

        let mut body_substitution = evidence.clone();
        body_substitution.response_body_sha256 = sha256_prefixed(b"substituted body");
        assert!(guard
            .complete_forwarded_with_evidence(&body_substitution)
            .expect_err("recovery must retain the original response body digest")
            .contains("substitution"));

        assert!(guard
            .complete_forwarded_with_evidence(&evidence)
            .expect("exact same-attempt replay must recover committed forwarding"));
        assert_eq!(guard.stage, ReleaseAuthorizationStage::Completed);
        assert!(guard.retained_completion.is_none());
        server.join().expect("release server");
        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 5);
        assert!(payloads.iter().all(|payload| payload == &payloads[0]));
        assert_eq!(
            payloads[0]["apiVersion"],
            "serverware.releaseAuthorizationComplete/v2"
        );
        assert_eq!(payloads[0]["outcome"], "forwarded");
        assert_eq!(
            payloads[0]["durablePolicy"]["responseEvidenceDigest"],
            evidence.response_evidence_digest
        );
    }

    #[test]
    fn atomic_release_lifecycle_preserves_attempt_flow_correlation() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("release listener");
        let address = listener.local_addr().expect("release listener address");
        let (payload_sender, payload_receiver) = mpsc::channel();
        let now_ms = u64::try_from(now_epoch_ms()).expect("current epoch fits u64");
        let dispatch_started_at_ms = now_ms.saturating_sub(5_000);
        let reservation_expires_at = now_ms + 30_000;
        let response_signing_key = SigningKey::from_bytes(&[91u8; 32]);
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.response_signing_key_id = Some(test_ed25519_spki_key_id(
            &response_signing_key.verifying_key(),
        ));
        snapshot.response_verifying_key = Some(response_signing_key.verifying_key());
        snapshot.attested_response_context = Some(AttestedResponseContext {
            runtime_manifest_digest: sha256_prefixed(b"test-runtime-manifest"),
            policy_bundle_digest: snapshot.hash.clone(),
            provenance_digest: None,
            image_signatures_digest: None,
            source_tree_digest: None,
        });
        let snapshot = Arc::new(snapshot);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let mut server_binding_digest = None;
            for (state, completion_outcome) in [
                ("reserved", None),
                ("dispatching", None),
                ("committed", Some("forwarded")),
            ] {
                let (mut stream, _) = listener.accept().expect("release request");
                stream
                    .set_read_timeout(Some(Duration::from_secs(2)))
                    .expect("release read timeout");
                let head = read_request_head_from(&mut stream, None).expect("release request head");
                let request = read_request_body_from_head(
                    &mut stream,
                    head,
                    MAX_MANAGEMENT_REQUEST_BODY_BYTES,
                )
                .expect("release request body");
                let payload =
                    strict_json_value_from_slice(&request.body).expect("release JSON");
                if state == "reserved" {
                    server_binding_digest =
                        Some(test_release_binding_digest(&payload, false, json!([])));
                }
                payload_sender
                    .send(payload)
                    .expect("capture release payload");
                let binding_digest = server_binding_digest
                    .as_ref()
                    .expect("reserve establishes binding digest");
                let body = json!({
                    "apiVersion":"serverware.releaseAuthorization/v1",
                    "ok":true,
                    "authorized":true,
                    "state":state,
                    "reason":state,
                    "attemptId":"attempt-test",
                    "bindingDigest":binding_digest,
                    "idempotentReplay":false,
                    "grantId":null,
                    "approvalRequestId":null,
                    "reservationExpiresAtEpochMs":reservation_expires_at,
                    "dispatchStartedAtEpochMs":if state == "reserved" {Value::Null} else {json!(dispatch_started_at_ms)},
                    "dispatchExpiresAtEpochMs":if state == "reserved" {Value::Null} else {json!(now_ms + 10_000)},
                    "completionOutcome":completion_outcome,
                    "retryAfterSeconds":0,
                    "quotas":[],
                    "store":{"backend":"sqlite","ha":true},
                });
                let response = signed_release_test_response(
                    &response_signing_key,
                    &server_snapshot,
                    &request,
                    StatusCode::OK,
                    body,
                );
                stream.write_all(&response).expect("release response");
            }
        });

        let mut state = test_gate_state(snapshot.clone());
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        let route = &snapshot.routes[0];
        let request = provider_test_request(
            "GET",
            "https://example.test/resource",
            BTreeMap::new(),
            "",
            Some(0),
        );
        let provider_url = Url::parse(&request.url).expect("non-JIT provider URL");
        let forwarded_headers = canonical_forwarded_request_headers(
            &request.headers,
            &provider_url,
            None,
            &Value::Null,
        )
        .expect("non-JIT canonical headers");
        let operation = json!({"operation":"read"});
        let canonical = canonical_request(
            &request,
            &forwarded_headers,
            &provider_url,
            &snapshot.principals[0],
            route,
            0,
            &snapshot.hash,
            &operation,
        );
        assert_eq!(canonical["v"], json!(1));
        assert_eq!(canonical["credential_version"], json!("none"));
        canonical_request_discard_headers(&canonical, &[])
            .expect("complete exact canonical v1 non-JIT request");
        let request_digest = digest_json_ensure_ascii(&canonical);
        let expected_operation_digest = operation_digest(&canonical);
        let (raw_release, mut guard) = request_release_authorization(
            &state,
            &snapshot,
            "attempt-test",
            "agent:test",
            route,
            None,
            0,
            &snapshot.hash,
            &request_digest,
            &expected_operation_digest,
            &operation,
            &canonical,
            &request,
            false,
            None,
        )
        .expect("request release authorization");
        let release = validate_requested_release_authorization(
            raw_release,
            "attempt-test",
            false,
        )
        .expect("validate release authorization");
        guard.reservation.grant_id = release.grant_id.clone();
        guard.reservation.approval_request_id = release.approval_request_id.clone();
        guard.reservation.reservation_expires_at_epoch_ms =
            release.reservation_expires_at_epoch_ms;
        guard.reservation.shared_quotas = release.validated_quotas;
        let dispatch_observation = guard
            .dispatch(&snapshot)
            .expect("dispatch release authorization");
        assert_eq!(
            dispatch_observation.observed_at_epoch_ms,
            dispatch_started_at_ms
        );
        guard
            .complete_forwarded()
            .expect("complete forwarded release authorization");
        server.join().expect("release server");

        let payloads = payload_receiver.iter().collect::<Vec<_>>();
        assert_eq!(payloads.len(), 3);
        assert_eq!(payloads[0]["attemptId"], "attempt-test");
        assert_eq!(payloads[0]["flowId"], "attempt-test");
        assert_eq!(payloads[0]["requestDigest"], request_digest);
        assert_eq!(payloads[0]["operationDigest"], expected_operation_digest);
        assert_eq!(payloads[0]["canonicalRequest"], canonical);
        assert!(payloads[0].get("redactedDisplay").is_none());
        assert_eq!(
            payloads[1]["bindingDigest"],
            test_release_binding_digest(&payloads[0], false, json!([]))
        );
        assert_eq!(payloads[1]["attemptId"], "attempt-test");
        assert_eq!(payloads[2]["attemptId"], "attempt-test");
        assert_eq!(payloads[2]["outcome"], "forwarded");
    }

    #[test]
    fn enrollment_session_header_is_strict_singleton_base64url() {
        for session_id in ["a".repeat(24), "Z_9-".repeat(32)] {
            let raw = format!(
                "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {session_id}\r\n\r\n"
            );
            let head = parse_head(raw.as_bytes()).expect("valid enrollment session header");
            assert_eq!(
                enrollment_session_id_from_headers(&head.headers)
                    .expect("validated enrollment session"),
                Some(session_id)
            );
        }

        for invalid in [
            "a".repeat(23),
            "a".repeat(129),
            format!("{}=", "a".repeat(23)),
            format!("{},b", "a".repeat(24)),
        ] {
            let raw = format!(
                "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {invalid}\r\n\r\n"
            );
            assert!(parse_head(raw.as_bytes())
                .err()
                .expect("malformed enrollment session must fail closed")
                .contains("24-128 base64url"));
        }

        let session_id = "a".repeat(24);
        let duplicate = format!(
            "CONNECT example.test:443 HTTP/1.1\r\nHost: example.test:443\r\nX-Serverware-Enrollment-Session: {session_id}\r\nx-serverware-enrollment-session: {session_id}\r\n\r\n"
        );
        assert_eq!(
            parse_head(duplicate.as_bytes())
                .err()
                .expect("duplicate enrollment session must fail closed"),
            "request_header_ambiguous"
        );

        let ambiguous = BTreeMap::from([
            (
                "X-Serverware-Enrollment-Session".to_string(),
                session_id.clone(),
            ),
            ("x-serverware-enrollment-session".to_string(), session_id),
        ]);
        assert!(enrollment_session_id_from_headers(&ambiguous)
            .expect_err("case-ambiguous enrollment session must fail closed")
            .contains("ambiguous"));
    }

    #[test]
    fn connect_enrollment_session_is_inherited_but_cannot_be_overridden() {
        let session_id = "A_-0123456789abcdefghijk";
        assert_eq!(session_id.len(), 24);
        let mut inner_headers = BTreeMap::new();
        inherit_connect_enrollment_session(&mut inner_headers, Some(session_id))
            .expect("CONNECT enrollment context");
        assert_eq!(
            enrollment_session_id_from_headers(&inner_headers)
                .expect("inherited enrollment context")
                .as_deref(),
            Some(session_id)
        );

        let mut supplied_inner =
            BTreeMap::from([(ENROLLMENT_SESSION_HEADER.to_string(), "b".repeat(24))]);
        assert!(
            inherit_connect_enrollment_session(&mut supplied_inner, Some(session_id))
                .expect_err("inner request must not override CONNECT enrollment context")
                .contains("must not supply")
        );
    }

    #[test]
    fn service_token_configuration_preserves_env_defaults_and_rejects_dual_sources() {
        assert_eq!(
            configured_service_token_values(
                "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
                Some(OsString::from("  development-token  ")),
                None,
            )
            .expect("environment token"),
            Some("development-token".to_string())
        );
        assert_eq!(
            configured_service_token_values(
                "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
                Some(OsString::new()),
                None,
            )
            .expect("blank environment token preserves the existing default"),
            None
        );
        assert_eq!(
            configured_service_token_values("SERVERWARE_DATA_PLANE_AUDIT_TOKEN", None, None,)
                .expect("unconfigured token"),
            None
        );
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            Some(OsString::new()),
            Some(OsString::new()),
        )
        .expect_err("blank but present sources must remain mutually exclusive")
        .contains("mutually exclusive"));
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            None,
            Some(OsString::new()),
        )
        .expect_err("blank token file path")
        .contains("must identify"));
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            None,
            Some(OsString::from("relative-token-file")),
        )
        .expect_err("relative token file path")
        .contains("absolute path"));
    }

    #[test]
    fn service_token_file_accepts_secure_owner_and_group_readable_modes() {
        for mode in [0o400, 0o600, 0o440, 0o640] {
            let token = format!("audit-service-token-ABCDEFGHIJKLMNOPQRSTUVWXYZ-{mode:o}");
            let path = write_test_service_token_file(
                &format!("service-token-mode-{mode:o}"),
                token.as_bytes(),
                mode,
            );
            assert_eq!(
                configured_service_token_values(
                    "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
                    None,
                    Some(path.as_os_str().to_os_string()),
                )
                .expect("secure token file"),
                Some(token)
            );
            fs::remove_file(path).expect("remove service token fixture");
        }
    }

    #[test]
    fn service_token_file_rejects_links_nonregular_files_size_modes_and_content() {
        let target = write_test_service_token_file(
            "service-token-symlink-target",
            b"audit-service-token-ABCDEFGHIJKLMNOPQRSTUVWXYZ-01",
            0o600,
        );
        let link = test_temp_path("service-token-symlink");
        std::os::unix::fs::symlink(&target, &link).expect("create service token symlink");
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            None,
            Some(link.as_os_str().to_os_string()),
        )
        .expect_err("service token symlink")
        .contains("must not be a symlink"));
        fs::remove_file(link).expect("remove service token symlink");
        fs::remove_file(target).expect("remove service token target");

        let directory = test_temp_path("service-token-directory");
        fs::create_dir(&directory).expect("create service token directory");
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            None,
            Some(directory.as_os_str().to_os_string()),
        )
        .expect_err("service token directory")
        .contains("regular file"));
        fs::remove_dir(directory).expect("remove service token directory");

        let oversized = write_test_service_token_file(
            "service-token-oversized",
            &vec![b'a'; MAX_INTERNAL_SERVICE_TOKEN_FILE_BYTES as usize + 1],
            0o600,
        );
        assert!(configured_service_token_values(
            "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
            None,
            Some(oversized.as_os_str().to_os_string()),
        )
        .expect_err("oversized service token")
        .contains("must contain"));
        fs::remove_file(oversized).expect("remove oversized service token fixture");

        for mode in [0o200, 0o444, 0o644, 0o700] {
            let path = write_test_service_token_file(
                &format!("service-token-insecure-mode-{mode:o}"),
                b"audit-service-token-ABCDEFGHIJKLMNOPQRSTUVWXYZ-02",
                mode,
            );
            assert!(
                configured_service_token_values(
                    "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
                    None,
                    Some(path.as_os_str().to_os_string()),
                )
                .is_err(),
                "accepted service token mode {mode:o}"
            );
            fs::remove_file(path).expect("remove insecure service token fixture");
        }

        for (label, contents) in [
            ("empty", b"".as_slice()),
            ("leading-space", b" token".as_slice()),
            ("trailing-space", b"token ".as_slice()),
            ("embedded-newline", b"token\nsecond".as_slice()),
            ("embedded-space", b"token second".as_slice()),
            ("embedded-unicode-space", "token\u{2003}second".as_bytes()),
            ("embedded-control", b"token\0second".as_slice()),
        ] {
            let path = write_test_service_token_file(
                &format!("service-token-invalid-{label}"),
                contents,
                0o600,
            );
            assert!(
                configured_service_token_values(
                    "SERVERWARE_DATA_PLANE_AUDIT_TOKEN",
                    None,
                    Some(path.as_os_str().to_os_string()),
                )
                .is_err(),
                "accepted invalid service token content {label}"
            );
            fs::remove_file(path).expect("remove invalid service token fixture");
        }
    }

    #[test]
    fn internal_service_tokens_are_scoped_strong_and_distinct() {
        let credential_lease =
            Some("credential-lease-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-01".to_string());
        let audit = Some("audit-ingest-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-02".to_string());
        let grant = Some("grant-consume-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-03".to_string());
        let rate_limit = Some("rate-limit-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-04".to_string());
        let release = Some("release-authorization-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-05".to_string());
        let management = Some("rust-management-scope-ABCDEFGHIJKLMNOPQRSTUVWXYZ-06".to_string());
        let names_and_tokens = [
            ("credential", &credential_lease),
            ("audit", &audit),
            ("grant", &grant),
            ("rate-limit", &rate_limit),
            ("release", &release),
            ("management", &management),
        ];
        validate_internal_service_tokens(true, &names_and_tokens)
            .expect("distinct production service tokens");

        let missing = None;
        assert!(
            validate_internal_service_tokens(true, &[("missing", &missing)])
                .expect_err("missing production token")
                .contains("missing")
        );
        let weak = Some("x".repeat(32));
        assert!(validate_internal_service_tokens(true, &[("weak", &weak)])
            .expect_err("weak production token")
            .contains("high-entropy"));
        let duplicate = audit.clone();
        assert!(validate_internal_service_tokens(
            true,
            &[("audit", &audit), ("credential", &duplicate)],
        )
        .expect_err("equal production tokens")
        .contains("distinct"));
        let optional_weak = Some("optional-but-weak".to_string());
        assert!(validate_configured_internal_service_tokens(
            true,
            &[
                ("credential", &credential_lease),
                ("optional", &optional_weak)
            ],
        )
        .expect_err("configured weak optional token")
        .contains("high-entropy"));
    }

