    #[test]
    fn ambient_authority_and_service_auth_headers_are_stripped_before_upstream_and_proof() {
        let headers = BTreeMap::from([
            (
                "Authorization".to_string(),
                "Bearer ambient-authority".to_string(),
            ),
            (
                "Cookie".to_string(),
                "ambient_session=caller-controlled".to_string(),
            ),
            (
                "Proxy-Authorization".to_string(),
                "Basic ambient-proxy-authority".to_string(),
            ),
            (
                "X-Serverware-Admin-Token".to_string(),
                "admin-secret".to_string(),
            ),
            (
                "X-Serverware-Audit-Anchor-Token".to_string(),
                "anchor-secret".to_string(),
            ),
            (
                "X-Serverware-CA-Install-Token".to_string(),
                "ca-install-secret".to_string(),
            ),
            (
                "X-Serverware-CSRF-Token".to_string(),
                "csrf-secret".to_string(),
            ),
            (
                "X-Serverware-Data-Plane-Token".to_string(),
                "service-secret".to_string(),
            ),
            (
                "X-Serverware-Response-Nonce".to_string(),
                "future-internal-value".to_string(),
            ),
            (
                "x-SeRvErWaRe-Future-Internal".to_string(),
                "future-mixed-case-value".to_string(),
            ),
            (
                "X-Serverware-Enrollment-Session".to_string(),
                "A_-0123456789abcdefghijk".to_string(),
            ),
            ("X-Serverware-Agent".to_string(), "agent:test".to_string()),
            ("X-Visible".to_string(), "visible".to_string()),
        ]);
        let forwarded = client_forward_header_material(&headers, &json!({"type":"bearer"}))
            .expect("forwarded headers");
        assert_eq!(
            forwarded,
            BTreeMap::from([("x-visible".to_string(), "visible".to_string())])
        );
        let proof = canonical_client_proof_headers(&headers).expect("proof headers");
        assert_eq!(proof, forwarded);

        let url = Url::parse("https://upstream.invalid/resource").expect("test URL");
        let canonical =
            canonical_forwarded_request_headers(&headers, &url, None, &json!({"type":"bearer"}))
                .expect("canonical forwarded headers");
        assert_eq!(
            canonical,
            BTreeMap::from([
                ("host".to_string(), "upstream.invalid".to_string()),
                ("x-visible".to_string(), "visible".to_string()),
            ])
        );
        let upstream = filtered_forward_headers(&headers, &json!({"type":"bearer"}), &[])
            .expect("actual upstream headers");
        assert_eq!(upstream.len(), 1);
        assert_eq!(
            upstream
                .get("x-visible")
                .and_then(|value| value.to_str().ok()),
            Some("visible")
        );
        assert!(!upstream.contains_key("x-serverware-response-nonce"));
        assert!(!upstream.contains_key("x-serverware-future-internal"));
    }

    #[test]
    fn malformed_generic_policy_cannot_forward_internal_prefix_to_upstream_or_proof() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("test upstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking upstream listener");
        let upstream = listener.local_addr().expect("test upstream address");
        let server = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(2);
            loop {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        stream
                            .set_read_timeout(Some(Duration::from_secs(1)))
                            .expect("upstream read timeout");
                        let mut request = Vec::new();
                        let mut buffer = [0_u8; 1024];
                        while !request.windows(4).any(|window| window == b"\r\n\r\n") {
                            let read = stream.read(&mut buffer).expect("read upstream request");
                            assert!(read > 0, "upstream request ended before its header block");
                            request.extend_from_slice(&buffer[..read]);
                        }
                        stream
                            .write_all(
                                b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 13\r\n\r\n{\"safe\":true}",
                            )
                            .expect("write upstream response");
                        return String::from_utf8(request).expect("ASCII upstream request");
                    }
                    Err(err) if err.kind() == io::ErrorKind::WouldBlock => {
                        assert!(
                            Instant::now() < deadline,
                            "request did not reach test upstream"
                        );
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(err) => panic!("accept test upstream request: {err}"),
                }
            }
        });

        let mut snapshot = (*test_snapshot(1)).clone();
        let route = &mut snapshot.routes[0];
        route.scheme = "http".to_string();
        route.host = upstream.ip().to_string();
        route.port = upstream.port();
        route.methods = HashSet::from(["GET".to_string()]);
        route.adapter_config["request"] = json!({
            "allowedHeaders":["accept", "x-serverware-response-nonce"],
            "allowedQueryKeys":[],
            "bodyMode":"none",
            "discardHeaders":["npm-session"],
            "maxBodyBytes":0
        });
        route.discard_headers = vec!["npm-session".to_string()];
        let snapshot = Arc::new(snapshot);
        let state = test_gate_state(Arc::clone(&snapshot));
        let headers = BTreeMap::from([
            ("Accept".to_string(), "application/json".to_string()),
            (
                "Npm-Session".to_string(),
                "must-not-reach-the-buffered-upstream".to_string(),
            ),
            (
                "X-Serverware-Response-Nonce".to_string(),
                "must-not-leave-the-data-plane".to_string(),
            ),
        ]);
        let result = forward_absolute_request_inner(
            &state,
            &snapshot,
            IncomingRequest {
                method: "GET".to_string(),
                target: format!("http://{upstream}/resource"),
                headers: headers.clone(),
                body: Vec::new(),
                client_ip: Some("127.0.0.1".to_string()),
            },
            Some("agent:test"),
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        );
        let response = match result {
            ForwardResult::Buffered(response) => {
                String::from_utf8(response.to_vec()).expect("buffered HTTP response")
            }
            ForwardResult::Streamed => panic!("test response unexpectedly streamed"),
        };
        assert!(response.starts_with("HTTP/1.1 200"), "{response}");

        let captured = server.join().expect("test upstream thread");
        assert!(captured
            .to_ascii_lowercase()
            .contains("accept: application/json"));
        assert!(!captured.to_ascii_lowercase().contains("npm-session"));
        assert!(!captured.contains("must-not-reach-the-buffered-upstream"));
        assert!(!captured.to_ascii_lowercase().contains("x-serverware-"));
        assert_eq!(
            canonical_client_proof_headers(&headers).expect("proof headers"),
            BTreeMap::from([("accept".to_string(), "application/json".to_string())])
        );
    }

    #[test]
    fn specialized_adapters_strip_ambient_cookie_before_credential_injection() {
        let injection = json!({"type":"bearer"});
        let url = Url::parse("https://api.example.test/resource").expect("test URL");
        let headers = BTreeMap::from([
            (
                "Authorization".to_string(),
                "Bearer ambient-authority".to_string(),
            ),
            (
                "Cookie".to_string(),
                "ambient_session=caller-controlled".to_string(),
            ),
            ("Host".to_string(), "caller.example.test".to_string()),
            (
                "Proxy-Authorization".to_string(),
                "Basic ambient-proxy-authority".to_string(),
            ),
            (
                "X-Serverware-Data-Plane-Token".to_string(),
                "service-session".to_string(),
            ),
            (
                "X-Serverware-Proof-Nonce".to_string(),
                "proof-nonce".to_string(),
            ),
            ("X-Visible".to_string(), "visible".to_string()),
        ]);
        let sanitized = client_forward_header_material(&headers, &injection)
            .expect("shared forwarding sanitizer");
        assert_eq!(
            sanitized,
            BTreeMap::from([("x-visible".to_string(), "visible".to_string())])
        );
        assert_eq!(
            canonical_client_proof_headers(&headers).expect("proof headers"),
            sanitized
        );

        let canonical = canonical_forwarded_request_headers(&headers, &url, None, &injection)
            .expect("canonical forwarded headers");
        assert_eq!(canonical["host"], "api.example.test");
        assert_eq!(canonical["x-visible"], "visible");
        assert!(!canonical.contains_key("cookie"));
        let canonical_digest = digest_json(&json!({"headers":canonical}));

        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        let mut lease = test_secret_lease(
            &test_snapshot(1),
            scope,
            1,
            "upstream-secret",
            BTreeMap::new(),
        );
        lease.policy_hash = "sha256:policy".to_string();
        for adapter_type in SUPPORTED_ADAPTER_TYPES
            .iter()
            .copied()
            .filter(|adapter_type| *adapter_type != "generic.rest")
        {
            let mut upstream = filtered_forward_headers(&headers, &injection, &[])
                .expect("actual upstream headers before credential injection");
            assert_eq!(upstream.len(), sanitized.len(), "{adapter_type}");
            assert_eq!(
                upstream
                    .get("x-visible")
                    .and_then(|value| value.to_str().ok()),
                Some("visible"),
                "{adapter_type}"
            );
            assert!(!upstream.contains_key("cookie"), "{adapter_type}");
            assert!(!upstream.contains_key("authorization"), "{adapter_type}");
            assert!(
                !upstream.contains_key("proxy-authorization"),
                "{adapter_type}"
            );

            let mut upstream_url = url.clone();
            let _guard =
                apply_credential_injection(&mut upstream, &mut upstream_url, &injection, &lease)
                    .expect("server credential injection");
            assert!(!upstream.contains_key("cookie"), "{adapter_type}");
            assert_eq!(
                upstream
                    .get("authorization")
                    .and_then(|value| value.to_str().ok()),
                Some("Bearer upstream-secret"),
                "{adapter_type}"
            );
        }

        let mut changed_cookie = headers.clone();
        changed_cookie.insert(
            "Cookie".to_string(),
            "ambient_session=different-caller-value".to_string(),
        );
        let changed_canonical =
            canonical_forwarded_request_headers(&changed_cookie, &url, None, &injection)
                .expect("canonical headers after ambient cookie change");
        assert_eq!(
            canonical_digest,
            digest_json(&json!({"headers":changed_canonical}))
        );

        let context = ResponseProofContext {
            client_nonce: "proof-nonce".to_string(),
            client_nonce_bytes: vec![7; 32],
            tls_exporter: "test-exporter".to_string(),
        };
        let proof_request = IncomingRequest {
            method: "GET".to_string(),
            target: url.to_string(),
            headers,
            body: Vec::new(),
            client_ip: Some("127.0.0.1".to_string()),
        };
        let proof_digest =
            client_proof_request_digest(&proof_request, &context).expect("proof request digest");
        let changed_proof_request = IncomingRequest {
            method: "GET".to_string(),
            target: url.to_string(),
            headers: changed_cookie,
            body: Vec::new(),
            client_ip: Some("127.0.0.1".to_string()),
        };
        assert_eq!(
            proof_digest,
            client_proof_request_digest(&changed_proof_request, &context)
                .expect("proof request digest after ambient cookie change")
        );
    }

