    #[test]
    fn duplicate_query_reversal_is_denied_before_jit_and_grant_consumption() {
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.routes[0].adapter_config["request"]["allowedQueryKeys"] = json!(["mode"]);
        snapshot.routes[0].jit = json!({
            "required":true,
            "ttlSeconds":30,
            "maxUses":1,
        });
        let snapshot = Arc::new(snapshot);
        let resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![
            "127.0.0.1:443".parse().expect("test upstream address"),
        ])]));
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.upstream_resolver = resolver.clone();
        state.grants.lock().expect("grant cache").insert(
            "sha256:unrelated-approved-grant".to_string(),
            Grant {
                id: "grant:unrelated".to_string(),
                approval_id: Some("approval:unrelated".to_string()),
                max_uses: 1,
                ttl_seconds: 30,
                uses_remaining: 1,
                expires_at_ms: now_epoch_ms() + 30_000,
            },
        );
        let request = |query: &str| DecisionRequest {
            client_ip: None,
            method: "GET".to_string(),
            url: format!("https://example.test/resource?{query}"),
            headers: BTreeMap::new(),
            body: String::new(),
            body_sha256: Some(sha256_prefixed(b"")),
            forwarded_body_length: Some(0),
            forwarded_body_utf8_valid: Some(true),
            credential_metadata: BTreeMap::new(),
            gmail_proofs: Vec::new(),
            client_request_digest: None,
        };

        let duplicate_head = parse_head(
            b"GET https://example.test/resource?mode=read&mode=delete HTTP/1.1\r\nHost: example.test\r\n\r\n",
        )
        .expect("duplicate-query request head");
        let duplicate_url = Url::parse(&duplicate_head.target).expect("duplicate-query URL");
        assert!(prepare_upstream_for_forward(
            &state,
            &snapshot,
            &duplicate_head,
            &duplicate_url,
            Some("agent:test"),
        )
        .expect("duplicate-query preflight")
        .is_none());
        assert_eq!(resolver.calls(), 0);
        assert_eq!(resolver.remaining_answers(), 1);

        for query in ["mode=read&mode=delete", "mode=delete&mode=read"] {
            let denied = decide_internal(&state, &snapshot, request(query), Some("agent:test"));
            assert_eq!(denied["status_code"], 400);
            assert_eq!(denied["payload"]["error"], "duplicate_query_key_denied");
            assert_eq!(denied["payload"]["key"], "mode");
            assert!(denied.get("request_digest").is_none());
            assert!(denied.get("operation_digest").is_none());
            assert!(denied.get("approval_id").is_none());
        }
        assert_eq!(
            state
                .grants
                .lock()
                .expect("grant cache")
                .values()
                .next()
                .expect("unrelated grant")
                .uses_remaining,
            1
        );
        assert!(state
            .constraint_rate_counters
            .lock()
            .expect("rate counters")
            .is_empty());
        assert!(state.audit_queue.lock().expect("audit queue").is_empty());
    }

    #[test]
    fn duplicate_and_discard_policy_admission_precede_dns_and_client_cache() {
        let snapshot = test_snapshot(1);
        let resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![
            "127.0.0.1:443".parse().expect("test upstream address"),
        ])]));
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.upstream_resolver = resolver.clone();
        let target_url = Url::parse("https://example.test/resource").expect("test URL");
        let ambiguous = RequestHead {
            method: "GET".to_string(),
            target: target_url.to_string(),
            http_version: "HTTP/1.1".to_string(),
            headers: BTreeMap::from([
                ("X-Client-Marker".to_string(), "first".to_string()),
                ("x-client-marker".to_string(), "second".to_string()),
            ]),
            raw_headers_digest: None,
            raw_header_count: 2,
            content_length: 0,
            has_content_length: false,
            prefetched_body: Vec::new(),
            client_ip: None,
        };
        assert!(prepare_upstream_for_forward(
            &state,
            &snapshot,
            &ambiguous,
            &target_url,
            Some("agent:test"),
        )
        .expect("duplicate-header preflight")
        .is_none());
        assert_eq!(resolver.calls(), 0);
        assert!(state
            .pinned_upstream_clients
            .lock()
            .expect("pinned upstream client cache")
            .entries
            .is_empty());

        let mut invalid_snapshot = (*snapshot).clone();
        invalid_snapshot.routes[0].discard_headers = vec!["x-client-retry".to_string()];
        let invalid_snapshot = Arc::new(invalid_snapshot);
        let invalid_resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![
            "127.0.0.1:443".parse().expect("test upstream address"),
        ])]));
        let mut invalid_state = test_gate_state(Arc::clone(&invalid_snapshot));
        invalid_state.upstream_resolver = invalid_resolver.clone();
        let mut valid_head = ambiguous;
        replace_string_map(&mut valid_head.headers, BTreeMap::new());
        valid_head.raw_header_count = 0;
        assert!(prepare_upstream_for_forward(
            &invalid_state,
            &invalid_snapshot,
            &valid_head,
            &target_url,
            Some("agent:test"),
        )
        .expect("discard-policy preflight")
        .is_none());
        assert_eq!(invalid_resolver.calls(), 0);
        assert!(invalid_state
            .pinned_upstream_clients
            .lock()
            .expect("pinned upstream client cache")
            .entries
            .is_empty());
    }

    #[test]
    fn denied_request_audit_promotes_canonical_payload_error() {
        let route = test_snapshot(1).routes[0].clone();
        let arbitrary_query_key = "caller-chosen-secret-key";
        let arbitrary_query_value = "caller-secret-must-not-enter-audit";
        let decision = deny(
            403,
            "JSON body contains a field outside the allowlist",
            json!({
                "error":"json_body_field_not_allowed",
                "reason":"JSON body contains a field outside the allowlist",
                "field":"unknown"
            }),
            Instant::now(),
        );
        let event = decision_audit_event(
            &decision,
            "POST",
            &Url::parse(&format!(
                "https://example.test/resource?{arbitrary_query_key}={arbitrary_query_value}"
            ))
            .expect("audit URL"),
            "denied",
            json!({"stage":"policy_decision"}),
        );

        assert_eq!(event["error"], "json_body_field_not_allowed");
        assert_eq!(
            event["reason"],
            "JSON body contains a field outside the allowlist"
        );
        assert!(event.get("payload").is_none());
        assert_eq!(event["url"]["query_keys"], json!([]));
        let serialized = canonical_json_ensure_ascii(&event);
        assert!(!serialized.contains(arbitrary_query_key));
        assert!(!serialized.contains(arbitrary_query_value));

        let routed = deny_for_route(
            500,
            "provider request profile is invalid",
            json!({"error":"provider_request_profile_invalid","adapter":route.adapter_type}),
            &route,
            Instant::now(),
        );
        let routed_event = decision_audit_event(
            &routed,
            "POST",
            &Url::parse(&format!(
                "https://example.test/resource?{arbitrary_query_key}={arbitrary_query_value}"
            ))
            .expect("audit URL"),
            "denied",
            json!({"stage":"policy_decision"}),
        );
        assert_eq!(routed_event["route_id"], route.id);
        assert_eq!(routed_event["adapter"], route.adapter_type);
        assert_eq!(routed_event["error"], "provider_request_profile_invalid");
        assert_eq!(routed_event["url"]["query_keys"], json!([]));
        assert!(routed_event.get("payload").is_none());
        let routed_serialized = canonical_json_ensure_ascii(&routed_event);
        assert!(!routed_serialized.contains(arbitrary_query_key));
        assert!(!routed_serialized.contains(arbitrary_query_value));
    }

