    pub(super) fn policy_with_route(mut route: Value) -> Value {
        let constraints = route
            .as_object_mut()
            .expect("test route object")
            .entry("constraints")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .expect("test route constraints");
        if !constraints.iter().any(|constraint| {
            constraint.get("type").and_then(Value::as_str) == Some("responseEnvelope")
        }) {
            constraints.push(json!({
                "id":"response-envelope",
                "type":"responseEnvelope",
                "phase":"response",
                "statusCodes":[200],
                "bodyPresence":"required",
                "contentTypes":["application/json"],
                "allowedResponseHeaderNames":[],
                "responseHeaderRules":[],
            }));
        }
        let mut credentials = Vec::new();
        if let Some(credential_id) = route
            .get("credentialRef")
            .and_then(Value::as_str)
            .map(str::to_string)
        {
            let adapter_type = route
                .pointer("/adapter/type")
                .and_then(Value::as_str)
                .expect("test route adapter type")
                .to_string();
            let (credential, binding) = match adapter_type.as_str() {
                "gmail.v1" => {
                    let client_id = "test-gmail-client";
                    let scopes = json!(["https://www.googleapis.com/auth/gmail.readonly"]);
                    (
                        json!({
                            "id":credential_id,
                            "credentialType":"oauth2",
                            "provider":"google",
                            "providerSubject":"test-google-account",
                            "oauthClientId":client_id,
                            "scopes":scopes,
                            "injection":{"type":"bearer","field":"access_token"},
                        }),
                        json!({
                            "credentialType":"oauth2",
                            "provider":"google",
                            "subjects":["test-google-account"],
                            "clientIds":[client_id],
                            "requiredScopes":scopes,
                        }),
                    )
                }
                "x.v2" => {
                    let app_ids = route
                        .pointer("/adapter/config/appIds")
                        .and_then(Value::as_array)
                        .cloned()
                        .unwrap_or_else(|| vec![json!("test-x-client")]);
                    let client_id = app_ids
                        .first()
                        .and_then(Value::as_str)
                        .unwrap_or("test-x-client")
                        .to_string();
                    let operations = if route
                        .pointer("/adapter/config/mode")
                        .and_then(Value::as_str)
                        == Some("controlledWrite")
                    {
                        vec!["tweets.write".to_string()]
                    } else {
                        route
                            .pointer("/adapter/config/allowedReadOperations")
                            .and_then(Value::as_array)
                            .into_iter()
                            .flatten()
                            .filter_map(Value::as_str)
                            .map(str::to_string)
                            .collect::<Vec<_>>()
                    };
                    let mut scopes = operations
                        .iter()
                        .flat_map(|operation| {
                            oauth_scopes_for_operation("x.v2", operation)
                                .unwrap_or_else(|| {
                                    oauth_scopes_for_operation("x.v2", "search.read")
                                        .expect("test X fallback scope catalog")
                                })
                                .iter()
                                .copied()
                        })
                        .map(str::to_string)
                        .collect::<Vec<_>>();
                    scopes.sort();
                    scopes.dedup();
                    if scopes.is_empty() {
                        scopes = vec!["tweet.read".to_string(), "users.read".to_string()];
                    }
                    (
                        json!({
                            "id":credential_id,
                            "credentialType":"oauth2",
                            "provider":"x",
                            "providerSubject":"test-x-account",
                            "oauthClientId":client_id,
                            "scopes":scopes,
                            "injection":{"type":"bearer","field":"access_token"},
                        }),
                        json!({
                            "credentialType":"oauth2",
                            "provider":"x",
                            "subjects":["test-x-account"],
                            "clientIds":app_ids,
                            "requiredScopes":scopes,
                        }),
                    )
                }
                "npm.registry" => (
                    json!({
                        "id":credential_id,
                        "credentialType":"static",
                        "provider":"npm",
                        "providerSubject":"test-npm-account",
                        "injection":{"type":"bearer"},
                    }),
                    json!({
                        "credentialType":"static",
                        "provider":"npm",
                        "subjects":["test-npm-account"],
                        "secretClass":"automationToken",
                    }),
                ),
                _ => (
                    json!({
                        "id":credential_id,
                        "credentialType":"static",
                        "provider":"generic",
                        "providerSubject":"account:test",
                        "injection":{"type":"bearer"},
                    }),
                    json!({
                        "credentialType":"static",
                        "provider":"generic",
                        "subjects":["account:test"],
                        "secretClass":"bearerToken",
                    }),
                ),
            };
            let adapter_config = route
                .pointer_mut("/adapter/config")
                .and_then(Value::as_object_mut)
                .expect("test adapter config");
            adapter_config.insert("credentialBinding".to_string(), binding);
            if adapter_type == "generic.rest" {
                adapter_config.insert("credentialMode".to_string(), json!("required"));
                adapter_config.remove("noCredentialProof");
            } else if adapter_type == "x.v2" && !adapter_config.contains_key("appIds") {
                adapter_config.insert(
                    "appIds".to_string(),
                    credential
                        .get("oauthClientId")
                        .cloned()
                        .map(|value| Value::Array(vec![value]))
                        .unwrap_or_else(|| json!(["test-x-client"])),
                );
            }
            credentials.push(credential);
        }
        json!({
            "metadata": {},
            "defaults": {
                "action":"deny",
                "failMode":"closed",
                "unknownHosts":"block",
                "unknownPaths":"block",
                "validationFailure":"block"
            },
            "principals":[{"id":"agent:test","sourceCidrs":["127.0.0.1/32"]}],
            "credentials":credentials,
            "routes":[route]
        })
    }

    fn provider_request_profile_json(adapter_type: &str, mode: Option<&str>) -> Value {
        let profile = provider_request_profile(adapter_type, mode)
            .expect("provider request profile")
            .expect("specialized adapter request profile");
        let discard_headers = if adapter_type == "npm.registry" {
            NPM_CANONICAL_DISCARD_HEADERS
        } else {
            &[]
        };
        json!({
            "allowedHeaders":profile.allowed_headers,
            "allowedQueryKeys":profile.allowed_query_keys,
            "allowedMediaTypes":profile.allowed_media_types,
            "discardHeaders":discard_headers,
            "maxBodyBytes":profile.max_body_bytes,
            "valueRules":[],
        })
    }

    fn specialized_test_route(adapter_type: &str, mode: Option<&str>) -> Route {
        let mut route = test_snapshot(1).routes[0].clone();
        route.adapter_type = adapter_type.to_string();
        route.adapter_config = json!({
            "request":provider_request_profile_json(adapter_type, mode),
        });
        route.discard_headers = (if adapter_type == "npm.registry" {
            NPM_CANONICAL_DISCARD_HEADERS
        } else {
            &[]
        })
            .iter()
            .map(|name| (*name).to_string())
            .collect();
        if let Some(mode) = mode {
            route.adapter_config["mode"] = json!(mode);
        }
        route
    }

