    fn sign_test_policy(
        mut policy: Value,
        signing_key: &SigningKey,
        signing_key_id: &str,
        sequence: u64,
    ) -> Value {
        policy["apiVersion"] = json!("serverware.policy/v1");
        policy["kind"] = json!("PolicyBundle");
        policy["metadata"] = json!({
            "id":"policy:test",
            "sequence":sequence,
            "rollbackEpoch":1,
            "signingKeyId":signing_key_id,
        });
        let payload = canonical_json(&signature_payload(&policy));
        let signature = signing_key.sign(payload.as_bytes());
        policy["metadata"]["signature"] = json!(format!(
            "ed25519:{}",
            general_purpose::URL_SAFE_NO_PAD.encode(signature.to_bytes())
        ));
        policy
    }

    fn load_compiled_test_snapshot(policy: Value, label: &str, sequence: u64) -> Snapshot {
        let policy_path = test_temp_path(&format!("{label}-policy.json"));
        let trust_path = test_temp_path(&format!("{label}-trust.pem"));
        let (signing_key, public_key_pem, signing_key_id) =
            response_proof_signing_material().expect("test policy signing material");
        fs::write(&trust_path, public_key_pem).expect("write test policy trust root");
        let signed = sign_test_policy(policy, &signing_key, &signing_key_id, sequence);
        fs::write(
            &policy_path,
            serde_json::to_vec(&signed).expect("serialize signed test policy"),
        )
        .expect("write signed test policy");
        let trust_source =
            PolicyTrustRootSource::File(trust_path.to_string_lossy().into_owned());
        let loaded = load_snapshot(
            &policy_path.to_string_lossy(),
            &trust_source,
            "sha256:test-binary",
        );
        fs::remove_file(policy_path).expect("remove signed test policy");
        fs::remove_file(trust_path).expect("remove test policy trust root");
        loaded.expect("signed test policy must compile through the production loader")
    }

