    fn generic_route_with_durable_claim(kind: &str) -> Value {
        let mut route = generic_policy_route("none", json!(1024));
        route["match"]["methods"] = json!(["GET"]);
        let constraint = match kind {
            "slidingWindowLimit" => json!({
                "id":"durable-sliding",
                "type":"slidingWindowLimit",
                "store":"shared",
                "max":10,
                "windowSeconds":60,
                "windowSemantics":"sliding",
                "measure":"operationCount",
                "reservationMode":"atomicReserveCommitRelease",
                "onOverflow":"deny",
                "key":{
                    "scope":["principal","route","credential","credentialVersion","operation"]
                },
            }),
            "weightedBudget" => {
                route["adapter"]["config"]["request"]["allowedQueryKeys"] = json!(["units"]);
                route["adapter"]["config"]["request"]["valueRules"] = json!([{
                    "source":"query",
                    "name":"units",
                    "predicate":{"kind":"numeric","min":1,"max":10,"integer":true},
                    "capture":"units",
                }]);
                json!({
                    "id":"durable-weighted",
                    "type":"weightedBudget",
                    "store":"shared",
                    "max":100,
                    "windowSeconds":60,
                    "windowSemantics":"sliding",
                    "measure":"weightedCanonicalInteger",
                    "reservationMode":"atomicReserveCommitRelease",
                    "onOverflow":"deny",
                    "key":{
                        "scope":["principal","route","credential","credentialVersion","operation"]
                    },
                    "weight":{
                        "source":"requestValue",
                        "field":"units",
                        "representation":"canonicalNonNegativeInteger",
                        "unit":"request-unit",
                        "minimumPerOperation":1,
                        "maximumPerOperation":10,
                    },
                })
            }
            "traversalBudget" => {
                route["adapter"]["config"]["request"]["allowedQueryKeys"] =
                    json!(["cursor", "q"]);
                json!({
                    "id":"durable-traversal",
                    "type":"traversalBudget",
                    "operations":["generic.write"],
                    "traversal":{
                        "store":"shared",
                        "phases":["request","response"],
                        "cursor":{
                            "requestSource":"query",
                            "requestField":"cursor",
                            "responseField":"next",
                            "digest":"sha256",
                            "firstPageMayOmit":true,
                        },
                        "lineage":{
                            "scope":["principal","route","credential","credentialVersion"],
                            "queryFields":["q"],
                            "queryDigest":"sha256",
                        },
                        "limits":{
                            "maxPages":3,
                            "maxLifetimeSeconds":60,
                            "maxRecords":10,
                            "maxDecodedBytes":4096,
                        },
                        "accounting":{
                            "recordCountField":"items",
                            "byteSource":"validatedDecodedResponseBytes",
                            "commit":"atomicAfterResponseValidation",
                        },
                        "onReplay":"deny",
                        "onCrossLineage":"deny",
                        "onMissingEvidence":"deny",
                    },
                })
            }
            _ => panic!("unsupported durable fixture kind"),
        };
        route["constraints"] = json!([constraint]);
        route
    }

