    #[test]
    fn credential_lease_request_authority_v1_is_closed_bounded_and_lowercase() {
        let authority = test_credential_lease_request_authority(
            json!({
                "operation":"gmail.message.get",
                "gmailUser":"me",
                "messageId":"message-1",
            }),
            7_001,
        );
        validate_credential_lease_request_authority(&authority)
            .expect("canonical request authority");
        let value = serde_json::to_value(&authority).expect("serialize request authority");
        assert_eq!(
            value.as_object().expect("request authority object").len(),
            8
        );
        assert_eq!(
            credential_lease_request_authority_sha256(&authority),
            digest_json_ensure_ascii(&value)
        );

        let mut unknown = value.clone();
        unknown["operation_context"] = unknown["operationContext"].clone();
        assert!(serde_json::from_value::<CredentialLeaseRequestAuthority>(unknown).is_err());

        let mut uppercase = authority.clone();
        uppercase.operation_digest =
            format!("sha256:{}", "A".repeat(64));
        assert!(validate_credential_lease_request_authority(&uppercase).is_err());

        let mut boolean = authority.clone();
        boolean.operation_context = json!({
            "operation":"gmail.message.get",
            "includeSpamTrash":false,
            "historyId":9_007,
        });
        validate_credential_lease_request_authority(&boolean)
            .expect("booleans and u64 integers remain distinct canonical values");

        let mut negative = authority.clone();
        negative.operation_context =
            json!({"operation":"gmail.message.get","historyId":-1});
        assert!(validate_credential_lease_request_authority(&negative).is_err());

        let mut floating = authority.clone();
        floating.operation_context =
            json!({"operation":"gmail.message.get","confidence":0.5});
        assert!(validate_credential_lease_request_authority(&floating).is_err());

        let mut nested = Value::Bool(true);
        for _ in 0..33 {
            nested = json!([nested]);
        }
        let mut too_deep = authority.clone();
        too_deep.operation_context =
            json!({"operation":"gmail.message.get","nested":nested});
        assert!(validate_credential_lease_request_authority(&too_deep).is_err());

        let mut oversized = authority;
        oversized.operation_context = json!({
            "operation":"gmail.message.get",
            "padding":"x".repeat(MAX_RELEASE_AUTHORIZATION_CANONICAL_REQUEST_BYTES),
        });
        assert!(validate_credential_lease_request_authority(&oversized).is_err());
    }

