    #[test]
    fn identity_content_encoding_is_stripped_only_after_semantic_admission() {
        let source = include_str!("main.rs");
        let decision = source
            .split_once("fn decide_internal_with_mode")
            .expect("decision function")
            .1
            .split_once("\nfn http_response(")
            .expect("decision function terminator")
            .0;
        let validation = decision
            .find("validate_identity_request_content_encoding(&req.headers)")
            .expect("initial Content-Encoding validation");
        let operation = decision
            .find("validate_adapter(&req, &forwarded_headers, &url, &route_match)")
            .expect("active adapter operation admission");
        let strip = decision
            .find("strip_identity_request_content_encoding(&req.headers)")
            .expect("deferred Content-Encoding strip");
        let semantics = decision
            .find("evaluate_request_constraints(")
            .expect("effect-bound provider semantic admission");
        assert!(validation < operation);
        assert!(operation < strip);
        assert!(strip < semantics);
    }

    #[test]
    fn provider_request_denial_precedes_all_downstream_side_effects() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("downstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking downstream listener");
        let address = listener.local_addr().expect("downstream address");
        let contact_count = Arc::new(AtomicU64::new(0));
        let server_count = Arc::clone(&contact_count);
        let server = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_millis(750);
            while Instant::now() < deadline {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        server_count.fetch_add(1, Ordering::Relaxed);
                        let _ = stream.set_read_timeout(Some(Duration::from_millis(100)));
                        let mut request = [0u8; 4096];
                        let _ = stream.read(&mut request);
                        let _ = stream.write_all(
                            b"HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                        );
                    }
                    Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(error) => panic!("downstream accept failed: {error}"),
                }
            }
        });

        let mut snapshot_value = (*test_snapshot(1)).clone();
        let route = &mut snapshot_value.routes[0];
        route.scheme = "http".to_string();
        route.host = address.ip().to_string();
        route.port = address.port();
        route.methods = HashSet::from(["GET".to_string()]);
        route.adapter_type = "x.v2".to_string();
        route.adapter_config = json!({
            "mode":"recentSearchOnly",
            "request":provider_request_profile_json("x.v2", Some("recentSearchOnly")),
            "blockWrites":true,
            "appIds":["approved-app"],
            "allowedReadOperations":["search.read"],
            "response":{"mode":"json","maxBodyBytes":1024,"allowedFields":["data"]},
        });
        route.credential_ref = Some("credential:test".to_string());
        route.jit = json!({"required":true,"ttlSeconds":30,"maxUses":1});
        route.constraints = vec![json!({
            "id":"shared-quota",
            "type":"rateLimit",
            "max":1,
            "windowSeconds":60,
            "store":"shared",
        })];
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "x".to_string(),
                provider_subject: Some("user:test".to_string()),
                injection: json!({
                    "type":"bearer",
                    "header":"Authorization",
                    "field":"access_token",
                    "prefix":"Bearer ",
                }),
            },
        );
        let snapshot = Arc::new(snapshot_value);
        let resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![address])]));
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.upstream_resolver = resolver.clone();
        let base = format!("http://{address}");
        state.credential_lease_url = Some(format!("{base}/credential-leases"));
        state.grant_consume_url = Some(format!("{base}/grants/consume"));
        state.rate_limit_consume_url = Some(format!("{base}/rate-limits/consume"));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!("{base}/release-authorizations"));

        let target = format!("http://{address}/resource?query=test");
        let response = forward_absolute_request_inner(
            &state,
            &snapshot,
            IncomingRequest {
                method: "GET".to_string(),
                target,
                headers: BTreeMap::from([(
                    "authorization".to_string(),
                    "Bearer caller-secret".to_string(),
                )]),
                body: Vec::new(),
                client_ip: None,
            },
            Some("agent:test"),
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        );
        let ForwardResult::Buffered(response) = response else {
            panic!("provider denial unexpectedly streamed");
        };
        let response = String::from_utf8(response.to_vec()).expect("provider denial response");
        assert!(response.starts_with("HTTP/1.1 403"), "{response}");
        assert!(
            response.contains("request_header_not_allowed"),
            "{response}"
        );
        assert!(state
            .credential_leases
            .lock()
            .expect("credential leases")
            .is_empty());
        assert!(state
            .constraint_rate_counters
            .lock()
            .expect("rate counters")
            .is_empty());
        assert!(state.grants.lock().expect("grants").is_empty());
        assert_eq!(resolver.calls(), 0);
        assert_eq!(resolver.remaining_answers(), 1);
        assert!(state
            .pinned_upstream_clients
            .lock()
            .expect("pinned upstream client cache")
            .entries
            .is_empty());

        server.join().expect("downstream server");
        assert_eq!(contact_count.load(Ordering::Relaxed), 0);
    }

    #[test]
    fn generic_semantic_denial_precedes_credential_and_rate_state() {
        let mut snapshot_value = (*test_snapshot(1)).clone();
        let route = &mut snapshot_value.routes[0];
        route.methods = HashSet::from(["POST".to_string()]);
        route.credential_ref = Some("credential:test".to_string());
        route.adapter_config["request"] = json!({
            "allowedHeaders":["content-type"],
            "allowedQueryKeys":[],
            "allowedMediaTypes":["application/json"],
            "bodyMode":"json",
            "maxBodyBytes":1024,
        });
        route.constraints = vec![
            json!({
                "id":"body-policy",
                "type":"jsonBody",
                "allowedFields":["safe"],
            }),
            json!({
                "id":"local-rate",
                "type":"rateLimit",
                "max":1,
                "windowSeconds":60,
                "store":"local",
            }),
        ];
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        let snapshot = Arc::new(snapshot_value);
        let state = test_gate_state(Arc::clone(&snapshot));
        let request = provider_test_request(
            "POST",
            "https://example.test/resource",
            BTreeMap::from([(
                "content-type".to_string(),
                "text/plain".to_string(),
            )]),
            r#"{"safe":true}"#,
            Some(13),
        );
        let decision = decide_internal(&state, &snapshot, request, Some("agent:test"));
        assert_eq!(decision["status_code"], 415);
        assert_eq!(
            decision["payload"]["error"],
            "generic_request_content_type_denied"
        );
        assert!(state
            .credential_generations
            .lock()
            .expect("credential generations")
            .is_empty());
        assert!(state
            .credential_leases
            .lock()
            .expect("credential leases")
            .is_empty());
        assert!(state
            .constraint_rate_counters
            .lock()
            .expect("rate counters")
            .is_empty());
        assert!(state.grants.lock().expect("grants").is_empty());
    }

    #[test]
    fn generic_adapter_enforces_headers_and_literal_zero_body_cap() {
        let route = Route {
            id: "generic".to_string(),
            principals: vec!["agent:test".to_string()],
            scheme: "https".to_string(),
            host: "example.test".to_string(),
            port: 443,
            resolved_address_policy: ResolvedAddressPolicy::PublicOnly,
            methods: HashSet::from(["POST".to_string()]),
            paths: vec![compile_template("/resource").expect("template")],
            credential_ref: None,
            adapter_type: "generic.rest".to_string(),
            adapter_config: json!({"request":{
                "allowedHeaders":[],
                "allowedQueryKeys":[],
                "bodyMode":"any",
                "maxBodyBytes":0
            }}),
            discard_headers: Vec::new(),
            constraints: Vec::new(),
            jit: json!({}),
            response_observation: None,
        };
        let route_match = RouteMatch {
            route: &route,
            params: BTreeMap::new(),
        };
        let mut req = DecisionRequest {
            client_ip: None,
            method: "POST".to_string(),
            url: "https://example.test/resource".to_string(),
            headers: BTreeMap::new(),
            body: "x".to_string(),
            body_sha256: None,
            forwarded_body_length: None,
            forwarded_body_utf8_valid: Some(true),
            credential_metadata: BTreeMap::new(),
            gmail_proofs: Vec::new(),
            client_request_digest: None,
        };
        let url = Url::parse(&req.url).expect("URL");
        let body_error = validate_adapter(
            &req,
            &BTreeMap::from([
                ("host".to_string(), "example.test".to_string()),
                ("content-length".to_string(), "1".to_string()),
            ]),
            &url,
            &route_match,
        )
        .expect_err("zero maxBodyBytes must reject one byte");
        assert_eq!(body_error["error"], "generic_body_too_large");

        req.body.zeroize();
        let header_error = validate_adapter(
            &req,
            &BTreeMap::from([
                ("host".to_string(), "example.test".to_string()),
                ("x-not-allowed".to_string(), "value".to_string()),
            ]),
            &url,
            &route_match,
        )
        .expect_err("unlisted generic header must fail closed");
        assert_eq!(header_error["error"], "generic_header_not_allowed");

        let mut media_route = route.clone();
        media_route.adapter_config["request"]["allowedMediaTypes"] = json!([]);
        let media_route_match = RouteMatch {
            route: &media_route,
            params: BTreeMap::new(),
        };
        let empty_media_error = validate_adapter(
            &DecisionRequest {
                client_ip: None,
                method: "POST".to_string(),
                url: "https://example.test/resource".to_string(),
                headers: BTreeMap::new(),
                body: String::new(),
                body_sha256: Some(sha256_prefixed(b"")),
                forwarded_body_length: Some(0),
                forwarded_body_utf8_valid: Some(true),
                credential_metadata: BTreeMap::new(),
                gmail_proofs: Vec::new(),
                client_request_digest: None,
            },
            &BTreeMap::from([
                ("content-length".to_string(), "0".to_string()),
                ("content-type".to_string(), "application/json".to_string()),
                ("host".to_string(), "example.test".to_string()),
            ]),
            &url,
            &media_route_match,
        )
        .expect_err("present Content-Type must fail against an empty media allowlist");
        assert_eq!(
            empty_media_error["error"],
            "generic_request_content_type_denied"
        );
    }

    #[test]
    fn generic_content_type_is_mediated_outside_header_allowlist() {
        let snapshot = load_compiled_test_snapshot(
            policy_with_route(generic_policy_route("json", json!(1024))),
            "generic-content-type-admission",
            1,
        );
        let route = &snapshot.routes[0];
        assert_eq!(route.adapter_config["request"]["allowedHeaders"], json!([]));
        let body = r#"{"safe":true}"#;
        let url = Url::parse("https://example.test/resource").expect("test URL");
        let validate = |headers: BTreeMap<String, String>| -> Result<(Value, Value), Value> {
            let request = provider_test_request(
                "POST",
                url.as_str(),
                headers,
                body,
                Some(body.len() as u64),
            );
            let forwarded = canonical_forwarded_request_headers(
                &request.headers,
                &url,
                Some(body.len() as u64),
                &Value::Null,
            )
            .map_err(|error| json!({"error":error}))?;
            validate_adapter(
                &request,
                &forwarded,
                &url,
                &RouteMatch { route, params: BTreeMap::new() },
            )
        };
        for content_type in ["application/json", "Application/JSON; charset=utf-8"] {
            validate(BTreeMap::from([("content-type".to_string(), content_type.to_string())]))
                .expect("schema-admitted JSON media contract must accept its content type");
        }
        for content_type in [
            "text/plain",
            "application/json;",
            "application/json; charset=utf-8; CHARSET=utf-8",
        ] {
            let denied = validate(BTreeMap::from([("content-type".to_string(), content_type.to_string())]))
                .expect_err("unapproved or malformed media type must remain denied");
            assert_eq!(denied["error"], "generic_request_content_type_denied");
            assert_eq!(denied["status_code"], 415);
        }
        let missing = validate(BTreeMap::new()).expect_err("body requires Content-Type");
        assert_eq!(missing["error"], "generic_request_content_type_required");
        let duplicate = validate(BTreeMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("Content-Type".to_string(), "application/json".to_string()),
        ]))
        .expect_err("duplicate normalized headers must fail before adapter admission");
        assert_eq!(duplicate["error"], "request_header_ambiguous");
        let unknown = validate(BTreeMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("x-not-allowed".to_string(), "local-unit".to_string()),
        ]))
        .expect_err("ordinary headers still require the exact allowlist");
        assert_eq!(unknown["error"], "generic_header_not_allowed");
    }

    #[test]
    fn generic_buffered_json_enforces_content_type_utf8_and_syntax() {
        let mut route = test_snapshot(1).routes[0].clone();
        route.methods = HashSet::from(["POST".to_string()]);
        route.adapter_config = generic_policy_route("json", json!(1024))["adapter"]["config"].clone();
        let validate = |route: &Route,
                        body: &str,
                        content_type: &str,
                        utf8_valid: bool|
         -> Result<(Value, Value), Value> {
            let request = DecisionRequest {
                client_ip: None,
                method: "POST".to_string(),
                url: "https://example.test/resource".to_string(),
                headers: BTreeMap::new(),
                body: body.to_string(),
                body_sha256: None,
                forwarded_body_length: Some(body.len() as u64),
                forwarded_body_utf8_valid: Some(utf8_valid),
                credential_metadata: BTreeMap::new(),
                gmail_proofs: Vec::new(),
                client_request_digest: None,
            };
            let headers = BTreeMap::from([
                ("host".to_string(), "example.test".to_string()),
                ("content-length".to_string(), body.len().to_string()),
                ("content-type".to_string(), content_type.to_string()),
            ]);
            validate_adapter(
                &request,
                &headers,
                &Url::parse(&request.url).expect("test URL"),
                &RouteMatch {
                    route,
                    params: BTreeMap::new(),
                },
            )
        };

        validate(
            &route,
            r#"{"safe":true}"#,
            "Application/JSON; charset=utf-8",
            true,
        )
        .expect("valid buffered JSON request");
        let content_type = validate(&route, r#"{"safe":true}"#, "text/plain", true)
            .expect_err("non-JSON media type must fail");
        assert_eq!(content_type["error"], "generic_request_content_type_denied");
        assert_eq!(content_type["status_code"], 415);
        let duplicate_parameter = validate(
            &route,
            r#"{"safe":true}"#,
            "application/json; charset=utf-8; CHARSET=us-ascii",
            true,
        )
        .expect_err("duplicate Content-Type parameters must fail");
        assert_eq!(
            duplicate_parameter["error"],
            "generic_request_content_type_denied"
        );

        let syntax = validate(&route, r#"{"safe":}"#, "application/json", true)
            .expect_err("invalid JSON syntax must fail");
        assert_eq!(syntax["error"], "request_json_invalid");
        assert_eq!(syntax["status_code"], 400);
        let utf8 = validate(&route, r#"{"safe":true}"#, "application/json", false)
            .expect_err("lossy buffered JSON must fail");
        assert_eq!(utf8["error"], "request_json_invalid");
        for duplicate in [
            r#"{"safe":"first","safe":"second"}"#,
            r#"{"nested":{"safe":"first","safe":"second"}}"#,
        ] {
            let duplicate = validate(&route, duplicate, "application/json", true)
                .expect_err("duplicate buffered JSON object keys must fail");
            assert_eq!(duplicate["error"], "request_json_invalid");
        }

        route.adapter_config["request"]["bodyMode"] = json!("any");
        route.adapter_config["request"]["allowedMediaTypes"] =
            json!(["application/octet-stream"]);
        validate(&route, "not-json", "application/octet-stream", true)
            .expect("explicit any mode must preserve opaque buffered bodies");
    }

    #[test]
    fn duplicate_buffered_json_is_denied_before_upstream_contact() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("test upstream listener");
        listener
            .set_nonblocking(true)
            .expect("nonblocking upstream listener");
        let upstream = listener.local_addr().expect("test upstream address");
        let server = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_millis(500);
            while Instant::now() < deadline {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        let _ = stream.set_read_timeout(Some(Duration::from_millis(100)));
                        let mut request = [0_u8; 4096];
                        let _ = stream.read(&mut request);
                        let _ = stream.write_all(
                            b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 13\r\n\r\n{\"safe\":true}",
                        );
                        return true;
                    }
                    Err(err) if err.kind() == io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(err) => panic!("accept test upstream request: {err}"),
                }
            }
            false
        });

        let mut snapshot = (*test_snapshot(1)).clone();
        let route = &mut snapshot.routes[0];
        route.scheme = "http".to_string();
        route.host = upstream.ip().to_string();
        route.port = upstream.port();
        route.methods = HashSet::from(["POST".to_string()]);
        route.adapter_config["request"] = json!({
            "allowedHeaders":["content-type"],
            "allowedQueryKeys":[],
            "allowedMediaTypes":["application/json"],
            "bodyMode":"json",
            "maxBodyBytes":1024
        });
        route.constraints = vec![json!({
            "id":"strict-json",
            "type":"jsonBody",
            "allowedFields":["safe"]
        })];
        let snapshot = Arc::new(snapshot);
        let state = test_gate_state(Arc::clone(&snapshot));
        let body = br#"{"safe":"allowed","safe":"shadow"}"#.to_vec();
        let result = forward_absolute_request_inner(
            &state,
            &snapshot,
            IncomingRequest {
                method: "POST".to_string(),
                target: format!("http://{upstream}/resource"),
                headers: BTreeMap::from([(
                    "content-type".to_string(),
                    "application/json".to_string(),
                )]),
                body,
                client_ip: Some("127.0.0.1".to_string()),
            },
            Some("agent:test"),
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        );
        let response = match result {
            ForwardResult::Buffered(response) => {
                String::from_utf8(response.to_vec()).expect("buffered HTTP denial")
            }
            ForwardResult::Streamed => panic!("duplicate buffered request unexpectedly streamed"),
        };
        assert!(response.starts_with("HTTP/1.1 400"), "{response}");
        assert!(response.contains("request_json_invalid"), "{response}");
        assert!(
            !server.join().expect("test upstream thread"),
            "duplicate request contacted the upstream"
        );
    }

    #[test]
    fn strict_json_rejects_integer_negative_zero_lexically() {
        for input in [
            br#"-0"#.as_slice(),
            br#"[-0]"#.as_slice(),
            br#"{"nested":{"value":-0}}"#.as_slice(),
            br#"{"unrelated":true,"value":-0}"#.as_slice(),
        ] {
            let error = strict_json_value_from_slice(input)
                .expect_err("integer negative zero must fail strict JSON parsing");
            assert!(error.to_string().contains("integer -0"), "{error}");
        }

        for input in [
            br#""-0""#.as_slice(),
            br#"-0.0"#.as_slice(),
            br#"-0e0"#.as_slice(),
            br#"{"text":"value -0 is data","value":0}"#.as_slice(),
        ] {
            strict_json_value_from_slice(input)
                .expect("strings, floating negative zero, and integer zero remain valid");
        }
    }

    #[test]
    fn credential_derived_parser_header_and_path_diagnostics_are_nonreflective() {
        let duplicate_key = "providerCredentialHeader";
        let secret_value = "credential-value-must-not-escape";
        let input = format!(
            r#"{{"{duplicate_key}":"visible","{duplicate_key}":"{secret_value}"}}"#
        );
        let error = strict_json_value_from_slice(input.as_bytes())
            .expect_err("duplicate credential-derived JSON key must fail")
            .to_string();
        assert!(error.contains("duplicate_json_object_key"), "{error}");
        assert!(!error.contains(duplicate_key), "{error}");
        assert!(!error.contains(secret_value), "{error}");

        let wire = format!(
            "GET / HTTP/1.1\r\nHost: example.test\r\nX-Provider-Secret: first\r\nx-provider-secret: {secret_value}\r\n\r\n"
        );
        let error = parse_head(wire.as_bytes())
            .err()
            .expect("duplicate provider-controlled header must fail");
        assert_eq!(error, "request_header_ambiguous");
        let response = request_head_error_response(&error);
        let response = std::str::from_utf8(&response).expect("fixed HTTP denial is UTF-8");
        assert!(!response.contains("x-provider-secret"));
        assert!(!response.contains(secret_value));
        assert!(!response.contains("\"detail\""));

        let message_id = "18f-provider-message-id";
        let url = Url::parse(&format!(
            "https://gmail.googleapis.com/gmail/v1/users/me/messages/{message_id}"
        ))
        .expect("Gmail URL");
        let audit = canonical_json(&audit_url_parts(&url));
        assert!(!audit.contains(message_id));
        assert!(!audit.contains("/messages/"));
        assert!(!audit.contains("gmail.googleapis.com"));
        assert!(!audit.contains("\"authority\""));
        assert!(audit.contains("origin_sha256"));
        assert!(audit.contains("origin_bytes"));
        assert!(audit.contains("path_sha256"));
        assert!(audit.contains("path_bytes"));
    }

    fn json_array_redaction_result(
        payload: &[u8],
        allowed_fields: &[Vec<String>],
    ) -> Result<Vec<u8>, String> {
        let mut document = Vec::with_capacity(payload.len() + 2);
        document.push(b'[');
        document.extend_from_slice(payload);
        document.push(b']');
        let mut core = JsonArrayRedactorCore::new(16 * 1024, allowed_fields.to_vec());
        let mut chunks = core.push(&document)?;
        chunks.extend(core.finish()?);
        Ok(chunks.concat())
    }

    fn json_sse_redaction_result(
        payload: &[u8],
        allowed_fields: &[Vec<String>],
    ) -> Result<Vec<u8>, String> {
        let mut event = b"data: ".to_vec();
        event.extend_from_slice(payload);
        event.extend_from_slice(b"\n\n");
        let mut core = JsonSseRedactorCore::new(16 * 1024, 16 * 1024, allowed_fields.to_vec());
        let mut chunks = core.push(&event)?;
        chunks.extend(core.finish()?);
        Ok(chunks.concat())
    }

    fn json_nested_redaction_result(
        reader: impl Read,
        allowed_fields: &[Vec<String>],
    ) -> Result<Vec<u8>, String> {
        let mut output = Vec::new();
        redact_json_nested_to_writer(reader, &mut output, allowed_fields, 16 * 1024)?;
        Ok(output)
    }

    #[test]
    fn structured_json_unit_parsers_match_buffered_strict_json() {
        let allowed_fields = vec![vec!["safe".to_string()]];
        let invalid_payloads = [
            br#"{"safe":1,"safe":2}"#.as_slice(),
            br#"{"safe":{"nested":1,"nested":2}}"#.as_slice(),
            br#"{"safe":1,"s\u0061fe":2}"#.as_slice(),
            br#"{"safe":1,"denied":{"hidden":1,"hidden":2}}"#.as_slice(),
            br#"{"safe":-0}"#.as_slice(),
            br#"{"safe":1,"denied":{"hidden":-0}}"#.as_slice(),
            br#"{"safe":01}"#.as_slice(),
            br#"{"safe":1e9999}"#.as_slice(),
            br#"{"safe":"\x"}"#.as_slice(),
            b"{\"safe\":\"\xff\"}".as_slice(),
            br#"{"safe":"truncated}"#.as_slice(),
            br#"{"safe":1}{"safe":2}"#.as_slice(),
        ];

        for payload in invalid_payloads {
            assert!(
                strict_json_value_from_slice(payload).is_err(),
                "buffered strict parser unexpectedly accepted {}",
                String::from_utf8_lossy(payload)
            );
            assert!(
                redact_json_line(payload, &allowed_fields).is_err(),
                "JSONL parser unexpectedly accepted {}",
                String::from_utf8_lossy(payload)
            );
            assert!(
                json_array_redaction_result(payload, &allowed_fields).is_err(),
                "JSON array parser unexpectedly accepted {}",
                String::from_utf8_lossy(payload)
            );
            assert!(
                json_sse_redaction_result(payload, &allowed_fields).is_err(),
                "JSON SSE parser unexpectedly accepted {}",
                String::from_utf8_lossy(payload)
            );
            assert!(
                json_nested_redaction_result(Cursor::new(payload), &allowed_fields).is_err(),
                "nested JSON parser unexpectedly accepted {}",
                String::from_utf8_lossy(payload)
            );
        }

        for payload in [
            br#"{"safe":-0.0,"denied":{"text":"-0"}}"#.as_slice(),
            br#"{"safe":-0e0,"denied":{"items":[{"value":1}]}}"#.as_slice(),
            br#"{"s\u0061fe":1,"denied":true}"#.as_slice(),
        ] {
            strict_json_value_from_slice(payload).expect("buffered valid strict JSON");
            redact_json_line(payload, &allowed_fields).expect("valid JSONL unit");
            json_array_redaction_result(payload, &allowed_fields).expect("valid JSON array item");
            json_sse_redaction_result(payload, &allowed_fields).expect("valid JSON SSE event");
            json_nested_redaction_result(Cursor::new(payload), &allowed_fields)
                .expect("valid nested JSON document");
        }
    }

    #[test]
    fn nested_strict_negative_zero_lexing_is_chunk_boundary_invariant() {
        let cases = [
            (br#"{"safe":-0}"#.as_slice(), true),
            (br#"{"safe":{"hidden":-0}}"#.as_slice(), true),
            (br#"{"safe":-0.0}"#.as_slice(), false),
            (br#"{"safe":-0e0}"#.as_slice(), false),
            (br#"{"safe":"-0"}"#.as_slice(), false),
            (br#"{"safe":"escaped \\\"-0\\\""}"#.as_slice(), false),
        ];
        let allowed_fields = vec![vec!["safe".to_string()]];

        for (input, rejected) in cases {
            for split in 0..=input.len() {
                let mut detector = IntegerNegativeZeroDetector::default();
                let detected = detector.scan(&input[..split])
                    || detector.scan(&input[split..])
                    || detector.finish();
                assert_eq!(detected, rejected, "split {split} for {input:?}");

                let reader = Cursor::new(input[..split].to_vec())
                    .chain(Cursor::new(input[split..].to_vec()));
                let result = json_nested_redaction_result(reader, &allowed_fields);
                assert_eq!(
                    result.is_err(),
                    rejected,
                    "nested split {split} for {input:?}"
                );
            }
        }
    }

    #[test]
    fn structured_redactors_withhold_failing_units_and_deferred_terminal() {
        let allowed_fields = vec![vec!["safe".to_string()]];

        let stats = Arc::new(Mutex::new(RequestBodyStreamStats::new()));
        let source = b"{\"safe\":1}\n{\"safe\":2,\"safe\":3}\n".to_vec();
        let mut jsonl = JsonLinesRedactorReader::new(
            Box::new(Cursor::new(source)),
            1024,
            allowed_fields.clone(),
            stats,
        );
        let mut first = [0u8; 64];
        let read = jsonl.read(&mut first).expect("first JSONL unit");
        assert_eq!(&first[..read], b"{\"safe\":1}\n");
        assert!(jsonl.read(&mut first).is_err());

        let mut array = JsonArrayRedactorCore::new(1024, allowed_fields.clone());
        let released = array
            .push(b"[{\"safe\":1},")
            .expect("valid JSON array prefix")
            .concat();
        assert_eq!(released, b"[{\"safe\":1}");
        assert!(array.push(b"{\"safe\":2,\"safe\":3}]").is_err());

        let mut sse = JsonSseRedactorCore::new(1024, 2048, allowed_fields.clone());
        let released = sse
            .push(b"data: {\"safe\":1}\n\n")
            .expect("valid SSE prefix")
            .concat();
        assert_eq!(released, b"data: {\"safe\":1}\n\n");
        assert!(sse.push(b"data: {\"safe\":2,\"safe\":3}\n\n").is_err());

        let mut wire = Vec::new();
        {
            let mut chunks = ChunkedHashWriter::new_with_deferred_terminal(&mut wire);
            redact_json_nested_to_writer(
                Cursor::new(br#"{"safe":1}{"safe":2}"#),
                &mut chunks,
                &allowed_fields,
                1024,
            )
            .expect_err("malformed final nested tail must fail");
        }
        assert!(!wire.windows(5).any(|window| window == b"0\r\n\r\n"));
        assert!(!wire
            .windows(STREAM_RESPONSE_PROOF_B64_TRAILER.len())
            .any(|window| window == STREAM_RESPONSE_PROOF_B64_TRAILER.as_bytes()));
    }

