    fn gmail_allowed_parent_decision(
        snapshot: &Snapshot,
        parent_url: &Url,
        injection: &Value,
    ) -> Value {
        let request =
            provider_test_request("GET", parent_url.as_str(), BTreeMap::new(), "", Some(0));
        let forwarded_headers = canonical_forwarded_request_headers(
            &request.headers,
            parent_url,
            None,
            injection,
        )
        .expect("canonical Gmail parent headers");
        let operation = json!({"operation":"gmail.messages.list"});
        let canonical = canonical_request(
            &request,
            &forwarded_headers,
            parent_url,
            &snapshot.principals[0],
            &snapshot.routes[0],
            7,
            &snapshot.hash,
            &operation,
        );
        let request_digest = digest_json_ensure_ascii(&canonical);
        let expected_operation_digest = operation_digest(&canonical);
        let attempt_id = sha256_prefixed(b"gmail-parent-attempt");
        let decision = json!({
            "allowed":true,
            "authorizes_forwarding":true,
            "principal_id":"agent:test",
            "route_id":"route:test",
            "policy_hash":snapshot.hash,
            "snapshot_epoch":snapshot.epoch,
            "credential_ref":"credential:test",
            "credential_version":7,
            "jit":{"required":false},
            "request_digest":request_digest,
            "operation_digest":expected_operation_digest,
            "attempt_id":attempt_id.clone(),
            "flow_id":sha256_prefixed(b"gmail-parent-flow"),
            "rewrite":{},
            "injection":{
                "credential_ref":"credential:test",
                "credential_version":7,
                "secret_available":true,
                "plan":injection,
            },
            "release_authorization":{
                "mode":"atomic",
                "state":"reserved",
                "attempt_id":attempt_id,
                "binding_digest":sha256_prefixed(b"gmail-parent-release-binding"),
                "credential_lease_authorization":Value::Null,
            },
            "canonical_request":canonical,
        });
        decision_route_context(snapshot, &decision, "GET", parent_url)
            .expect("Gmail parent decision route context");
        provider_url_bound_to_decision(&decision, "GET", parent_url)
            .expect("Gmail parent decision provider URL");
        decision
    }

    #[test]
    fn gmail_metadata_child_url_requires_canonical_identifiers_and_exact_query() {
        let parent =
            Url::parse("https://gmail.example.test:8443/gmail/v1/users/me/messages?q=safe")
                .expect("parent Gmail URL");
        let child = gmail_metadata_child_url(&parent, "user@example.test", "id_123-safe")
            .expect("canonical child URL");
        assert_eq!(child.scheme(), "https");
        assert_eq!(child.host_str(), Some("gmail.example.test"));
        assert_eq!(child.port(), Some(8443));
        assert_eq!(
            child.path(),
            "/gmail/v1/users/user@example.test/messages/id_123-safe"
        );
        assert_eq!(
            child.query_pairs().collect::<Vec<_>>(),
            vec![
                ("fields".into(), "id,internalDate".into()),
                ("format".into(), "metadata".into())
            ]
        );
        let mut headers = HeaderMap::new();
        headers.insert("accept", HeaderValue::from_static("application/json"));
        headers.insert("accept-encoding", HeaderValue::from_static("identity"));
        let canonical = gmail_metadata_child_canonical_request(&child, &headers)
            .expect("canonical metadata child");
        assert_eq!(
            canonical["query"],
            json!([["fields","id,internalDate"],["format","metadata"]])
        );
        let mut alternate = child.clone();
        alternate.set_query(Some("format=metadata&fields=id%2CinternalDate"));
        assert!(
            gmail_metadata_child_canonical_request(&alternate, &headers).is_err(),
            "alternate physical query order must not share the child binding"
        );
        for (user, message_id) in [
            ("user/../victim", "safe"),
            ("user\\victim", "safe"),
            ("user%2Fvictim", "safe"),
            ("user@example.test", "."),
            ("user@example.test", ".."),
            ("user@example.test", "id/child"),
            ("user@example.test", "id%2fchild"),
            ("user@example.test", "id\u{00e9}"),
            ("user@example.test", "id\u{0000}"),
        ] {
            assert!(
                gmail_metadata_child_url(&parent, user, message_id).is_err(),
                "noncanonical Gmail identifier was admitted: {user:?} {message_id:?}"
            );
        }
    }

    #[test]
    fn gmail_metadata_child_authorization_binds_mutation_alias_and_single_use() {
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.routes[0].adapter_type = "gmail.v1".to_string();
        snapshot.routes[0].scheme = "https".to_string();
        snapshot.routes[0].host = "gmail.example.test".to_string();
        snapshot.routes[0].port = 443;
        snapshot.routes[0].paths = vec![
            compile_template("/gmail/v1/users/{user}/messages")
                .expect("Gmail parent route template"),
        ];
        snapshot.routes[0].credential_ref = Some("credential:test".to_string());
        snapshot.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "google".to_string(),
                provider_subject: Some("user:test".to_string()),
                injection: json!({"type":"bearer"}),
            },
        );
        let parent = Url::parse("https://gmail.example.test/gmail/v1/users/me/messages")
            .expect("Gmail parent URL");
        let decision = gmail_allowed_parent_decision(&snapshot, &parent, &json!({"type":"bearer"}));
        let child = gmail_metadata_child_url(&parent, "me", "message-1")
            .expect("Gmail child URL");
        let mut headers = HeaderMap::new();
        headers.insert("accept", HeaderValue::from_static("application/json"));
        headers.insert("accept-encoding", HeaderValue::from_static("identity"));
        let child_request = gmail_metadata_child_canonical_request(&child, &headers)
            .expect("Gmail child canonical request");
        let authorization = derive_gmail_metadata_child_authorization(
            &snapshot,
            &decision,
            &parent,
            &child_request,
            1,
            1,
            10,
        )
        .expect("derived child authorization");
        assert!(is_sha256_digest(&authorization.authorization_digest));
        assert!(is_sha256_digest(
            &authorization.material.parent_decision_binding_digest
        ));

        let ledger = GmailMetadataChildAuthorizationLedger::default();
        ledger
            .register(&authorization)
            .expect("first child authorization registration");
        assert_eq!(
            ledger.register(&authorization),
            Err("gmail_metadata_child_authorization_replayed")
        );
        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Derived,
                GmailMetadataChildAuthorizationPhase::Injecting,
            )
            .expect("single child injection claim");
        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Injecting,
                GmailMetadataChildAuthorizationPhase::Injected,
            )
            .expect("single child injection consume");
        assert_eq!(
            ledger.advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Derived,
                GmailMetadataChildAuthorizationPhase::Injected,
            ),
            Err("gmail_metadata_child_authorization_replayed")
        );

        let mut mutated = authorization.clone();
        mutated.material.child_request["path"] =
            json!("/gmail/v1/users/me/messages/message-2");
        assert!(validate_gmail_metadata_child_authorization(
            &snapshot,
            &decision,
            &parent,
            &child,
            &headers,
            &mutated,
        )
        .is_err());

        let mut replayed_parent = decision.clone();
        replayed_parent["attempt_id"] = json!(sha256_prefixed(b"other-parent-attempt"));
        assert!(validate_gmail_metadata_child_authorization(
            &snapshot,
            &replayed_parent,
            &parent,
            &child,
            &headers,
            &authorization,
        )
        .is_err());

        let mut alias = child.clone();
        alias.set_query(Some("format=metadata&fields=id%2CinternalDate"));
        assert!(validate_gmail_metadata_child_authorization(
            &snapshot,
            &decision,
            &parent,
            &alias,
            &headers,
            &authorization,
        )
        .is_err());
    }

    #[test]
    fn gmail_metadata_child_transport_error_after_dispatch_is_indeterminate() {
        let mut snapshot = (*test_snapshot(1)).clone();
        snapshot.routes[0].adapter_type = "gmail.v1".to_string();
        snapshot.routes[0].scheme = "https".to_string();
        snapshot.routes[0].host = "gmail.example.test".to_string();
        snapshot.routes[0].port = 443;
        snapshot.routes[0].paths = vec![
            compile_template("/gmail/v1/users/{user}/messages")
                .expect("Gmail parent route template"),
        ];
        snapshot.routes[0].credential_ref = Some("credential:test".to_string());
        snapshot.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "google".to_string(),
                provider_subject: Some("user:test".to_string()),
                injection: json!({"type":"bearer"}),
            },
        );
        let parent = Url::parse("https://gmail.example.test/gmail/v1/users/me/messages")
            .expect("Gmail parent URL");
        let decision = gmail_allowed_parent_decision(&snapshot, &parent, &json!({"type":"bearer"}));
        let child =
            gmail_metadata_child_url(&parent, "me", "message-1").expect("Gmail child URL");
        let mut headers = HeaderMap::new();
        headers.insert("accept", HeaderValue::from_static("application/json"));
        headers.insert("accept-encoding", HeaderValue::from_static("identity"));
        let child_request = gmail_metadata_child_canonical_request(&child, &headers)
            .expect("Gmail child canonical request");
        let authorization = derive_gmail_metadata_child_authorization(
            &snapshot,
            &decision,
            &parent,
            &child_request,
            1,
            1,
            10,
        )
        .expect("derived child authorization");
        let ledger = GmailMetadataChildAuthorizationLedger::default();
        ledger
            .register(&authorization)
            .expect("register child authorization");
        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Derived,
                GmailMetadataChildAuthorizationPhase::Injecting,
            )
            .expect("claim child injection");
        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Injecting,
                GmailMetadataChildAuthorizationPhase::Injected,
            )
            .expect("complete child injection");
        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Injected,
                GmailMetadataChildAuthorizationPhase::Dispatched,
            )
            .expect("mark child dispatched");

        ledger
            .advance(
                &authorization,
                GmailMetadataChildAuthorizationPhase::Dispatched,
                GmailMetadataChildAuthorizationPhase::ProviderOutcomeUnknown,
            )
            .expect("terminalize post-dispatch transport error");
        let result = gmail_metadata_child_send_error_result(
            authorization.material.child_request_digest.clone(),
            UpstreamSendError::Request("connection reset after dispatch".to_string()),
        );
        let GmailMetadataChildResult::Indeterminate { payload, record } = result else {
            panic!("post-dispatch transport error was not indeterminate");
        };
        assert_eq!(
            payload["error"],
            "gmail_metadata_fetch_provider_outcome_unknown"
        );
        assert_eq!(payload["providerOperationMayHaveCommitted"], true);
        assert_eq!(payload["retryProviderRequest"], false);
        assert_eq!(record["outcome"], "provider_outcome_unknown");
        assert!(!record.to_string().contains("dropped"));
        assert_eq!(
            ledger
                .phases
                .lock()
                .expect("child authorization ledger")
                .get(&authorization.authorization_digest),
            Some(&GmailMetadataChildAuthorizationPhase::ProviderOutcomeUnknown)
        );

        let build_authorization = derive_gmail_metadata_child_authorization(
            &snapshot,
            &decision,
            &parent,
            &child_request,
            2,
            2,
            10,
        )
        .expect("derived request-build child authorization");
        ledger
            .register(&build_authorization)
            .expect("register request-build child authorization");
        ledger
            .advance(
                &build_authorization,
                GmailMetadataChildAuthorizationPhase::Derived,
                GmailMetadataChildAuthorizationPhase::Injecting,
            )
            .expect("claim request-build child injection");
        ledger
            .advance(
                &build_authorization,
                GmailMetadataChildAuthorizationPhase::Injecting,
                GmailMetadataChildAuthorizationPhase::Injected,
            )
            .expect("complete request-build child injection");
        ledger
            .advance(
                &build_authorization,
                GmailMetadataChildAuthorizationPhase::Injected,
                GmailMetadataChildAuthorizationPhase::Failed,
            )
            .expect("terminalize request-build failure");
        let build_result = gmail_metadata_child_send_error_result(
            build_authorization.material.child_request_digest.clone(),
            UpstreamSendError::RequestBuild("request construction failed".to_string()),
        );
        let GmailMetadataChildResult::Blocked { payload, record } = build_result else {
            panic!("pre-dispatch request-build error was not blocked");
        };
        assert_eq!(payload["error"], "gmail_metadata_fetch_request_build_failed");
        assert_eq!(record["outcome"], "blocked_request_build");
        assert_eq!(
            ledger
                .phases
                .lock()
                .expect("child authorization ledger")
                .get(&build_authorization.authorization_digest),
            Some(&GmailMetadataChildAuthorizationPhase::Failed)
        );
    }

    #[test]
    fn gmail_metadata_child_source_reuses_parent_prepared_upstream_without_resolution() {
        let source = include_str!("main.rs");
        let child = source
            .split_once("fn fetch_gmail_metadata_child(")
            .expect("Gmail metadata child fetch")
            .1
            .split_once("\nfn hydrate_gmail_list_metadata(")
            .expect("Gmail metadata child fetch terminator")
            .0;
        assert!(child.contains(
            "validate_prepared_upstream_binding(\n        execution.prepared_upstream,"
        ));
        assert!(child.contains("&execution.prepared_upstream.client"));
        assert!(child.contains("parent_binding"));
        assert!(!child.contains("prepare_upstream("));
        assert!(!child.contains("prepare_upstream_for_forward("));
        assert!(!child.contains("upstream_resolver"));
        assert!(!child.contains("resolve("));
        assert!(!child.contains("dropped_transport"));
        assert!(child.contains("classify_gmail_metadata_child_send_error("));
    }

