    #[test]
    fn concurrent_release_authorities_resolve_and_drop_only_their_exact_cache_owner() {
        let response_signing_key = SigningKey::from_bytes(&[109u8; 32]);
        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.hash = sha256_prefixed(b"request-scoped-release-cache-policy");
        snapshot_value
            .attested_response_context
            .as_mut()
            .expect("attested response context")
            .policy_bundle_digest = snapshot_value.hash.clone();
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        snapshot_value.routes[0].credential_ref = Some("credential:test".to_string());
        snapshot_value.routes[0].jit = json!({
            "required":true,
            "ttlSeconds":30,
            "maxUses":1,
        });
        let snapshot = Arc::new(snapshot_value);
        let scope =
            CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        let reservation_a = test_jit_release_reservation(&snapshot, &scope, 7, 1);
        let reservation_b = test_jit_release_reservation(&snapshot, &scope, 7, 2);
        let request_authority_a = reservation_a
            .credential_lease_request_authority()
            .expect("first request authority");
        let request_authority_b = reservation_b
            .credential_lease_request_authority()
            .expect("second request authority");
        let authorization_a = reservation_a
            .credential_lease_authorization()
            .expect("first release authorization")
            .expect("JIT release authority");
        let authorization_b = reservation_b
            .credential_lease_authorization()
            .expect("second release authorization")
            .expect("JIT release authority");

        let credential_listener =
            TcpListener::bind("127.0.0.1:0").expect("credential listener");
        let credential_address = credential_listener
            .local_addr()
            .expect("credential listener address");
        let credential_snapshot = Arc::clone(&snapshot);
        let attempt_a = authorization_a.attempt_id.clone();
        let attempt_b = authorization_b.attempt_id.clone();
        let credential_server = thread::spawn(move || {
            let response_signing_key = SigningKey::from_bytes(&[109u8; 32]);
            let mut attempts = Vec::new();
            for _ in 0..2 {
                let (mut stream, _) = credential_listener
                    .accept()
                    .expect("concurrent credential request");
                let head = read_request_head_from(&mut stream, None)
                    .expect("concurrent credential request head");
                let request = read_request_body_from_head(
                    &mut stream,
                    head,
                    MAX_CREDENTIAL_LEASE_RESPONSE_BYTES,
                )
                .expect("concurrent credential request body");
                let payload = strict_json_value_from_slice(&request.body)
                    .expect("concurrent credential request JSON");
                let attempt_id = payload
                    .pointer("/releaseAuthorization/attemptId")
                    .and_then(Value::as_str)
                    .expect("exact credential release attempt")
                    .to_string();
                let secret = if attempt_id == attempt_a {
                    "reservation-a-secret"
                } else if attempt_id == attempt_b {
                    "reservation-b-secret"
                } else {
                    panic!("unexpected concurrent credential release attempt");
                };
                let response_nonce = request
                    .headers
                    .get("x-serverware-response-nonce")
                    .expect("credential response nonce");
                let response = signed_encrypted_dispatch_credential_response(
                    &response_signing_key,
                    &credential_snapshot,
                    &request,
                    response_nonce,
                    secret,
                    7,
                    BTreeMap::new(),
                );
                stream
                    .write_all(&response)
                    .expect("concurrent signed credential response");
                attempts.push(attempt_id);
            }
            attempts
        });

        let completion_listener =
            TcpListener::bind("127.0.0.1:0").expect("completion listener");
        let completion_address = completion_listener
            .local_addr()
            .expect("completion listener address");
        let completion_reservation = reservation_b.clone();
        let completion_snapshot = Arc::clone(&snapshot);
        let completion_server = thread::spawn(move || {
            let (mut stream, request, payload) =
                read_release_test_http_request(&completion_listener);
            assert_eq!(payload["attemptId"], completion_reservation.attempt_id);
            assert_eq!(
                payload["bindingDigest"],
                completion_reservation.binding_digest
            );
            assert_eq!(payload["outcome"], "not_forwarded");
            let body = json!({
                "apiVersion":"serverware.releaseAuthorization/v1",
                "ok":true,
                "authorized":false,
                "state":"cancelled",
                "reason":"cancelled",
                "attemptId":completion_reservation.attempt_id,
                "bindingDigest":completion_reservation.binding_digest,
                "idempotentReplay":false,
                "grantId":completion_reservation.grant_id,
                "approvalRequestId":completion_reservation.approval_request_id,
                "reservationExpiresAtEpochMs":
                    completion_reservation.reservation_expires_at_epoch_ms,
                "dispatchStartedAtEpochMs":null,
                "dispatchExpiresAtEpochMs":null,
                "completionOutcome":"not_forwarded",
                "retryAfterSeconds":0,
                "quotas":[],
                "store":{"backend":"sqlite","ha":true},
            });
            stream
                .write_all(&signed_release_test_response(
                    &response_signing_key,
                    &completion_snapshot,
                    &request,
                    StatusCode::OK,
                    body,
                ))
                .expect("completion response");
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.release_authorization_base_url = Some(format!(
            "http://{completion_address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.credential_lease_url = Some(format!(
            "http://{credential_address}/api/data-plane/credential-leases"
        ));
        state.credential_lease_token = Some("credential-token".to_string());
        state
            .credential_generations
            .lock()
            .expect("credential generations")
            .insert(
                scope.clone(),
                test_credential_generation(&snapshot, 7, BTreeMap::new()),
            );
        let state = Arc::new(state);

        let flight_a = CredentialLeaseGenerationKey::new_bound(
            &snapshot,
            &scope,
            CredentialLeasePurpose::DispatchSecret,
            Some(&request_authority_a),
            Some(&authorization_a),
        );
        let flight_b = CredentialLeaseGenerationKey::new_bound(
            &snapshot,
            &scope,
            CredentialLeasePurpose::DispatchSecret,
            Some(&request_authority_b),
            Some(&authorization_b),
        );
        assert_ne!(flight_a, flight_b);
        let mut exact_variant = authorization_a.clone();
        exact_variant.reservation_expires_at_epoch_ms += 1;
        assert_ne!(
            flight_a,
            CredentialLeaseGenerationKey::new_bound(
                &snapshot,
                &scope,
                CredentialLeasePurpose::DispatchSecret,
                Some(&request_authority_a),
                Some(&exact_variant),
            ),
            "singleflight identity includes the full release authorization"
        );

        let (ready_sender, ready_receiver) = mpsc::sync_channel::<()>(2);
        let (start_a_sender, start_a_receiver) = mpsc::sync_channel::<()>(0);
        let (start_b_sender, start_b_receiver) = mpsc::sync_channel::<()>(0);
        let (a_removed_sender, a_removed_receiver) = mpsc::sync_channel::<()>(0);

        let state_a = Arc::clone(&state);
        let snapshot_a = Arc::clone(&snapshot);
        let scope_a = scope.clone();
        let request_authority_a_thread = request_authority_a.clone();
        let request_authority_b_for_a = request_authority_b.clone();
        let authorization_a_thread = authorization_a.clone();
        let authorization_b_for_a = authorization_b.clone();
        let ready_sender_a = ready_sender.clone();
        let request_a = thread::spawn(move || {
            let mut guard = ReleaseAuthorizationGuard::new(&state_a, reservation_a);
            guard
                .arm_credential_lease_cleanup(&scope_a, &authorization_a_thread)
                .expect("arm first exact cleanup");
            let lease_info = ensure_scoped_credential_lease_bound(
                &state_a,
                &snapshot_a,
                &scope_a,
                Some(&request_authority_a_thread),
                Some(&authorization_a_thread),
            )
            .expect("fetch first exact release-controlled secret");
            assert!(lease_info.secret_available);
            let resolved = credential_lease_for_release(
                &state_a,
                &snapshot_a,
                &test_release_controlled_decision(&snapshot_a, &authorization_a_thread),
                &scope_a.credential_id,
                7,
            )
            .expect("first concurrent request resolves its own secret");
            assert_eq!(resolved.secret.as_str(), "reservation-a-secret");
            drop(resolved);
            ready_sender_a.send(()).expect("first request ready");
            start_a_receiver.recv().expect("start first cleanup");
            guard.stage = ReleaseAuthorizationStage::Completed;
            drop(guard);
            let cache = state_a
                .credential_leases
                .lock()
                .expect("credential lease cache");
            assert!(!cache.contains_key(&CredentialLeaseCacheKey::new_bound(
                &scope_a,
                Some(&request_authority_a_thread),
                Some(&authorization_a_thread),
            )));
            assert!(cache.contains_key(&CredentialLeaseCacheKey::new_bound(
                &scope_a,
                Some(&request_authority_b_for_a),
                Some(&authorization_b_for_a),
            )));
            drop(cache);
            a_removed_sender
                .send(())
                .expect("signal first exact cleanup");
        });

        let state_b = Arc::clone(&state);
        let snapshot_b = Arc::clone(&snapshot);
        let scope_b = scope.clone();
        let request_authority_b_thread = request_authority_b.clone();
        let authorization_b_thread = authorization_b.clone();
        let request_b = thread::spawn(move || {
            let mut guard = ReleaseAuthorizationGuard::new(&state_b, reservation_b);
            guard
                .arm_credential_lease_cleanup(&scope_b, &authorization_b_thread)
                .expect("arm second exact cleanup");
            let lease_info = ensure_scoped_credential_lease_bound(
                &state_b,
                &snapshot_b,
                &scope_b,
                Some(&request_authority_b_thread),
                Some(&authorization_b_thread),
            )
            .expect("fetch second exact release-controlled secret");
            assert!(lease_info.secret_available);
            let resolved = credential_lease_for_release(
                &state_b,
                &snapshot_b,
                &test_release_controlled_decision(&snapshot_b, &authorization_b_thread),
                &scope_b.credential_id,
                7,
            )
            .expect("second concurrent request resolves its own secret");
            assert_eq!(resolved.secret.as_str(), "reservation-b-secret");
            drop(resolved);
            ready_sender.send(()).expect("second request ready");
            start_b_receiver.recv().expect("start second cleanup");
            a_removed_receiver
                .recv()
                .expect("first exact cleanup completed");
            guard
                .complete_not_forwarded()
                .expect("complete second request");
            assert!(
                state_b
                    .credential_leases
                    .lock()
                    .expect("credential lease cache")
                    .contains_key(&CredentialLeaseCacheKey::new_bound(
                        &scope_b,
                        Some(&request_authority_b_thread),
                        Some(&authorization_b_thread),
                    )),
                "authorization completion must not evict while request validation can still use the secret"
            );
            drop(guard);
            assert!(state_b
                .credential_leases
                .lock()
                .expect("credential lease cache")
                .is_empty());
        });

        ready_receiver.recv().expect("first concurrent request ready");
        ready_receiver.recv().expect("second concurrent request ready");
        assert_eq!(
            state
                .credential_leases
                .lock()
                .expect("credential lease cache")
                .len(),
            2,
            "distinct exact release authorities must coexist"
        );
        start_a_sender.send(()).expect("start first request cleanup");
        start_b_sender.send(()).expect("start second request cleanup");
        request_a.join().expect("first concurrent request");
        request_b.join().expect("second concurrent request");
        let credential_attempts = credential_server.join().expect("credential server");
        assert_eq!(
            credential_attempts.into_iter().collect::<HashSet<_>>(),
            HashSet::from([
                authorization_a.attempt_id.clone(),
                authorization_b.attempt_id.clone(),
            ])
        );
        completion_server.join().expect("completion server");
        assert!(state
            .credential_leases
            .lock()
            .expect("credential lease cache")
            .is_empty());
    }

    #[test]
    fn poisoned_cleanup_recovers_and_zeroizes_only_the_exact_cache_owner() {
        let ReleaseCleanupTestFixture {
            snapshot,
            state,
            scope,
            shared_scope,
            request_authority,
            authorization,
            concurrent_request_authority,
            concurrent_authorization,
            ..
        } = test_release_cleanup_fixture(40);
        let state = Arc::new(state);
        let mut cleanup = CredentialLeaseRequestCleanup::new(&state);
        cleanup
            .arm_bound(&scope, Some(&request_authority), Some(&authorization))
            .expect("arm poisoned exact cleanup");
        let poison_state = Arc::clone(&state);
        let poisoner = thread::spawn(move || {
            let _leases = poison_state
                .credential_leases
                .lock()
                .expect("credential lease cache before intentional poison");
            panic!("intentional credential lease cache poison");
        });
        assert!(poisoner.join().is_err());

        let cleanup_result =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| drop(cleanup)));
        assert!(
            cleanup_result.is_ok(),
            "request cleanup Drop must not panic on a poisoned cache mutex"
        );
        cache_scoped_credential_lease(
            &state,
            &snapshot,
            &shared_scope,
            test_secret_lease(
                &snapshot,
                shared_scope.clone(),
                11,
                "shared-hot-secret",
                BTreeMap::new(),
            ),
        )
        .expect("ordinary cache operation succeeds after cleanup clears poison");
        let leases = state
            .credential_leases
            .lock()
            .expect("credential lease cache poison was cleared");
        assert!(!leases.contains_key(&CredentialLeaseCacheKey::new_bound(
            &scope,
            Some(&request_authority),
            Some(&authorization),
        )));
        assert!(leases.contains_key(&CredentialLeaseCacheKey::new_bound(
            &scope,
            Some(&concurrent_request_authority),
            Some(&concurrent_authorization),
        )));
        assert!(leases.contains_key(&CredentialLeaseCacheKey::new(
            &shared_scope,
            None,
        )));
        assert_eq!(leases.len(), 2);
    }

    #[test]
    fn repeated_one_use_credential_requests_do_not_consume_shared_cache_capacity() {
        let mut snapshot_value = (*test_snapshot(1)).clone();
        snapshot_value.hash = sha256_prefixed(b"bounded-one-use-credential-cache-policy");
        snapshot_value.routes[0].credential_ref = Some("credential:one-use".to_string());
        snapshot_value.routes[0].jit = json!({
            "required":true,
            "ttlSeconds":30,
            "maxUses":1,
        });
        let mut shared_route = snapshot_value.routes[0].clone();
        shared_route.id = "route:shared".to_string();
        shared_route.credential_ref = Some("credential:shared".to_string());
        shared_route.jit = json!({
            "required":false,
            "ttlSeconds":3600,
            "maxUses":1,
        });
        snapshot_value.routes.push(shared_route);
        for credential_id in ["credential:one-use", "credential:shared"] {
            snapshot_value.credentials.insert(
                credential_id.to_string(),
                Credential {
                    provider: "generic".to_string(),
                    provider_subject: None,
                    injection: json!({"type":"bearer"}),
                },
            );
        }
        let snapshot = Arc::new(snapshot_value);
        let one_use_scope =
            CredentialLeaseScope::new("agent:test", "route:test", "credential:one-use");
        let shared_scope =
            CredentialLeaseScope::new("agent:test", "route:shared", "credential:shared");
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.credential_lease_cache_max = 2;
        {
            let mut generations = state
                .credential_generations
                .lock()
                .expect("credential generations");
            generations.insert(
                one_use_scope.clone(),
                test_credential_generation(&snapshot, 7, BTreeMap::new()),
            );
            generations.insert(
                shared_scope.clone(),
                test_credential_generation(&snapshot, 11, BTreeMap::new()),
            );
        }
        cache_scoped_credential_lease(
            &state,
            &snapshot,
            &shared_scope,
            test_secret_lease(
                &snapshot,
                shared_scope.clone(),
                11,
                "shared-hot-secret",
                BTreeMap::new(),
            ),
        )
        .expect("cache shared hot lease");

        for marker in 1..=8 {
            let reservation =
                test_jit_release_reservation(&snapshot, &one_use_scope, 7, marker);
            let request_authority = reservation
                .credential_lease_request_authority()
                .expect("one-use request authority");
            let authorization = reservation
                .credential_lease_authorization()
                .expect("one-use release authorization")
                .expect("JIT release authority");
            let mut cleanup = ReleaseAuthorizationGuard::new(&state, reservation);
            cleanup
                .arm_credential_lease_cleanup(&one_use_scope, &authorization)
                .expect("arm one-use cleanup");
            let mut lease = test_secret_lease(
                &snapshot,
                one_use_scope.clone(),
                7,
                &format!("one-use-secret-{marker}"),
                BTreeMap::new(),
            );
            lease.request_authority = Some(request_authority);
            lease.release_authorization = Some(authorization);
            cache_scoped_credential_lease(
                &state,
                &snapshot,
                &one_use_scope,
                lease,
            )
            .expect("one-use secret fits beside shared hot lease");
            assert_eq!(
                state
                    .credential_leases
                    .lock()
                    .expect("credential lease cache")
                    .len(),
                2
            );
            cleanup.stage = ReleaseAuthorizationStage::Completed;
            drop(cleanup);
            let cache = state
                .credential_leases
                .lock()
                .expect("credential lease cache");
            assert_eq!(cache.len(), 1);
            assert!(cache.contains_key(&CredentialLeaseCacheKey::new(
                &shared_scope,
                None,
            )));
        }
        assert_eq!(
            cached_credential_lease_info(&state, &snapshot, &shared_scope)
                .expect("shared lease remains hot")
                .version,
            11
        );
    }

    #[test]
    fn cache_owner_zeroization_and_bounded_transient_transport_cover_query_and_named_header() {
        for (marker, injection) in [
            (
                50,
                json!({"type":"header","name":"x-api-key","prefix":"Key "}),
            ),
            (51, json!({"type":"query","name":"access_token"})),
        ] {
            let fixture = test_release_cleanup_fixture(marker);
            let mut release =
                ReleaseAuthorizationGuard::new(&fixture.state, fixture.reservation.clone());
            release
                .arm_credential_lease_cleanup(&fixture.scope, &fixture.authorization)
                .expect("arm exact injection-shape cleanup");
            let lease = credential_lease_for_release(
                &fixture.state,
                &fixture.snapshot,
                &test_release_controlled_decision(
                    &fixture.snapshot,
                    &fixture.authorization,
                ),
                &fixture.scope.credential_id,
                7,
            )
            .expect("exact injection-shape secret");
            let policy_url =
                Url::parse("https://example.test/resource").expect("provider policy URL");
            let mut provider_request =
                TransientProviderRequest::new(HeaderMap::new(), policy_url.clone());
            let (headers, transport_url) = provider_request.injection_parts();
            let response_secret_guard =
                apply_credential_injection(headers, transport_url, &injection, &lease)
                    .expect("credential injection shape");
            match injection.get("type").and_then(Value::as_str) {
                Some("header") => assert_eq!(
                    provider_request
                        .headers
                        .get("x-api-key")
                        .and_then(|value| value.to_str().ok()),
                    Some("Key target-one-use-secret")
                ),
                Some("query") => assert_eq!(
                    provider_request
                        .transport_url
                        .query_pairs()
                        .find(|(name, _)| name.as_ref() == "access_token")
                        .map(|(_, value)| value.into_owned())
                        .as_deref(),
                    Some("target-one-use-secret")
                ),
                _ => unreachable!(),
            }
            let builder =
                provider_request.take_builder(&fixture.state.credential_lease_client, Method::GET);
            assert!(provider_request.headers.is_empty());
            assert_eq!(provider_request.transport_url, policy_url);
            assert_eq!(provider_request.policy_url(), &policy_url);
            drop(builder);
            drop(response_secret_guard);
            drop(lease);
            release.stage = ReleaseAuthorizationStage::Completed;
            drop(release);
            assert_only_exact_release_secret_removed(&fixture);
        }
    }

    #[test]
    fn release_secret_raii_covers_injection_dispatch_transport_and_response_failures() {
        {
            let fixture = test_release_cleanup_fixture(52);
            let mut release =
                ReleaseAuthorizationGuard::new(&fixture.state, fixture.reservation.clone());
            release
                .arm_credential_lease_cleanup(&fixture.scope, &fixture.authorization)
                .expect("arm injection failure cleanup");
            let lease = credential_lease_for_release(
                &fixture.state,
                &fixture.snapshot,
                &test_release_controlled_decision(
                    &fixture.snapshot,
                    &fixture.authorization,
                ),
                &fixture.scope.credential_id,
                7,
            )
            .expect("injection failure secret");
            let mut provider_request = TransientProviderRequest::new(
                HeaderMap::new(),
                Url::parse("https://example.test/resource").expect("provider URL"),
            );
            let (headers, url) = provider_request.injection_parts();
            assert!(apply_credential_injection(
                headers,
                url,
                &json!({"type":"header","name":"x-serverware-secret"}),
                &lease,
            )
            .err()
            .expect("reserved injection header must fail")
            .contains("reserved for Serverware internals"));
            drop(lease);
            drop(release);
            assert_only_exact_release_secret_removed(&fixture);
        }

        {
            let fixture = test_release_cleanup_fixture(53);
            let mut release =
                ReleaseAuthorizationGuard::new(&fixture.state, fixture.reservation.clone());
            release
                .arm_credential_lease_cleanup(&fixture.scope, &fixture.authorization)
                .expect("arm dispatch uncertainty cleanup");
            release.stage = ReleaseAuthorizationStage::DispatchUncertain;
            drop(release);
            assert_only_exact_release_secret_removed(&fixture);
        }

        {
            let fixture = test_release_cleanup_fixture(54);
            let mut release =
                ReleaseAuthorizationGuard::new(&fixture.state, fixture.reservation.clone());
            release
                .arm_credential_lease_cleanup(&fixture.scope, &fixture.authorization)
                .expect("arm provider transport failure cleanup");
            release.stage = ReleaseAuthorizationStage::Dispatching;
            let lease = credential_lease_for_release(
                &fixture.state,
                &fixture.snapshot,
                &test_release_controlled_decision(
                    &fixture.snapshot,
                    &fixture.authorization,
                ),
                &fixture.scope.credential_id,
                7,
            )
            .expect("provider transport failure secret");
            let binding = credential_lease_release_binding(&lease);
            let closed_listener =
                TcpListener::bind("127.0.0.1:0").expect("closed provider listener");
            let closed_address = closed_listener
                .local_addr()
                .expect("closed provider address");
            drop(closed_listener);
            let mut provider_request = TransientProviderRequest::new(
                HeaderMap::new(),
                Url::parse(&format!("http://{closed_address}/resource"))
                    .expect("closed provider URL"),
            );
            let (headers, url) = provider_request.injection_parts();
            let response_secret_guard = apply_credential_injection(
                headers,
                url,
                &json!({"type":"bearer"}),
                &lease,
            )
            .expect("provider transport credential injection");
            let builder =
                provider_request.take_builder(&fixture.state.credential_lease_client, Method::GET);
            assert!(matches!(
                send_upstream_request_with_current_lease(
                    &fixture.state,
                    &fixture.snapshot,
                    Some(&binding),
                    builder,
                    UpstreamSendDeadlines {
                        reservation_expires_at_epoch_ms: fixture
                            .reservation
                            .reservation_expires_at_epoch_ms,
                        dispatch_expires_at_epoch_ms: fixture
                            .reservation
                            .reservation_expires_at_epoch_ms,
                        policy_expires_at_epoch_ms: None,
                    },
                    false,
                ),
                Err(UpstreamSendError::Request(_))
            ));
            drop(response_secret_guard);
            drop(lease);
            drop(release);
            assert_only_exact_release_secret_removed(&fixture);
        }

        {
            let fixture = test_release_cleanup_fixture(55);
            let mut release =
                ReleaseAuthorizationGuard::new(&fixture.state, fixture.reservation.clone());
            release
                .arm_credential_lease_cleanup(&fixture.scope, &fixture.authorization)
                .expect("arm response rejection cleanup");
            release.stage = ReleaseAuthorizationStage::Completed;
            let mut response_secret_guard = ResponseSecretGuard::default();
            response_secret_guard.add_text_encodings("target-one-use-secret");
            let decision = json!({
                "principal_id":"agent:test",
                "route_id":"route:test",
                "policy_hash":fixture.snapshot.hash,
                "snapshot_epoch":fixture.snapshot.epoch,
                "request_digest":"sha256:request",
                "operation_digest":"sha256:operation",
                "operation":{"operation":"test.read"},
            });
            let provider_url =
                Url::parse("https://example.test/resource").expect("provider response URL");
            let response = test_reqwest_response(http_response(
                "200 OK",
                json!({"echo":"target-one-use-secret"}),
            ));
            let finalized = finalize_upstream_response(
                &fixture.state,
                &fixture.snapshot,
                &decision,
                "GET",
                &provider_url,
                response,
                &response_secret_guard,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                false,
            );
            let ForwardResult::Buffered(finalized) = finalized else {
                panic!("reflected credential response unexpectedly streamed");
            };
            let finalized =
                String::from_utf8(finalized.to_vec()).expect("credential reflection response");
            assert!(
                finalized.contains("response_credential_reflection"),
                "{finalized}"
            );
            assert!(fixture
                .state
                .credential_leases
                .lock()
                .expect("credential lease cache")
                .contains_key(&CredentialLeaseCacheKey::new_bound(
                    &fixture.scope,
                    Some(&fixture.request_authority),
                    Some(&fixture.authorization),
                )));
            drop(response_secret_guard);
            drop(release);
            assert_only_exact_release_secret_removed(&fixture);
        }
    }

    #[test]
    fn successful_release_controlled_forwarding_uses_exact_secret_and_cleans_terminal_cache() {
        let response_signing_key = SigningKey::from_bytes(&[108u8; 32]);
        let provider_listener =
            TcpListener::bind("127.0.0.1:0").expect("provider listener");
        let provider_address = provider_listener
            .local_addr()
            .expect("provider listener address");
        let credential_listener =
            TcpListener::bind("127.0.0.1:0").expect("credential listener");
        let credential_address = credential_listener
            .local_addr()
            .expect("credential listener address");
        let release_listener =
            TcpListener::bind("127.0.0.1:0").expect("release listener");
        let release_address = release_listener
            .local_addr()
            .expect("release listener address");

        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.hash = sha256_prefixed(b"complete-release-controlled-forward-policy");
        snapshot_value
            .attested_response_context
            .as_mut()
            .expect("attested response context")
            .policy_bundle_digest = snapshot_value.hash.clone();
        let route = &mut snapshot_value.routes[0];
        route.scheme = "http".to_string();
        route.host = "bound-provider.invalid".to_string();
        route.port = provider_address.port();
        route.credential_ref = Some("credential:test".to_string());
        route.jit = json!({
            "required":true,
            "ttlSeconds":30,
            "maxUses":1,
        });
        snapshot_value.credentials.insert(
            "credential:test".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        let snapshot = Arc::new(snapshot_value);
        let request_order = Arc::new(Mutex::new(Vec::new()));
        let reservation_expires_at =
            u64::try_from(now_epoch_ms()).expect("current epoch") + 30_000;

        let release_order = Arc::clone(&request_order);
        let release_snapshot = Arc::clone(&snapshot);
        let release_server = thread::spawn(move || {
            let mut captured = Vec::new();
            let mut attempt_id = None;
            let mut binding_digest = None;
            let mut dispatch_started_at = None;
            let mut dispatch_expires_at = None;
            for step in ["reserve", "dispatch", "complete"] {
                let (mut stream, _) = release_listener.accept().expect("release request");
                let head =
                    read_request_head_from(&mut stream, None).expect("release request head");
                let request = read_request_body_from_head(
                    &mut stream,
                    head,
                    MAX_MANAGEMENT_REQUEST_BODY_BYTES,
                )
                .expect("release request body");
                let payload =
                    strict_json_value_from_slice(&request.body).expect("release request JSON");
                release_order
                    .lock()
                    .expect("request order")
                    .push(step);
                let response_body = match step {
                    "reserve" => {
                        assert_eq!(
                            payload["apiVersion"],
                            "serverware.releaseAuthorizationReserve/v1"
                        );
                        let current_attempt = payload["attemptId"]
                            .as_str()
                            .expect("reserve attempt ID")
                            .to_string();
                        let current_binding =
                            test_release_binding_digest(&payload, true, json!([]));
                        attempt_id = Some(current_attempt.clone());
                        binding_digest = Some(current_binding.clone());
                        json!({
                            "apiVersion":"serverware.releaseAuthorization/v1",
                            "ok":true,
                            "authorized":true,
                            "state":"reserved",
                            "reason":"reserved",
                            "attemptId":current_attempt,
                            "bindingDigest":current_binding,
                            "idempotentReplay":false,
                            "grantId":"grant:forward",
                            "approvalRequestId":"approval:forward",
                            "reservationExpiresAtEpochMs":reservation_expires_at,
                            "dispatchStartedAtEpochMs":null,
                            "dispatchExpiresAtEpochMs":null,
                            "completionOutcome":null,
                            "retryAfterSeconds":0,
                            "quotas":[],
                            "store":{"backend":"postgres","ha":true},
                        })
                    }
                    "dispatch" => {
                        assert_eq!(
                            payload["apiVersion"],
                            "serverware.releaseAuthorizationDispatch/v1"
                        );
                        assert_eq!(payload["attemptId"], attempt_id.as_deref().unwrap());
                        assert_eq!(
                            payload["bindingDigest"],
                            binding_digest.as_deref().unwrap()
                        );
                        let current_dispatch_started_at =
                            u64::try_from(now_epoch_ms()).expect("dispatch epoch");
                        let current_dispatch_expires_at =
                            current_dispatch_started_at + 10_000;
                        dispatch_started_at = Some(current_dispatch_started_at);
                        dispatch_expires_at = Some(current_dispatch_expires_at);
                        json!({
                            "apiVersion":"serverware.releaseAuthorization/v1",
                            "ok":true,
                            "authorized":true,
                            "state":"dispatching",
                            "reason":"dispatching",
                            "attemptId":attempt_id.as_deref().unwrap(),
                            "bindingDigest":binding_digest.as_deref().unwrap(),
                            "idempotentReplay":false,
                            "grantId":"grant:forward",
                            "approvalRequestId":"approval:forward",
                            "reservationExpiresAtEpochMs":reservation_expires_at,
                            "dispatchStartedAtEpochMs":dispatch_started_at,
                            "dispatchExpiresAtEpochMs":dispatch_expires_at,
                            "completionOutcome":null,
                            "retryAfterSeconds":0,
                            "quotas":[],
                            "store":{"backend":"postgres","ha":true},
                        })
                    }
                    "complete" => {
                        assert_eq!(
                            payload["apiVersion"],
                            "serverware.releaseAuthorizationComplete/v1"
                        );
                        assert_eq!(payload["attemptId"], attempt_id.as_deref().unwrap());
                        assert_eq!(
                            payload["bindingDigest"],
                            binding_digest.as_deref().unwrap()
                        );
                        assert_eq!(payload["outcome"], "forwarded");
                        json!({
                            "apiVersion":"serverware.releaseAuthorization/v1",
                            "ok":true,
                            "authorized":true,
                            "state":"committed",
                            "reason":"committed",
                            "attemptId":attempt_id.as_deref().unwrap(),
                            "bindingDigest":binding_digest.as_deref().unwrap(),
                            "idempotentReplay":false,
                            "grantId":"grant:forward",
                            "approvalRequestId":"approval:forward",
                            "reservationExpiresAtEpochMs":reservation_expires_at,
                            "dispatchStartedAtEpochMs":dispatch_started_at,
                            "dispatchExpiresAtEpochMs":dispatch_expires_at,
                            "completionOutcome":"forwarded",
                            "retryAfterSeconds":0,
                            "quotas":[],
                            "store":{"backend":"postgres","ha":true},
                        })
                    }
                    _ => unreachable!(),
                };
                let response = signed_release_test_response(
                    &response_signing_key,
                    &release_snapshot,
                    &request,
                    StatusCode::OK,
                    response_body,
                );
                stream.write_all(&response).expect("release response");
                captured.push(payload);
            }
            captured
        });

        let credential_order = Arc::clone(&request_order);
        let credential_snapshot = Arc::clone(&snapshot);
        let credential_signing_key = SigningKey::from_bytes(&[108u8; 32]);
        let credential_server = thread::spawn(move || {
            let (mut stream, _) = credential_listener
                .accept()
                .expect("dispatch credential request");
            let head =
                read_request_head_from(&mut stream, None).expect("credential request head");
            let request =
                read_request_body_from_head(&mut stream, head, MAX_CREDENTIAL_LEASE_RESPONSE_BYTES)
                    .expect("credential request body");
            let payload =
                strict_json_value_from_slice(&request.body).expect("credential request JSON");
            credential_order
                .lock()
                .expect("request order")
                .push("credential");
            let response_nonce = request
                .headers
                .get("x-serverware-response-nonce")
                .expect("credential response nonce");
            let response = signed_encrypted_dispatch_credential_response(
                &credential_signing_key,
                &credential_snapshot,
                &request,
                response_nonce,
                "exact-bound-forward-secret",
                7,
                BTreeMap::new(),
            );
            stream
                .write_all(&response)
                .expect("signed credential response");
            payload
        });

        let provider_order = Arc::clone(&request_order);
        let provider_server = thread::spawn(move || {
            let (mut stream, _) = provider_listener.accept().expect("provider request");
            let request =
                read_request_head_from(&mut stream, None).expect("provider request head");
            provider_order
                .lock()
                .expect("request order")
                .push("provider");
            stream
                .write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 13\r\nConnection: close\r\n\r\n{\"safe\":true}",
                )
                .expect("provider response");
            request
        });

        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        state.release_authorization_base_url = Some(format!(
            "http://{release_address}/api/data-plane/release-authorizations"
        ));
        state.release_authorization_token = Some("release-token".to_string());
        state.credential_lease_url = Some(format!(
            "http://{credential_address}/api/data-plane/credential-leases"
        ));
        state.credential_lease_token = Some("credential-token".to_string());
        state.upstream_resolver = Arc::new(SequencedUpstreamResolver::new(vec![Ok(vec![
            provider_address,
        ])]));
        let scope =
            CredentialLeaseScope::new("agent:test", "route:test", "credential:test");
        state
            .credential_generations
            .lock()
            .expect("credential generations")
            .insert(
                scope.clone(),
                test_credential_generation(&snapshot, 7, BTreeMap::new()),
            );

        let response = forward_absolute_request_inner(
            &state,
            &snapshot,
            IncomingRequest {
                method: "GET".to_string(),
                target: format!(
                    "http://bound-provider.invalid:{}/resource",
                    provider_address.port()
                ),
                headers: BTreeMap::new(),
                body: Vec::new(),
                client_ip: None,
            },
            Some("agent:test"),
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        );
        let ForwardResult::Buffered(response) = response else {
            panic!("release-controlled response unexpectedly streamed");
        };
        let response = String::from_utf8(response.to_vec()).expect("forwarding response");
        assert!(response.starts_with("HTTP/1.1 200"), "{response}");

        let release_payloads = release_server.join().expect("release server");
        let credential_payload = credential_server.join().expect("credential server");
        let provider_request = provider_server.join().expect("provider server");
        assert_eq!(
            *request_order.lock().expect("request order"),
            vec!["reserve", "credential", "dispatch", "provider", "complete"]
        );
        assert_eq!(
            credential_payload["releaseAuthorization"]["attemptId"],
            release_payloads[0]["attemptId"]
        );
        assert_eq!(
            credential_payload["releaseAuthorization"]["bindingDigest"],
            test_release_binding_digest(&release_payloads[0], true, json!([]))
        );
        assert_eq!(
            provider_request
                .headers
                .get("authorization")
                .map(String::as_str),
            Some("Bearer exact-bound-forward-secret")
        );
        assert_eq!(release_payloads[2]["outcome"], "forwarded");
        assert!(state
            .credential_leases
            .lock()
            .expect("credential lease cache")
            .is_empty());
        assert_eq!(
            state
                .credential_generations
                .lock()
                .expect("credential generations")
                .get(&scope)
                .map(|generation| generation.version),
            Some(7),
            "only the request-scoped secret is evicted"
        );
    }

    #[test]
    fn non_jit_atomic_shared_quota_fetches_secret_only_with_reserved_authority() {
        let response_signing_key = SigningKey::from_bytes(&[107u8; 32]);
        let mut snapshot_value =
            (*test_snapshot_with_control_plane_response_key(1, &response_signing_key)).clone();
        snapshot_value.credentials.insert(
            "credential".to_string(),
            Credential {
                provider: "generic".to_string(),
                provider_subject: None,
                injection: json!({"type":"bearer"}),
            },
        );
        snapshot_value.routes[0].credential_ref = Some("credential".to_string());
        snapshot_value.routes[0].constraints = vec![json!({
            "id":"shared-minute",
            "type":"rateLimit",
            "max":1,
            "windowSeconds":60,
            "store":"shared",
        })];
        let snapshot = Arc::new(snapshot_value);
        let mut state = test_gate_state(Arc::clone(&snapshot));
        state.atomic_release_authorization_enabled = true;
        let scope = CredentialLeaseScope::new("agent:test", "route:test", "credential");
        assert!(
            credential_lease_background_candidates(&state, &snapshot, Duration::from_secs(1))
                .is_empty(),
            "cold non-JIT atomic quota scope must not fetch credential material"
        );
        state
            .credential_lease_activity
            .lock()
            .expect("credential lease activity")
            .insert(scope.clone(), Instant::now());
        state
            .credential_generations
            .lock()
            .expect("credential generations")
            .insert(
                scope.clone(),
                test_credential_generation(&snapshot, 7, BTreeMap::new()),
            );

        assert!(
            credential_lease_background_candidates(&state, &snapshot, Duration::from_secs(1))
                .is_empty(),
            "hot non-JIT atomic quota scope must not prefetch dispatch secret"
        );
        assert!(state
            .credential_leases
            .lock()
            .expect("credential leases")
            .is_empty());

        let listener = TcpListener::bind("127.0.0.1:0").expect("credential listener");
        let address = listener.local_addr().expect("credential listener address");
        state.credential_lease_url = Some(format!(
            "http://{address}/api/data-plane/credential-leases"
        ));
        state.credential_lease_token = Some("credential-token".to_string());
        let unreserved_error = refresh_scoped_credential_material_singleflight(
            &state,
            &snapshot,
            &scope,
            CredentialLeasePurpose::DispatchSecret,
            None,
        )
        .expect_err("release-controlled secret fetch requires a reservation");
        assert!(unreserved_error
            .contains("controlled credential dispatch requires exact request authority"));
        listener
            .set_nonblocking(true)
            .expect("credential listener nonblocking");
        assert!(matches!(
            listener.accept(),
            Err(error) if error.kind() == io::ErrorKind::WouldBlock
        ));
        listener
            .set_nonblocking(false)
            .expect("credential listener blocking");
        let captured = Arc::new(Mutex::new(None));
        let captured_request = Arc::clone(&captured);
        let server_snapshot = Arc::clone(&snapshot);
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("dispatch credential request");
            let head = read_request_head_from(&mut stream, None).expect("credential request head");
            let request =
                read_request_body_from_head(&mut stream, head, MAX_CREDENTIAL_LEASE_RESPONSE_BYTES)
                    .expect("credential request body");
            let payload =
                strict_json_value_from_slice(&request.body).expect("credential request JSON");
            *captured_request.lock().expect("captured credential request") = Some(payload);
            let response_nonce = request
                .headers
                .get("x-serverware-response-nonce")
                .expect("credential response nonce");
            let response = signed_encrypted_dispatch_credential_response(
                &response_signing_key,
                &server_snapshot,
                &request,
                response_nonce,
                "atomic-reservation-token",
                7,
                BTreeMap::new(),
            );
            stream
                .write_all(&response)
                .expect("signed credential response");
        });
        let release_now_ms = u64::try_from(now_epoch_ms()).expect("current epoch");
        let reservation = ReleaseAuthorizationReservation {
            profile: ReleaseProfile::Legacy,
            preparation: None,
            attempt_id: format!("sha256:{}", "a".repeat(64)),
            binding_digest: format!("sha256:{}", "b".repeat(64)),
            principal_id: "agent:test".to_string(),
            route_id: "route:test".to_string(),
            credential_id: "credential".to_string(),
            credential_version: 7,
            policy_hash: snapshot.hash.clone(),
            request_digest: format!("sha256:{}", "c".repeat(64)),
            operation_digest: Some(format!("sha256:{}", "d".repeat(64))),
            operation_context: Some(json!({"operation":"resource.read"})),
            grant_id: None,
            approval_request_id: None,
            reservation_expires_at_epoch_ms: Some(
                release_now_ms + 30_000,
            ),
            shared_quotas: vec![ValidatedReleaseAuthorizationQuota {
                binding: ReleaseAuthorizationBindingQuota {
                    counter_key: format!("sha256:{}", "e".repeat(64)),
                    constraint_id: "shared-minute".to_string(),
                    operation: Some("resource.read".to_string()),
                    window_kind: RateLimitWindowKind::Fixed,
                    window_seconds: Some(60),
                    max_count: 1,
                },
                window_start_epoch_ms: release_now_ms.saturating_sub(1_000),
                window_end_epoch_ms: release_now_ms + 59_000,
                count: 1,
                remaining: 0,
            }],
            durable_policy: None,
            dispatch_started_at_epoch_ms: None,
            dispatch_expires_at_epoch_ms: None,
        };
        let request_authority = reservation
            .credential_lease_request_authority()
            .expect("validated request authority");
        let release_authorization = reservation
            .credential_lease_authorization()
            .expect("validated reserved credential authority")
            .expect("shared quota requires atomic credential authority");
        let lease_info = ensure_scoped_credential_lease_bound(
            &state,
            &snapshot,
            &scope,
            Some(&request_authority),
            Some(&release_authorization),
        )
        .expect("reserved non-JIT authority fetches a dispatch secret");
        assert_eq!(lease_info.version, 7);
        assert!(lease_info.secret_available);
        server.join().expect("credential server");
        let request = captured
            .lock()
            .expect("captured credential request")
            .clone()
            .expect("post-reserve credential request");
        assert_eq!(request["purpose"], "dispatchSecret");
        assert_eq!(request["apiVersion"], "serverware.credentialLeaseRequest/v4");
        assert_eq!(
            request["requestAuthority"],
            serde_json::to_value(&request_authority).expect("serialize request authority")
        );
        assert_eq!(request["releaseAuthorization"]["attemptId"], reservation.attempt_id);
        assert_eq!(
            request["releaseAuthorization"]["bindingDigest"],
            reservation.binding_digest
        );
        assert_eq!(
            request["releaseAuthorization"]["kind"],
            "atomicReservation"
        );

        let decision = json!({
            "allowed":true,
            "principal_id":"agent:test",
            "route_id":"route:test",
            "policy_hash":snapshot.hash,
            "snapshot_epoch":snapshot.epoch,
            "jit":{"required":false},
            "release_authorization":{
                "credential_lease_request_authority":request_authority,
                "credential_lease_authorization":release_authorization.clone(),
            },
        });
        let lease = credential_lease_for_release(
            &state,
            &snapshot,
            &decision,
            "credential",
            7,
        )
        .expect("cached lease remains bound to the atomic reservation");
        let binding = credential_lease_release_binding(&lease);
        let provider_listener =
            TcpListener::bind("127.0.0.1:0").expect("provider listener");
        let provider_address = provider_listener
            .local_addr()
            .expect("provider listener address");
        let provider = thread::spawn(move || {
            let (mut stream, _) =
                provider_listener.accept().expect("provider request");
            let request =
                read_request_head_from(&mut stream, None).expect("provider request head");
            stream
                .write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 13\r\nConnection: close\r\n\r\n{\"safe\":true}",
                )
                .expect("provider response");
            request
        });
        let mut provider_url =
            Url::parse(&format!("http://{provider_address}/resource"))
                .expect("provider URL");
        let mut provider_headers = HeaderMap::new();
        let _response_secret_guard = apply_credential_injection(
            &mut provider_headers,
            &mut provider_url,
            &snapshot.credentials["credential"].injection,
            &lease,
        )
        .expect("atomic credential injection");
        let response = send_upstream_request_with_current_lease(
            &state,
            &snapshot,
            Some(&binding),
            state
                .credential_lease_client
                .get(provider_url)
                .headers(provider_headers),
            UpstreamSendDeadlines {
                reservation_expires_at_epoch_ms: reservation
                    .reservation_expires_at_epoch_ms,
                dispatch_expires_at_epoch_ms: Some(release_now_ms + 20_000),
                policy_expires_at_epoch_ms: None,
            },
            false,
        )
        .expect("atomic reservation forwarding branch");
        assert_eq!(response.status(), StatusCode::OK);
        let provider_request = provider.join().expect("provider server");
        assert_eq!(
            provider_request.headers.get("authorization").map(String::as_str),
            Some("Bearer atomic-reservation-token")
        );

        let generation = state
            .credential_generations
            .lock()
            .expect("credential generation")
            .get(&scope)
            .cloned()
            .expect("credential generation remains cached");
        let mut wrong_scope = release_authorization.clone();
        wrong_scope.route_id = "route:other".to_string();
        assert!(validate_credential_lease_release_scope(
            &snapshot,
            &scope,
            generation.version,
            &wrong_scope,
        )
        .is_err());
        let mut expired = release_authorization.clone();
        expired.reservation_expires_at_epoch_ms =
            release_now_ms.saturating_sub(1);
        assert!(validate_credential_lease_release_authorization(&expired).is_err());
        let mut different_reservation = release_authorization.clone();
        different_reservation.attempt_id =
            format!("sha256:{}", "f".repeat(64));
        different_reservation.reservation_id = release_reservation_id(
            &different_reservation.attempt_id,
            &different_reservation.binding_digest,
        );
        let replay_decision = json!({
            "principal_id":"agent:test",
            "route_id":"route:test",
            "policy_hash":snapshot.hash,
            "snapshot_epoch":snapshot.epoch,
            "jit":{"required":false},
            "release_authorization":{
                "credential_lease_authorization":different_reservation,
            },
        });
        assert!(matches!(
            credential_lease_for_release(
                &state,
                &snapshot,
                &replay_decision,
                "credential",
                7,
            ),
            Err("credential_lease_missing")
        ));
    }

